window.QUIZ_DATA = {"meta":{"exam":{"questions":40,"durationMin":45,"pass":32,"knowledge":28,"situations":12,"mix":{"vivre":6,"histoire":6,"droits":5,"institutions":6,"valeurs":5},"seriesCount":40},"themes":{"vivre":{"label":"Vivre dans la société française","short":"Vivre en société"},"histoire":{"label":"Histoire, géographie et culture","short":"Histoire et culture"},"droits":{"label":"Droits et devoirs","short":"Droits et devoirs"},"institutions":{"label":"Système institutionnel et politique","short":"Institutions"},"valeurs":{"label":"Principes et valeurs de la République","short":"Valeurs de la République"},"situation":{"label":"Mises en situation","short":"Mises en situation"}},"generatedAt":"2026-09-17","counts":{"vivre":72,"histoire":129,"droits":68,"institutions":78,"valeurs":58,"situation":67},"total":472,"sources":{"site":228,"sujet":244}},"questions":[{"id":"SC-001","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quelle est la devise de la République française ?","options":["Liberté, Égalité, Fraternité","Travail, Famille, Patrie","Paix, Justice, Progrès","Unité, Force, Honneur"],"correct":0,"why":"C’est la devise officielle, inscrite à l’article 2 de la Constitution, héritée de la Révolution de 1789. Piège : « Travail, Famille, Patrie » était la devise du régime de Vichy (1940-1944) — piège classique ! Complément : La devise est inscrite à l'article 2 de la Constitution ; elle apparaît sur les bâtiments publics et les pièces de monnaie.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-002","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Où peut-on voir la devise de la République ?","options":["Sur les bâtiments publics (mairies, écoles, tribunaux)","Uniquement sur les billets de banque","Dans les églises","Sur les plaques d’immatriculation"],"correct":0,"why":"À retenir : « Liberté, Égalité, Fraternité » figure sur les édifices publics (mairies, écoles, tribunaux) et dans les documents administratifs. « Liberté, Égalité, Fraternité » est inscrite sur le fronton des bâtiments publics.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-003","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quelles sont les couleurs du drapeau français ?","options":["Bleu, blanc, rouge","Rouge, jaune, vert","Bleu, jaune, rouge","Bleu, blanc, vert"],"correct":0,"why":"Le drapeau tricolore bleu-blanc-rouge est l’emblème national depuis la Révolution.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-004","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quel est le nom de l’hymne national français ?","options":["La Marseillaise","Le Chant du départ","L’Ode à la Joie","La Parisienne"],"correct":0,"why":"La Marseillaise, composée par Rouget de Lisle en 1792. L’Ode à la Joie est l’hymne… européen.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-005","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qui a composé la Marseillaise ?","options":["Rouget de Lisle","Victor Hugo","Beethoven","Mozart"],"correct":0,"why":"Claude Joseph Rouget de Lisle, officier, l’a composée à Strasbourg en avril 1792. Beethoven a composé l’hymne européen.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-006","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Complétez : « Allons enfants de la patrie… »","options":["… le jour de gloire est arrivé","… la victoire est à nous","… le soleil se lève","… la République nous appelle"],"correct":0,"why":"C’est le premier vers de la Marseillaise, composée en 1792.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-007","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qui est Marianne ?","options":["La figure symbolique de la République française","La première reine de France","Une héroïne de la guerre de 1914","L’épouse de Napoléon"],"correct":0,"why":"Marianne est une figure imaginaire : son buste trône dans toutes les mairies. Elle porte le bonnet phrygien, symbole de liberté. Piège : Jeanne d’Arc et Simone Veil sont des personnalités réelles, pas le symbole de la République.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-008","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Que porte Marianne sur la tête ?","options":["Le bonnet phrygien","Une couronne royale","Un casque de guerre","Un chapeau de paille"],"correct":0,"why":"Le bonnet phrygien : dans l’Antiquité, il était porté par les esclaves libérés. Il symbolise donc la liberté.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-009","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Sur quel document peut-on voir Marianne ?","options":["Sur les timbres, les pièces de monnaie et les documents officiels","Uniquement sur le passeport","Sur les plaques de rue","Sur les billets d’avion"],"correct":0,"why":"À retenir : Marianne figure sur les documents administratifs de la République : cartes d'identité, passeports, timbres, et dans toutes les mairies. Marianne est partout : timbres-poste, pièces, cartes officielles… et son buste dans les mairies.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-010","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quel animal symbolise traditionnellement la France ?","options":["Le coq","L’aigle","L’ours","Le lion"],"correct":0,"why":"Le coq gaulois ! En latin, « gallus » désignait à la fois le coq et le Gaulois. Il figure sur les maillots de sport.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-011","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Lequel de ces éléments n’est PAS un symbole officiel inscrit dans la Constitution ?","options":["Le coq","Le drapeau tricolore","La Marseillaise","La devise Liberté, Égalité, Fraternité"],"correct":0,"why":"L’article 2 cite le drapeau, l’hymne et la devise. Le coq et Marianne sont des symboles traditionnels, pas constitutionnels.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-012","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quelle est la date de la fête nationale française ?","options":["Le 14 juillet","Le 4 juillet","Le 11 novembre","Le 1er mai"],"correct":0,"why":"Le 14 juillet : prise de la Bastille (1789) et fête de la Fédération (1790). Chaque année : défilé, bals et feux d’artifice. Piège : Le 4 juillet, c’est la fête nationale… américaine. Piège fréquent !","themeLabel":"Principes et valeurs de la République"},{"id":"SC-013","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qu’est-ce qui est traditionnellement organisé le 14 juillet sur les Champs-Élysées ?","options":["Un défilé militaire","Un carnaval","Un marché de Noël","Une course cycliste"],"correct":0,"why":"Le défilé militaire du 14 juillet descend les Champs-Élysées chaque année devant le président de la République.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-014","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Peut-on brûler publiquement un drapeau français ?","options":["Non, c’est un délit puni par la loi","Oui, c’est la liberté d’expression","Oui, si c’est pour une manifestation","Oui, le dimanche seulement"],"correct":0,"why":"À retenir : L'article 433-5-1 du Code pénal punit l'outrage à l'hymne national ou au drapeau tricolore commis pendant une manifestation organisée ou réglementée. L’outrage au drapeau national est un délit : jusqu’à 1 500 € d’amende. Respecter les symboles, c’est respecter la Nation.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-015","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Que signifie la « fraternité » dans la devise ?","options":["La solidarité entre les citoyens","L’amitié entre voisins seulement","L’amour de la famille","Le partage de l’argent"],"correct":0,"why":"Se voir comme des semblables, membres d’une même communauté : on veille les uns sur les autres.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-016","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Que signifie « égalité » dans la devise républicaine ?","options":["Les mêmes droits et devoirs pour tous, sans distinction","Gagner le même salaire que tout le monde","Porter les mêmes vêtements","Habiter dans le même quartier"],"correct":0,"why":"Mêmes droits, mêmes devoirs, quelle que soit l’origine, le sexe ou la religion (article 1er de la Constitution).","themeLabel":"Principes et valeurs de la République"},{"id":"SC-017","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quelle est la langue officielle de la République française ?","options":["Le français","L’anglais","Il n’y a pas de langue officielle","Le français et le basque"],"correct":0,"why":"L’article 2 de la Constitution : « La langue de la République est le français ».","themeLabel":"Principes et valeurs de la République"},{"id":"SC-018","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qu’est-ce que la laïcité ?","options":["La liberté de croire ou de ne pas croire","L’interdiction de toutes les religions","Une religion officielle de l’État","L’obligation d’être athée"],"correct":0,"why":"La laïcité garantit la liberté de conscience : chacun peut croire, ne pas croire, changer de religion. Piège : La laïcité n’interdit PAS la religion : elle la protège, tout en gardant l’État neutre. Complément : La laïcité protège la liberté de croire ou de ne pas croire, et assure l'égalité des citoyens quelles que soient leurs convictions.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-019","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"En quelle année la loi de séparation des Églises et de l’État a-t-elle été votée ?","options":["1905","1789","1882","1958"],"correct":0,"why":"À retenir : Votée le 9 décembre 1905 et portée par Aristide Briand, elle fonde la laïcité à la française : la République ne reconnaît ni ne salarie aucun culte. Le 9 décembre 1905 : la République ne reconnaît, ne salarie ni ne subventionne aucun culte.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-020","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Que prévoit la loi du 9 décembre 1905 ?","options":["La séparation des Églises et de l’État, la neutralité de l’État et la liberté de conscience","L’école obligatoire","Le droit de vote des femmes","L’abolition de la peine de mort"],"correct":0,"why":"C’est le texte fondateur de la laïcité française : l’État est neutre, chacun est libre de croire.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-021","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quel est le « jour de la laïcité » en France ?","options":["Le 9 décembre","Le 14 juillet","Le 1er janvier","Le 11 novembre"],"correct":0,"why":"Le 9 décembre, anniversaire de la loi de 1905, est la journée de la laïcité.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-022","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Selon la laïcité, que signifie la neutralité de l’État ?","options":["L’État ne privilégie aucune religion et traite tous les citoyens de manière égale","L’État interdit les religions","L’État choisit une religion pour les citoyens","L’État finance toutes les religions"],"correct":0,"why":"Neutre ne veut pas dire hostile : l’État protège la liberté religieuse sans favoriser personne.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-023","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qui doit respecter la neutralité religieuse dans les services publics ?","options":["Les agents publics (fonctionnaires)","Les usagers dans la rue","Les enfants à la maison","Personne"],"correct":0,"why":"Les agents publics ne manifestent pas leur religion au travail. Les usagers, eux, restent libres de leurs tenues.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-024","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Un élève peut-il porter un signe religieux ostensible dans une école publique ?","options":["Non, la loi de 2004 l’interdit dans les écoles publiques","Oui, toujours","Oui, s’il a plus de 15 ans","Seulement le vendredi"],"correct":0,"why":"La loi du 15 mars 2004 interdit les signes religieux ostensibles à l’école publique : l’école reste un espace neutre et apaisé.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-025","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Une personne peut-elle changer librement de religion en France ?","options":["Oui, c’est la liberté de conscience","Non, c’est interdit","Oui, mais avec une autorisation du préfet","Seulement une fois dans sa vie"],"correct":0,"why":"À retenir : La liberté de conscience et de culte est garantie par la Déclaration de 1789, la Constitution et la Convention européenne des droits de l'homme. La liberté de conscience inclut le droit de croire, de ne plus croire ou de changer de religion.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-026","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Comment appelle-t-on une personne qui ne croit en aucun dieu ?","options":["Une personne athée","Une personne pratiquante","Une personne croyante","Une personne laïque"],"correct":0,"why":"Athée = qui ne croit en aucun dieu. La laïcité protège autant les croyants que les athées.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-027","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Quelle institution doit rester neutre en matière de religion ?","options":["L’État et ses services publics (mairies, écoles, hôpitaux, tribunaux)","Les restaurants","Les entreprises privées","Les familles"],"correct":0,"why":"Neutralité pour l’État et ses agents ; liberté pour les citoyens dans l’espace public.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-028","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qu’est-ce que l’antisémitisme ?","options":["Une forme de racisme dirigée contre les personnes juives, punie par la loi","Une religion","Un parti politique","Une fête traditionnelle"],"correct":0,"why":"L’antisémitisme est un délit. Les contenus haineux peuvent être signalés sur la plateforme Pharos.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-029","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qu’est-ce que la liberté d’association ?","options":["Le droit de créer ou de rejoindre librement une association","Le droit de voter","Le droit de grève","Le droit de rester chez soi"],"correct":0,"why":"À retenir : La liberté d'association est un droit fondamental protégé par la Constitution et par la Convention européenne des droits de l'homme. Garantie par la loi du 1er juillet 1901 : culturelle, sportive, caritative… chacun peut s’associer librement.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-030","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"En France, il est possible pour l’État de financer :","options":["Aucun culte (l’État ne salarie ni ne subventionne de religion)","Toutes les religions","Seulement une religion officielle","Les religions majoritaires"],"correct":0,"why":"À retenir : La loi de 1905 interdit de subventionner les cultes, sauf régime particulier en Alsace-Moselle ; les aides publiques ciblées (presse, entreprises) sont encadrées par la loi. Article 2 de la loi de 1905. (Exception historique : l’Alsace-Moselle, restée sous le concordat de 1801.)","themeLabel":"Principes et valeurs de la République"},{"id":"SC-031","theme":"valeurs","source":"site","themeOrigine":"Principes et valeurs","q":"Qu’est-ce que la Charte de la laïcité à l’école (2013) ?","options":["Un document affiché dans les établissements qui rappelle les règles de la laïcité","Un diplôme de fin de collège","Un manuel de religion","Une chanson patriotique"],"correct":0,"why":"Affichée dans toutes les écoles publiques depuis 2013, elle rappelle neutralité, liberté de conscience et refus du prosélytisme.","themeLabel":"Principes et valeurs de la République"},{"id":"SC-032","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quel est le régime politique de la France aujourd’hui ?","options":["La Ve République","Une monarchie","Un Empire","La IVe République"],"correct":0,"why":"La Ve République, fondée en 1958 par le général de Gaulle, est notre régime actuel.","themeLabel":"Système institutionnel et politique"},{"id":"SC-033","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui est élu lors des élections présidentielles ?","options":["Le président de la République","Le Premier ministre","Le maire","Les députés"],"correct":0,"why":"Le président est élu au suffrage universel direct par tous les électeurs inscrits.","themeLabel":"Système institutionnel et politique"},{"id":"SC-034","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Pour combien de temps le président de la République est-il élu ?","options":["5 ans","7 ans","4 ans","6 ans"],"correct":0,"why":"5 ans : c’est le « quinquennat », en place depuis le référendum de 2000 (avant : 7 ans).","themeLabel":"Système institutionnel et politique"},{"id":"SC-035","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Où réside le président de la République ?","options":["Au palais de l’Élysée","À l’hôtel de Matignon","Au palais du Luxembourg","Au château de Versailles"],"correct":0,"why":"L’Élysée = le président. Matignon = le Premier ministre. Le Luxembourg = le Sénat. Bien distinguer !","themeLabel":"Système institutionnel et politique"},{"id":"SC-036","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui dirige l’action du Gouvernement ?","options":["Le Premier ministre","Le président de la République","Le maire de Paris","Le préfet"],"correct":0,"why":"À retenir : Art. 21 de la Constitution : le Premier ministre dirige l'action du gouvernement ; le président préside le Conseil des ministres et fixe les grandes orientations. Article 21 de la Constitution : le Premier ministre dirige l’action du Gouvernement et veille à l’exécution des lois.","themeLabel":"Système institutionnel et politique"},{"id":"SC-037","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui est élu lors des élections législatives ?","options":["Les députés","Le président","Les maires","Les sénateurs"],"correct":0,"why":"À retenir : Les législatives désignent les 577 députés de l'Assemblée nationale ; les sénateurs sont élus par les grands électeurs. Les législatives élisent les députés, qui siègent à l’Assemblée nationale au palais Bourbon.","themeLabel":"Système institutionnel et politique"},{"id":"SC-038","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Combien de députés composent l’Assemblée nationale ?","options":["577","348","300","650"],"correct":0,"why":"577 députés à l’Assemblée nationale. Astuce mémo : le Sénat compte 348 sénateurs, les deux ensemble = le Parlement. Piège : 348, c’est le nombre de sénateurs au Sénat — le piège préféré de l’examen !","themeLabel":"Système institutionnel et politique"},{"id":"SC-039","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Pour combien de temps les députés sont-ils élus ?","options":["5 ans","6 ans","4 ans","7 ans"],"correct":0,"why":"Députés : 5 ans. Sénateurs : 6 ans. Maires et conseils municipaux : 6 ans. Président : 5 ans.","themeLabel":"Système institutionnel et politique"},{"id":"SC-040","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Pour combien de temps les sénateurs sont-ils élus ?","options":["6 ans","5 ans","9 ans","4 ans"],"correct":0,"why":"6 ans, renouvelés par moitié tous les 3 ans. Ils siègent au palais du Luxembourg.","themeLabel":"Système institutionnel et politique"},{"id":"SC-041","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Comment les sénateurs sont-ils élus ?","options":["Au suffrage universel indirect, par des grands électeurs","Au suffrage universel direct","Par le président","Par tirage au sort"],"correct":0,"why":"Les sénateurs sont choisis par un collège de grands électeurs (élus locaux) : suffrage indirect.","themeLabel":"Système institutionnel et politique"},{"id":"SC-042","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui vote les lois ?","options":["Le Parlement (Assemblée nationale et Sénat)","Le président tout seul","Le préfet","Les maires"],"correct":0,"why":"À retenir : La loi est votée par le Parlement ; le gouvernement peut faire des propositions de loi, et le président promulgue la loi après son adoption. Le Parlement, composé de DEUX chambres : l’Assemblée nationale et le Sénat. Le président promulgue ensuite les lois.","themeLabel":"Système institutionnel et politique"},{"id":"SC-043","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui est élu lors des élections municipales ?","options":["Les conseillers municipaux (qui élisent ensuite le maire)","Le maire directement","Le préfet","Les ministres"],"correct":0,"why":"À retenir : Les électeurs élisent les conseillers municipaux pour 6 ans ; lors du premier conseil, ceux-ci élisent le maire et les adjoints. Les habitants élisent les conseillers municipaux ; CEUX-CI choisissent ensuite le maire parmi eux.","themeLabel":"Système institutionnel et politique"},{"id":"SC-044","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Comment le maire d’une commune est-il désigné ?","options":["Élu par le conseil municipal parmi ses membres","Nommé par le président","Élu directement par les habitants","Tiré au sort"],"correct":0,"why":"Les électeurs votent pour une liste de conseillers ; les conseillers élus choisissent leur maire. Mandat de 6 ans.","themeLabel":"Système institutionnel et politique"},{"id":"SC-045","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui représente l’État dans un département ?","options":["Le préfet","Le maire","Le député","Le président de région"],"correct":0,"why":"À retenir : Le préfet représente l'État et le gouvernement dans le département ; le président du conseil départemental administre la collectivité. Le préfet est nommé par l’État : il veille à l’application des lois dans le département. Le maire, lui, dirige la commune.","themeLabel":"Système institutionnel et politique"},{"id":"SC-046","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Combien y a-t-il de départements en France ?","options":["101","96","18","350"],"correct":0,"why":"101 départements : 96 en métropole + 5 d’outre-mer (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte). Piège : 96 = seulement la métropole. 18 = le nombre de régions. Ne pas mélanger ! Complément : 96 départements en métropole (dont 2 en Corse) et 5 départements d'outre-mer, soit 101 au total depuis 2011.","themeLabel":"Système institutionnel et politique"},{"id":"SC-047","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Comment la France est-elle organisée administrativement ?","options":["Communes, départements et régions","Provinces et royaumes","États et cantons","10 grandes provinces"],"correct":0,"why":"≈ 35 000 communes, 101 départements, 18 régions (13 en métropole + 5 outre-mer).","themeLabel":"Système institutionnel et politique"},{"id":"SC-048","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"À quel âge a-t-on le droit de voter en France ?","options":["18 ans","16 ans","21 ans","25 ans"],"correct":0,"why":"La majorité civile et le droit de vote sont à 18 ans. À 16 ans : le recensement citoyen en mairie.","themeLabel":"Système institutionnel et politique"},{"id":"SC-049","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Le vote en France est-il obligatoire ?","options":["Non, c’est un droit civique, pas une obligation","Oui, sous peine d’amende","Oui, pour les présidentielles","Seulement pour les moins de 50 ans"],"correct":0,"why":"Pas d’obligation légale, mais voter est un acte essentiel : c’est la voix du peuple !","themeLabel":"Système institutionnel et politique"},{"id":"SC-050","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"À qui appartient la souveraineté nationale ?","options":["Au peuple, qui l’exerce par ses représentants et par référendum","Au président","À l’armée","Aux riches propriétaires"],"correct":0,"why":"À retenir : Art. 3 de la Constitution : la souveraineté nationale appartient au peuple, qui l'exerce par ses représentants ou par la voie du référendum. Article 3 de la Constitution : le pouvoir vient du peuple — par ses représentants élus ou par référendum.","themeLabel":"Système institutionnel et politique"},{"id":"SC-051","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quels sont les trois pouvoirs séparés dans la République ?","options":["Exécutif, législatif, judiciaire","Police, armée, justice","Maire, préfet, président","Économique, social, culturel"],"correct":0,"why":"Exécutif (applique les lois), législatif (vote les lois), judiciaire (juge). Leur séparation protège nos libertés.","themeLabel":"Système institutionnel et politique"},{"id":"SC-052","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qu’est-ce qu’un État de droit ?","options":["Un État où tous, citoyens et dirigeants, sont soumis à la loi","Un État dirigé par les juges","Un État sans loi","Un État militaire"],"correct":0,"why":"Personne n’est au-dessus de la loi, pas même le président ou les ministres. La justice est indépendante.","themeLabel":"Système institutionnel et politique"},{"id":"SC-053","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Le président de la République a-t-il tous les pouvoirs ?","options":["Non, ses pouvoirs sont limités par la Constitution et la séparation des pouvoirs","Oui, absolument tous","Oui, pendant la guerre","Oui, s’il a la majorité"],"correct":0,"why":"En démocratie, personne n’a tous les pouvoirs : le Parlement vote les lois, la justice juge, le Conseil constitutionnel veille.","themeLabel":"Système institutionnel et politique"},{"id":"SC-054","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui sanctionne l’auteur d’un vol ?","options":["La justice (les tribunaux)","La police","Le maire","Le président"],"correct":0,"why":"À retenir : La police constate les faits et enquête ; seule la justice juge et prononce la sanction (amende, prison selon la gravité). La police enquête, mais seul un juge peut prononcer une sanction : c’est la séparation des pouvoirs.","themeLabel":"Système institutionnel et politique"},{"id":"SC-055","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Peut-on modifier la Constitution ?","options":["Oui, par un vote du Parlement suivi d’un référendum ou d’un vote du Congrès","Non, jamais","Oui, par le président seul","Oui, par un décret du préfet"],"correct":0,"why":"La révision demande l’accord des deux chambres, puis référendum ou Congrès (à Versailles, 3/5 des voix). Exemple : inscrire l’IVG, 2024.","themeLabel":"Système institutionnel et politique"},{"id":"SC-056","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Où s’inscrit-on sur les listes électorales si l’on n’a pas internet ?","options":["À la mairie de sa commune","À la préfecture de police","À la poste","Au commissariat"],"correct":0,"why":"La mairie tient les listes électorales. On peut aussi s’inscrire en ligne sur service-public.fr.","themeLabel":"Système institutionnel et politique"},{"id":"SC-057","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Qui est le Défenseur des droits ?","options":["Une autorité indépendante qui défend les citoyens face aux administrations et lutte contre les discriminations","Un policier de quartier","Un juge d’instruction","Un ministre"],"correct":0,"why":"On peut le saisir gratuitement — par exemple en cas de discrimination à l’embauche ou par une administration.","themeLabel":"Système institutionnel et politique"},{"id":"SC-058","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Combien de pays font partie de l’Union européenne ?","options":["27","28","15","50"],"correct":0,"why":"27 États membres depuis le départ du Royaume-Uni (Brexit, 2020). La France en fait partie.","themeLabel":"Système institutionnel et politique"},{"id":"SC-059","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quel pays est sorti de l’Union européenne en 2020 ?","options":["Le Royaume-Uni","La Suisse","La Turquie","La Norvège"],"correct":0,"why":"Le Brexit : le Royaume-Uni a quitté l’UE en janvier 2020. La Suisse et la Norvège n’ont jamais été membres.","themeLabel":"Système institutionnel et politique"},{"id":"SC-060","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quelle est la devise de l’Union européenne ?","options":["« Unie dans la diversité »","« Liberté, Égalité, Fraternité »","« Un peuple, un but »","« Paix et travail »"],"correct":0,"why":"À retenir : « Unie dans la diversité » est la devise officielle de l'UE depuis 2000 ; la devise de la République française est « Liberté, Égalité, Fraternité ». « Unie dans la diversité » : des peuples unis pour la paix, fiers de leurs cultures différentes.","themeLabel":"Système institutionnel et politique"},{"id":"SC-061","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quel est l’hymne de l’Union européenne ?","options":["L’Ode à la Joie de Beethoven","La Marseillaise","Le Chant des partisans","God Save the King"],"correct":0,"why":"À retenir : Adopté en 1985, l'hymne européen est l'air de l'Ode à la joie ; La Marseillaise est l'hymne français (art. 2 de la Constitution). L’Ode à la Joie (9e symphonie de Beethoven), adopté en 1985. Astuce : UE = Beethoven, France = Rouget de Lisle.","themeLabel":"Système institutionnel et politique"},{"id":"SC-062","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Que représente le drapeau européen ?","options":["12 étoiles dorées en cercle sur fond bleu","27 étoiles sur fond blanc","Une croix rouge","Des rayures bleues et blanches"],"correct":0,"why":"12 étoiles, symbole d’unité — pas le nombre de pays membres ! Astuce : 12 comme les mois de l’année.","themeLabel":"Système institutionnel et politique"},{"id":"SC-063","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Où siège le Parlement européen ?","options":["À Strasbourg","À Paris","À Bruxelles uniquement","À Luxembourg"],"correct":0,"why":"Strasbourg, en France ! (Des travaux ont aussi lieu à Bruxelles.) La Commission européenne, elle, est à Bruxelles.","themeLabel":"Système institutionnel et politique"},{"id":"SC-064","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quel traité a fondé l’Union européenne ?","options":["Le traité de Maastricht (1992)","Le traité de Versailles (1919)","Le traité de Rome seul (1957)","Le traité de Paris (1945)"],"correct":0,"why":"Maastricht, signé en 1992, entré en vigueur en 1993 : naissance de l’UE et de la citoyenneté européenne.","themeLabel":"Système institutionnel et politique"},{"id":"SC-065","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Quand est célébrée la journée de l’Europe ?","options":["Le 9 mai","Le 8 mai","Le 14 juillet","Le 11 novembre"],"correct":0,"why":"À retenir : Le 9 mai commémore la déclaration Schuman du 9 mai 1950, acte de naissance de la construction européenne. Le 9 mai, en souvenir de la déclaration Schuman du 9 mai 1950. (Le 8 mai = victoire de 1945.)","themeLabel":"Système institutionnel et politique"},{"id":"SC-066","theme":"institutions","source":"site","themeOrigine":"Institutions","q":"Les citoyens européens résidant en France peuvent-ils voter aux élections locales ?","options":["Oui, aux élections municipales et européennes","Non, jamais","Oui, à toutes les élections","Uniquement aux présidentielles"],"correct":0,"why":"Ils peuvent voter et être élus conseillers municipaux (mais pas maire). Les élections nationales restent réservées aux Français.","themeLabel":"Système institutionnel et politique"},{"id":"SC-067","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quel texte énonce les droits et devoirs fondamentaux des personnes en France ?","options":["La Déclaration des droits de l’homme et du citoyen","Le Code de la route","La Bible","Le règlement intérieur des écoles"],"correct":0,"why":"La Déclaration des droits de l’homme et du citoyen, adoptée le 26 août 1789 pendant la Révolution. Valeur constitutionnelle.","themeLabel":"Droits et devoirs"},{"id":"SC-068","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"De quelle année date la Déclaration des droits de l’homme et du citoyen ?","options":["1789","1905","1958","1945"],"correct":0,"why":"1789, l’année de la Révolution française. « Les hommes naissent et demeurent libres et égaux en droits » (article 1er).","themeLabel":"Droits et devoirs"},{"id":"SC-069","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quelle citation vient de la Déclaration des droits de l’homme de 1789 ?","options":["« Les hommes naissent et demeurent libres et égaux en droits »","« Travail, famille, patrie »","« Un pour tous, tous pour un »","« Paix aux hommes de bonne volonté »"],"correct":0,"why":"C’est son article 1er — le fondement de l’égalité républicaine.","themeLabel":"Droits et devoirs"},{"id":"SC-070","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"La liberté d’expression, en France, c’est :","options":["Exprimer ses idées librement, dans les limites fixées par la loi","Dire absolument tout, même des insultes racistes","Un droit réservé aux journalistes","Le droit de mentir"],"correct":0,"why":"Liberté réelle MAIS encadrée : la loi interdit la diffamation, l’injure raciste et l’appel à la violence. Mes droits s’arrêtent là où commencent ceux des autres.","themeLabel":"Droits et devoirs"},{"id":"SC-071","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Pour quel motif la liberté d’expression peut-elle être limitée ?","options":["Pour protéger les droits des autres et l’ordre public (haine, diffamation, violence)","Pour empêcher les critiques du gouvernement","Parce qu’un voisin n’est pas d’accord","Elle ne peut jamais être limitée"],"correct":0,"why":"La loi punit la provocation à la haine, la diffamation et l’apologie du terrorisme. On peut critiquer le pouvoir, c’est normal en démocratie !","themeLabel":"Droits et devoirs"},{"id":"SC-072","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"L’article 4 de la Déclaration de 1789 dit que la liberté consiste à « pouvoir faire tout ce qui ne nuit pas à autrui ». Que signifie cela ?","options":["Ma liberté s’arrête où commence celle des autres","Je peux tout faire sans règles","Les autres doivent me laisser tranquille","La liberté n’existe pas"],"correct":0,"why":"Chacun est libre, mais dans le respect des autres et de la loi. C’est le cœur de la vie en société.","themeLabel":"Droits et devoirs"},{"id":"SC-073","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"La peine de mort en France est :","options":["Abolie depuis 1981","Toujours appliquée","Appliquée uniquement pour les crimes graves","Décidée par les préfets"],"correct":0,"why":"Abolie en 1981 sous l’impulsion de Robert Badinter (présidence Mitterrand). La France défend l’abolition universelle.","themeLabel":"Droits et devoirs"},{"id":"SC-074","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Une femme peut-elle voter en France ?","options":["Oui, depuis 1944-1945 comme les hommes","Non","Uniquement si son mari est d’accord","Depuis 2020 seulement"],"correct":0,"why":"Les femmes votent depuis 1945 (droit obtenu en avril 1944). L’égalité des droits est un principe de la République.","themeLabel":"Droits et devoirs"},{"id":"SC-075","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Une femme peut-elle travailler sans l’autorisation de son mari ?","options":["Oui, toujours : les droits ne dépendent pas du mari","Non","Uniquement avec son accord écrit","Seulement à temps partiel"],"correct":0,"why":"Femmes et hommes ont exactement les mêmes droits : travailler, ouvrir un compte, voyager, créer une entreprise.","themeLabel":"Droits et devoirs"},{"id":"SC-076","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Est-il légal d’être marié à plusieurs personnes en même temps en France ?","options":["Non, la polygamie est interdite","Oui, avec une autorisation","Oui, selon certaines religions","Oui, pour les personnes riches"],"correct":0,"why":"Le Code civil impose la monogamie : une seule personne à la fois. La bigamie est un délit.","themeLabel":"Droits et devoirs"},{"id":"SC-077","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Le mariage entre deux personnes de même sexe est :","options":["Légal depuis la loi de 2013","Interdit","Légal seulement à Paris","Toléré mais sans valeur"],"correct":0,"why":"Depuis le 17 mai 2013, le mariage est ouvert aux couples de même sexe, avec les mêmes droits (dont l’adoption).","themeLabel":"Droits et devoirs"},{"id":"SC-078","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"L’avortement (IVG) en France est :","options":["Un droit garanti par la Constitution, pris en charge à 100 %","Interdit","Autorisé seulement avec accord du mari","Réservé aux plus de 30 ans"],"correct":0,"why":"Droit depuis la loi Veil de 1975, inscrit dans la Constitution en mars 2024 — une première mondiale. Remboursé intégralement.","themeLabel":"Droits et devoirs"},{"id":"SC-079","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Qui a fait adopter la loi autorisant l’avortement en 1975 ?","options":["Simone Veil","Marie Curie","Jeanne d’Arc","George Sand"],"correct":0,"why":"Simone Veil, ministre de la Santé et rescapée d’Auschwitz. Elle est entrée au Panthéon en 2018. Piège : Marie Curie = scientifique, prix Nobel. Ne pas confondre — les deux sont tombées à l’examen !","themeLabel":"Droits et devoirs"},{"id":"SC-080","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Le divorce en France est :","options":["Possible, à la demande d’un seul ou des deux époux","Interdit","Réservé aux hommes","Décidé par la famille"],"correct":0,"why":"Depuis 1975, le divorce par consentement mutuel existe. Un seul époux peut aussi divorcer. La loi protège la liberté de chacun.","themeLabel":"Droits et devoirs"},{"id":"SC-081","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Jeter une bouteille ou un mégot dans la rue est :","options":["Interdit et passible d’une amende","Autorisé","Autorisé le week-end","Accepté s’il n’y a pas de poubelle"],"correct":0,"why":"Déposer ses déchets sur la voie publique est une infraction. Respecter l’espace public, c’est le respecter pour tous.","themeLabel":"Droits et devoirs"},{"id":"SC-082","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Pourquoi doit-on trier ses déchets ?","options":["Pour protéger l’environnement et recycler","C’est obligatoire pour les étrangers seulement","Pour payer moins d’impôts","Ce n’est pas obligatoire"],"correct":0,"why":"La Charte de l’environnement (inscrite dans la Constitution) fait de la protection de la planète un devoir d’intérêt général.","themeLabel":"Droits et devoirs"},{"id":"SC-083","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Que doit faire une personne témoin d’un accident ?","options":["Alerter les secours et porter assistance dans la mesure de ses moyens","Continuer sa route","Filmer la scène","Attendre que quelqu’un d’autre agisse"],"correct":0,"why":"La non-assistance à personne en danger est un délit : on appelle le 15 (SAMU), le 18 (pompiers), le 17 (police) ou le 112 (européen).","themeLabel":"Droits et devoirs"},{"id":"SC-084","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quel numéro appelle le SAMU (urgence médicale) ?","options":["Le 15","Le 17","Le 18","Le 12"],"correct":0,"why":"15 = SAMU (médecin). 18 = pompiers. 17 = police. 112 = numéro unique valable dans toute l’Europe. 114 = SMS pour les sourds et malentendants.","themeLabel":"Droits et devoirs"},{"id":"SC-085","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quel numéro appelle la police en France ?","options":["Le 17","Le 15","Le 18","Le 119"],"correct":0,"why":"17 = police/gendarmerie. 119 = enfance en danger. 112 = urgence européenne. À retenir par cœur !","themeLabel":"Droits et devoirs"},{"id":"SC-086","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quel numéro appelle les pompiers ?","options":["Le 18","Le 15","Le 17","Le 112 seulement"],"correct":0,"why":"18 = pompiers (feu, accidents, personne en danger). En Europe entière, le 112 marche aussi partout.","themeLabel":"Droits et devoirs"},{"id":"SC-087","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Face aux ordres des policiers ou gendarmes, il faut :","options":["Obéir et présenter ses documents si demandé","S’enfuir","Discuter leurs ordres","Les ignorer"],"correct":0,"why":"La police et la gendarmerie assurent l’ordre public et notre sécurité. On coopère calmement.","themeLabel":"Droits et devoirs"},{"id":"SC-088","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quel est le rôle de la police et de la gendarmerie ?","options":["Protéger les personnes et les biens, faire respecter la loi","Fabriquer les lois","Gérer les écoles","Dresser les impôts"],"correct":0,"why":"Elles assurent la sécurité et l’ordre public. Ce sont les tribunaux, pas la police, qui punissent.","themeLabel":"Droits et devoirs"},{"id":"SC-089","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Que risque une personne qui ne respecte pas la loi ?","options":["Des sanctions : amendes, voire prison, selon la gravité","Rien du tout","Juste un avertissement amical","Une augmentation d’impôts"],"correct":0,"why":"L’État de droit : la même loi pour tous, et des sanctions proportionnées en cas d’infraction (amende, délit, crime).","themeLabel":"Droits et devoirs"},{"id":"SC-090","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Si l’on considère une loi injuste, on peut :","options":["La contester par les voies légales : recours, manifestations, vote","La désobéir tranquillement","Menacer les élus","Ne plus payer d’impôts"],"correct":0,"why":"On ne choisit pas ses lois : mais la démocratie offre des moyens pacifiques pour les faire changer (vote, pétitions, manifestations, recours).","themeLabel":"Droits et devoirs"},{"id":"SC-091","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Qu’a-t-on le droit de faire en France quelle que soit sa nationalité ?","options":["Bénéficier des droits fondamentaux (dignité, justice, sécurité) et respecter les lois","Voter aux présidentielles","Être maire","Devenir policier"],"correct":0,"why":"Certains droits sont pour tous (vivre dignement, être jugé équitablement…) ; le vote national, lui, est lié à la citoyenneté française.","themeLabel":"Droits et devoirs"},{"id":"SC-092","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Payer ses impôts est :","options":["Un devoir qui finance les services publics pour tous","Une option","Réservé aux riches","Interdit aux femmes"],"correct":0,"why":"Écoles, hôpitaux, routes, sécurité… : l’impôt finance la vie commune. C’est un pilier de la solidarité nationale.","themeLabel":"Droits et devoirs"},{"id":"SC-093","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Le droit de grève est :","options":["Un droit inscrit dans la Constitution, pour défendre ses revendications professionnelles","Interdit","Réservé aux syndicats étrangers","Un délit"],"correct":0,"why":"Droit constitutionnel pour tous les salariés, privés comme publics, dans le cadre prévu par la loi.","themeLabel":"Droits et devoirs"},{"id":"SC-094","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Se syndiquer est :","options":["Un droit pour tous les travailleurs, sans condition de nationalité","Interdit aux étrangers","Réservé aux fonctionnaires","Interdit en entreprise"],"correct":0,"why":"Tout travailleur peut adhérer à un syndicat. Un employeur qui punit un salarié syndiqué commet un délit.","themeLabel":"Droits et devoirs"},{"id":"SC-095","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"Quels biens de l’armée et du pays… Les cimetières militaires et monuments aux morts :","options":["Ils honorent les soldats morts pour la France, on les respecte","Ce sont des parcs de jeux","Ils datent de Napoléon seulement","Ils n’ont aucune importance"],"correct":0,"why":"Respecter la mémoire des morts pour la France fait partie des valeurs de la Nation (ex : l’Arc de triomphe, le 11 novembre).","themeLabel":"Droits et devoirs"},{"id":"SC-096","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"La violence physique ou psychologique envers ses enfants est :","options":["Interdite par la loi depuis 2019","Autorisée pour punir","Légale à la maison","Acceptée dans certaines cultures en France"],"correct":0,"why":"L’article 371-1 du Code civil : l’autorité parentale s’exerce SANS violences physiques ou psychologiques. Le 119 permet de signaler un enfant en danger.","themeLabel":"Droits et devoirs"},{"id":"SC-097","theme":"droits","source":"site","themeOrigine":"Droits et devoirs","q":"La répudiation de sa femme (décider seul de « répudier » son épouse) est :","options":["Interdite : seule la justice et la loi décident d’un divorce","Encadrée mais possible","Légale le dimanche","Acceptée selon les religions"],"correct":0,"why":"En France, nul ne peut mettre fin à un mariage par une simple parole : le divorce suit les règles du Code civil, à égalité entre les époux.","themeLabel":"Droits et devoirs"},{"id":"SC-098","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"En quelle année a commencé la Révolution française ?","options":["1789","1914","1848","1804"],"correct":0,"why":"1789 : prise de la Bastille le 14 juillet, Déclaration des droits de l’homme en août. Fin de la monarchie absolue.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-099","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel roi de France a été guillotiné pendant la Révolution ?","options":["Louis XVI","Louis XIV","François Ier","Henri IV"],"correct":0,"why":"Louis XVI, guillotiné le 21 janvier 1793. (Louis XIV = le « Roi-Soleil » de Versailles, 100 ans avant.)","themeLabel":"Histoire, géographie et culture"},{"id":"SC-100","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Où les rois de France étaient-ils couronnés ?","options":["À Reims","À Paris","À Versailles","À Lyon"],"correct":0,"why":"À la cathédrale de Reims, la « cité des sacres », du baptême de Clovis (496) à Charles X (1825). Ils étaient enterrés à Saint-Denis.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-101","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"En quelle année Napoléon Ier est-il devenu empereur ?","options":["1804","1789","1815","1918"],"correct":0,"why":"Sacré à Notre-Dame le 2 décembre 1804. Il laisse le Code civil, toujours en vigueur, et l’Arc de triomphe.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-102","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel texte célèbre a été adopté sous Napoléon Ier ?","options":["Le Code civil","La Déclaration de 1789","La Constitution de 1958","Le traité de Maastricht"],"correct":0,"why":"Le Code civil de 1804 (« Code Napoléon ») règle la famille, les biens, les contrats — c’est encore notre référence.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-103","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"La Première Guerre mondiale a eu lieu :","options":["De 1914 à 1918","De 1939 à 1945","De 1870 à 1871","De 1804 à 1815"],"correct":0,"why":"1914-1918 : « la Grande Guerre », 1,4 million de morts français. L’armistice est signé le 11 novembre 1918 — jour férié.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-104","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"La Seconde Guerre mondiale a eu lieu :","options":["De 1939 à 1945","De 1914 à 1918","De 1954 à 1962","De 1800 à 1815"],"correct":0,"why":"1939-1945. La France occupée par l’Allemagne nazie de 1940 à 1944, puis libérée (Débarquement le 6 juin 1944 en Normandie).","themeLabel":"Histoire, géographie et culture"},{"id":"SC-105","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Où a eu lieu le Débarquement allié de 1944 ?","options":["En Normandie","En Bretagne","Sur la Côte d’Azur","Dans le Nord"],"correct":0,"why":"Le 6 juin 1944 (« D-Day »), les Alliés débarquent sur les plages de Normandie (Utah, Omaha…). Début de la Libération.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-106","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Que fête-t-on le 8 mai ?","options":["La victoire de 1945, la fin de la Seconde Guerre mondiale en Europe","L’armistice de 1914-1918","La fête du travail","La fête nationale"],"correct":0,"why":"Le 8 mai 1945 : victoire des Alliés sur l’Allemagne nazie. (Le 11 novembre, lui, célèbre l’armistice de 1918.)","themeLabel":"Histoire, géographie et culture"},{"id":"SC-107","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Que commémore le 11 novembre ?","options":["L’armistice de la Première Guerre mondiale (1918)","La fête nationale","La victoire de 1945","La journée de l’Europe"],"correct":0,"why":"Le 11 novembre 1918 : fin de la Grande Guerre. Jour férié de mémoire, avec la flamme ravivée sous l’Arc de triomphe.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-108","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"De quand date l’appel à la résistance du général de Gaulle ?","options":["Du 18 juin 1940","Du 14 juillet 1789","Du 8 mai 1945","Du 11 novembre 1918"],"correct":0,"why":"Le 18 juin 1940, à la BBC de Londres : « Honneur à ceux qui refusent la défaite » — de Gaulle appelle à continuer le combat. Complément : L'appel du 18 juin 1940, lancé depuis Londres sur la BBC, invite les Français à refuser la défaite et l'armistice.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-109","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Jean Moulin ?","options":["Un héros de la Résistance pendant la Seconde Guerre mondiale","Un roi de France","Un peintre","Un chanteur"],"correct":0,"why":"Jean Moulin a uni la Résistance pour de Gaulle ; arrêté et torturé, il meurt en 1943 sans avoir parlé.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-110","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qu’est-ce que la Shoah ?","options":["L’extermination de 6 millions de Juifs par les nazis pendant la Seconde Guerre mondiale","Une fête juive","Une région de France","Une bataille de 1914"],"correct":0,"why":"À retenir : La Shoah désigne l'extermination systématique des Juifs d'Europe par le régime nazi et ses complices entre 1941 et 1945 ; environ 76 000 Juifs ont été déportés de France. Le génocide des Juifs d’Europe : 6 millions de victimes, dont 76 000 déportés de France. Un devoir de mémoire.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-111","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui a fondé la Ve République en 1958 ?","options":["Le général de Gaulle","Napoléon","François Mitterrand","Georges Pompidou"],"correct":0,"why":"1958 : de Gaulle fait adopter la Constitution de la Ve République, notre régime actuel, et en devient le premier président.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-112","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Depuis quelle année les Français élisent-ils le président au suffrage universel direct ?","options":["1962","1958","1789","2000"],"correct":0,"why":"Référendum de 1962 voulu par de Gaulle. Avant, le président était choisi par un collège de grands électeurs.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-113","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"En quelle année l’esclavage a-t-il été définitivement aboli en France ?","options":["1848","1789","1905","1945"],"correct":0,"why":"Abolition définitive en 1848 grâce à Victor Schœlcher. (Une première abolition en 1794 avait été annulée par Napoléon en 1802.)","themeLabel":"Histoire, géographie et culture"},{"id":"SC-114","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel grand port français participait à la traite des êtres humains (esclavage) au XVIIIe siècle ?","options":["Nantes","Marseille","Calais","Bordeaux seulement"],"correct":0,"why":"Nantes était le principal port négrier français, avant Bordeaux. En 2012, la ville a inauguré un Mémorial d’abolition. Le 10 mai est la journée nationale de commémoration.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-115","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui a rendu l’école gratuite, laïque et obligatoire ?","options":["Jules Ferry","Napoléon","Victor Hugo","De Gaulle"],"correct":0,"why":"À retenir : Jules Ferry, ministre de l'Instruction publique, a fait voter les lois de 1881 (gratuité) et 1882 (laïcité et obligation) ; Victor Hugo plaidait pour l'école gratuite mais n'a pas fait voter ces lois. Les lois Jules Ferry de 1881 (gratuité) et 1882 (obligation et laïcité). C’est pourquoi tant d’écoles portent son nom.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-116","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Le 1er mai, en France, c’est :","options":["La fête du Travail","La fête nationale","L’armistice","La journée de l’Europe"],"correct":0,"why":"Fête du Travail (journée de 8 heures, conquête ouvrière) ; on offre traditionnellement un brin de muguet.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-117","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle organisation internationale fut créée en 1945 après la guerre ?","options":["L’ONU","L’Union européenne","L’OTAN seulement","La francophonie"],"correct":0,"why":"L’Organisation des Nations unies, pour maintenir la paix. La France est membre permanent de son Conseil de sécurité.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-118","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"En quelle année l’euro est-elle devenue la monnaie utilisée en France ?","options":["2002","1992","1999","2020"],"correct":0,"why":"Pièces et billets en euro depuis janvier 2002, en remplacement du franc. Aujourd’hui, 20 pays de l’UE partagent l’euro.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-119","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"La CECA, première étape de la construction européenne (1951), portait sur :","options":["Le charbon et l’acier","Le blé et le vin","Les avions","La défense nucléaire"],"correct":0,"why":"Mettre en commun charbon et acier entre France et Allemagne pour rendre la guerre impossible : l’idée de Robert Schuman.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-120","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel fleuve traverse Paris ?","options":["La Seine","La Loire","Le Rhône","La Garonne"],"correct":0,"why":"La Seine traverse Paris (775 km, embouchure au Havre). La Loire est le plus long fleuve, le Rhône passe à Lyon. Complément : La Seine traverse Paris sur environ 13 km ; la Loire est le plus long fleuve de France (Orléans, Nantes).","themeLabel":"Histoire, géographie et culture"},{"id":"SC-121","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel océan borde la côte ouest de la France ?","options":["L’océan Atlantique","La mer Méditerranée","La mer du Nord","L’océan Indien"],"correct":0,"why":"L’Atlantique à l’ouest ; la Méditerranée au sud ; la Manche au nord, entre la France et l’Angleterre.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-122","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle mer sépare la France de l’Angleterre ?","options":["La Manche","La Méditerranée","La mer du Nord","L’Adriatique"],"correct":0,"why":"La Manche — traversée par le tunnel sous la Manche depuis 1994 (Paris-Londres en train !).","themeLabel":"Histoire, géographie et culture"},{"id":"SC-123","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle chaîne de montagnes sépare la France de l’Espagne ?","options":["Les Pyrénées","Les Alpes","Le Jura","Les Vosges"],"correct":0,"why":"Les Pyrénées au sud-ouest. (Les Alpes, elles, séparent la France de l’Italie — avec le Mont-Blanc.)","themeLabel":"Histoire, géographie et culture"},{"id":"SC-124","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle chaîne de montagnes se trouve entre la France et l’Italie ?","options":["Les Alpes","Les Pyrénées","Le Massif central","Les Vosges"],"correct":0,"why":"Les Alpes, où culmine le Mont-Blanc (4 808 m), le plus haut sommet d’Europe occidentale.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-125","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle est la plus haute montagne de France ?","options":["Le Mont-Blanc","Le Mont Ventoux","Le Puy de Dôme","Le pic du Midi"],"correct":0,"why":"Le Mont-Blanc, 4 808 mètres, dans les Alpes près de Chamonix. Premiers JO d’hiver là-bas en 1924 ! Complément : Le mont Blanc culmine à environ 4 805 mètres, à la frontière franco-italienne.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-126","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle grande ville est le chef-lieu de la région Auvergne-Rhône-Alpes ?","options":["Lyon","Grenoble","Clermont-Ferrand","Saint-Étienne"],"correct":0,"why":"Lyon, troisième ville de France, réputée pour sa gastronomie et sa fête des Lumières.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-127","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle est le premier port maritime de France ?","options":["Marseille","Le Havre","Calais","Nantes"],"correct":0,"why":"Marseille (port Marseille-Fos) : 1er port de France en tonnage, sur la Méditerranée. Fondée par les Grecs sous le nom de Massalia !","themeLabel":"Histoire, géographie et culture"},{"id":"SC-128","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"De quelle ville la fusée Ariane décolle-t-elle ?","options":["Kourou, en Guyane française","Toulouse","Paris","Cayenne uniquement"],"correct":0,"why":"Kourou, en Guyane (Amérique du Sud, près de l’équateur) : le Centre spatial guyanais — un fierté spatiale européenne.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-129","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel département français a une frontière terrestre avec le Brésil ?","options":["La Guyane","La Guadeloupe","La Réunion","Mayotte"],"correct":0,"why":"La Guyane, en Amérique du Sud : 730 km de frontière avec le Brésil. Le plus grand département de France !","themeLabel":"Histoire, géographie et culture"},{"id":"SC-130","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle île française se trouve dans l’océan Indien ?","options":["La Réunion","La Guadeloupe","La Corse","La Martinique"],"correct":0,"why":"La Réunion (974), au large de Madagascar. Mayotte aussi. Corse : Méditerranée. Guadeloupe et Martinique : les Antilles (Caraïbes).","themeLabel":"Histoire, géographie et culture"},{"id":"SC-131","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Les Antilles françaises regroupent :","options":["La Guadeloupe et la Martinique","La Réunion et Mayotte","La Corse et la Sicile","La Bretagne et la Normandie"],"correct":0,"why":"Dans la mer des Caraïbes : Guadeloupe (971) et Martinique (972). Destinations tropicales et départements français.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-132","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel est le 101e et plus récent département français ?","options":["Mayotte","La Réunion","La Guadeloupe","La Martinique"],"correct":0,"why":"Mayotte, dans l’océan Indien, département depuis 2011 après un vote à 95 % en sa faveur.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-133","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Combien de régions compte la France métropolitaine ?","options":["13","18","22","8"],"correct":0,"why":"13 régions en métropole, 18 en tout avec les 5 régions d’outre-mer (depuis la réforme de 2016).","themeLabel":"Histoire, géographie et culture"},{"id":"SC-134","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle est la population approximative de la France ?","options":["Environ 68 millions d’habitants","100 millions","30 millions","10 millions"],"correct":0,"why":"≈ 68 millions (métropole + outre-mer) : le 2e pays le plus peuplé de l’Union européenne, après l’Allemagne.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-135","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel monument sur une île en Normandie est célèbre dans le monde ?","options":["Le Mont-Saint-Michel","Le château de Chambord","Le pont du Gard","Le palais Idéal"],"correct":0,"why":"Le Mont-Saint-Michel et son abbaye médiévale : classé UNESCO, ~3 millions de visiteurs par an.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-136","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Dans quel musée parisien peut-on voir la Joconde ?","options":["Le Louvre","Le musée d’Orsay","Le Centre Pompidou","Le Palais de Tokyo"],"correct":0,"why":"Le Louvre : le plus grand musée d’art du monde. La Joconde de Léonard de Vinci y est la star absolue.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-137","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Pour quelle occasion la tour Eiffel a-t-elle été construite ?","options":["L’Exposition universelle de 1889","Le centenaire de la République en 1958","Les Jeux olympiques de 1900 seulement","La visite de la reine d’Angleterre"],"correct":0,"why":"Elle célébrait les 100 ans de la Révolution ! 330 m, presque démolie après 20 ans, sauvée grâce à la radio. 7 M de visiteurs par an.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-138","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel château près de Paris symbolise le pouvoir de Louis XIV ?","options":["Versailles","Chambord","Chenonceau","Fontainebleau seulement"],"correct":0,"why":"Le château de Versailles : le Roi-Soleil y installa sa cour en 1682, symbole de l’absolutisme et du rayonnement français.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-139","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Où peut-on voir des peintures préhistoriques en France ?","options":["À la grotte de Lascaux, en Dordogne","À Versailles","Au Louvre","Au Mont-Saint-Michel"],"correct":0,"why":"Lascaux : ~17 000 ans d’histoire, découverte en 1940, « chapelle Sixtine de la Préhistoire ». (La grotte Chauvet, en Ardèche, est encore plus vieille.) Complément : Lascaux (environ 17 000 ans) abrite des peintures rupestres ; Carnac est un ensemble de menhirs, pas de peintures.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-140","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui a peint « La Liberté guidant le peuple » ?","options":["Eugène Delacroix","Claude Monet","Auguste Renoir","Paul Cézanne"],"correct":0,"why":"Delacroix, 1830 : la Liberté brandit le drapeau tricolore sur une barricade. Ce tableau a inspiré l’image de Marianne. Visible au Louvre. Complément : Cette toile de 1830 célèbre les Trois Glorieuses ; Monet et Renoir sont arrivés plus tard, Picasso au XXe siècle.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-141","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel peintre français est le fondateur de l’impressionnisme (les Nymphéas) ?","options":["Claude Monet","Paul Cézanne","Auguste Rodin","Delacroix"],"correct":0,"why":"Claude Monet. Son « Impression, soleil levant » a donné son nom au mouvement. Ses Nymphéas : au musée de l’Orangerie, à Paris.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-142","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Auguste Rodin ?","options":["Un sculpteur célèbre (Le Penseur)","Un écrivain","Un chanteur","Un roi"],"correct":0,"why":"À retenir : Rodin (1840-1917) était sculpteur, non peintre : c'est une erreur fréquente de le confondre avec Renoir. Rodin, père de la sculpture moderne : Le Penseur, Le Baiser… Son musée est à Paris.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-143","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Molière ?","options":["Un dramaturge français, le père de la comédie française","Un peintre","Un roi de France","Un cuisinier"],"correct":0,"why":"Molière (XVIIe siècle) : L’Avare, Le Malade imaginaire, Tartuffe… On l’appelle le père de la comédie — et même « la langue de Molière » = le français. Complément : Molière (1622-1673), de son vrai nom Jean-Baptiste Poquelin, a écrit Le Misanthrope, L'Avare, Le Malade imaginaire.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-144","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Victor Hugo ?","options":["Un très grand écrivain français (Les Misérables, Notre-Dame de Paris)","Un peintre","Un général","Un chanteur"],"correct":0,"why":"Poète, romancier, combattant politique (contre la peine de mort et la misère). Ses funérailles en 1885 : 2 millions de personnes. Il repose au Panthéon.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-145","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Marie Curie ?","options":["Une physicienne et chimiste, double prix Nobel","Une reine","Une chanteuse","Une résistante de 1940"],"correct":0,"why":"À retenir : Marie Curie (1867-1934), née polonaise, a découvert le radium et le polonium : elle est la première femme à recevoir un prix Nobel et la seule à en avoir deux dans deux disciplines scientifiques. D’origine polonaise, naturalisée française : SEULE personne avec deux Nobel dans deux sciences (physique 1903, chimie 1911). Première femme professeur à la Sorbonne.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-146","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Simone de Beauvoir ?","options":["Une écrivaine et philosophe féministe (Le Deuxième Sexe)","Une reine de France","Une scientifique","Une peintre"],"correct":0,"why":"À retenir : Simone de Beauvoir (1908-1986), compagne de Jean-Paul Sartre, a publié Le Deuxième Sexe en 1949 ; aucune femme n'a encore été présidente de la République. Le Deuxième Sexe (1949) est un texte fondateur du féminisme moderne. Compagne de Jean-Paul Sartre.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-147","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui fut la première femme élue à l’Académie française ?","options":["Marguerite Yourcenar","George Sand","Simone Veil","Édith Piaf"],"correct":0,"why":"Marguerite Yourcenar, en 1980 (Mémoires d’Hadrien). L’Académie française, gardienne de la langue, date de 1635.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-148","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était George Sand ?","options":["Une écrivaine française du XIXe siècle","Une reine","Une chanteuse","Une scientifique"],"correct":0,"why":"Écrivaine célèbre (son vrai nom : Aurore Dupin) — engagée pour les femmes ; elle écrivit sous un pseudo « masculin » pour être publiée. Complément : George Sand (1804-1876), pseudonyme d'Aurore Dupin, a écrit La Mare au diable, Indiana, et correspondait avec Flaubert.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-149","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Albert Camus ?","options":["Un écrivain et philosophe, prix Nobel de littérature (L’Étranger)","Un roi","Un peintre","Un cuisinier"],"correct":0,"why":"À retenir : Camus (1913-1960), auteur de L'Étranger et de La Peste, est le deuxième plus jeune lauréat du prix Nobel de littérature. Nobel de littérature 1957. Né en Algérie, auteur de L’Étranger et La Peste.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-150","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Joséphine Baker ?","options":["Une artiste et résistante franco-américaine, entrée au Panthéon","Une reine","Une scientifique","Une nageuse"],"correct":0,"why":"Star du music-hall, résistante pendant l’Occupation, militante contre le racisme : entrée au Panthéon en 2021.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-151","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Combien de personnes parlent français dans le monde ?","options":["Environ 300 millions","3 millions","30 millions","1 milliard"],"correct":0,"why":"≈ 300 millions de francophones sur 5 continents : une des langues les plus parlées au monde, en forte croissance.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-152","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle cathédrale a été en partie détruite par un incendie en 2019 ?","options":["Notre-Dame de Paris","La cathédrale de Reims","La basilique de Saint-Denis","Le Mont-Saint-Michel"],"correct":0,"why":"Notre-Dame : incendie le 15 avril 2019, rouverte en décembre 2024 après un magnifique chantier national.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-153","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel compositeur français du « Clair de lune » est un monument de la musique ?","options":["Claude Debussy","Charles Aznavour","Beethoven","Mozart"],"correct":0,"why":"Debussy (1862-1918), figure de la « musique impressionniste ». (Aznavour : chanteur ; Beethoven et Mozart : pas français.)","themeLabel":"Histoire, géographie et culture"},{"id":"SC-154","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Charles Baudelaire ?","options":["Un poète français (Les Fleurs du mal)","Un roi","Un peintre","Un sportif"],"correct":0,"why":"Poète du XIXe siècle, auteur des Fleurs du mal, l’un des recueils de poésie les plus célèbres du monde. Complément : Baudelaire (1821-1867) est l'auteur des Fleurs du mal (1857) et le traducteur d'Edgar Poe.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-155","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Qui était Jean de La Fontaine ?","options":["L’auteur des Fables (ex. Le Corbeau et le Renard)","Un général","Un chanteur","Un architecte"],"correct":0,"why":"Ses Fables (XVIIe siècle), avec leurs animaux et leurs morales, sont apprises par cœur dans toutes les écoles de France.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-156","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quand peut-on visiter gratuitement des lieux culturels en France ?","options":["Lors des Journées européennes du patrimoine (septembre)","Jamais","Uniquement le 25 décembre","Le matin du dimanche uniquement"],"correct":0,"why":"3e week-end de septembre : châteaux, ministères, sites fermés au public ouvrent gratuitement leurs portes. (Et le 1er dimanche du mois dans beaucoup de musées.)","themeLabel":"Histoire, géographie et culture"},{"id":"SC-157","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quel plat est une spécialité de la cuisine française ?","options":["Le bœuf bourguignon","Les sushis","Le paella","Le kebab"],"correct":0,"why":"Bœuf bourguignon, ratatouille, coq au vin, bouillabaisse de Marseille… Le repas gastronomique français est inscrit à l’UNESCO depuis 2010 ! Complément : La ratatouille, niçoise, est un plat traditionnel français ; la paella est espagnole, le goulash hongrois, les sushis japonais.","themeLabel":"Histoire, géographie et culture"},{"id":"SC-158","theme":"histoire","source":"site","themeOrigine":"Histoire et culture","q":"Quelle fête est une tradition française ?","options":["La fête de la musique, le 21 juin","Halloween est une fête nationale","Thanksgiving","La Saint-Valentin est une fête nationale"],"correct":0,"why":"Le 21 juin, des musiciens amateurs jouent partout dans les rues — une fête française devenue mondiale !","themeLabel":"Histoire, géographie et culture"},{"id":"SC-159","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Où faut-il déclarer la naissance d’un enfant ?","options":["À la mairie du lieu de naissance, dans les 5 jours","À la préfecture, dans les 3 mois","À l’hôpital seulement","Nulle part, c’est automatique"],"correct":0,"why":"Le service d’état civil de la mairie enregistre la naissance : obligation de 5 jours (jour de l’accouchement non compris). Complément : La déclaration se fait à l'officier d'état civil de la mairie du lieu de naissance (art. 55 du Code civil).","themeLabel":"Vivre dans la société française"},{"id":"SC-160","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quel mariage est reconnu par l’État français ?","options":["Uniquement le mariage civil, célébré à la mairie","Le mariage religieux","Le mariage traditionnel","Toutes les formes de mariage"],"correct":0,"why":"Seul le mariage civil, célébré par un officier d’état civil à la mairie, a une valeur juridique. Le religieux peut s’ajouter ensuite, librement.","themeLabel":"Vivre dans la société française"},{"id":"SC-161","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"En cas de divorce, qui exerce l’autorité parentale ?","options":["Les deux parents, ensemble, sauf décision contraire du juge","Le père uniquement","La mère uniquement","Les grands-parents"],"correct":0,"why":"Le divorce ne change pas les droits des parents : les deux continuent de protéger et d’éduquer l’enfant, dans SON intérêt. Complément : Le divorce ne supprime pas l'autorité parentale : elle reste exercée en commun, dans l'intérêt de l'enfant.","themeLabel":"Vivre dans la société française"},{"id":"SC-162","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"L’école est obligatoire en France :","options":["De 3 à 16 ans (instruction), avec formation obligatoire jusqu’à 18 ans","De 6 à 14 ans","Pas d’âge limite","Seulement jusqu’à 10 ans"],"correct":0,"why":"Depuis 2019 : l’instruction démarre à 3 ans (maternelle incluse). De 16 à 18 ans : obligation de formation (lycée, apprentissage…).","themeLabel":"Vivre dans la société française"},{"id":"SC-163","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Si un enfant est absent de l’école, quel motif est accepté ?","options":["La maladie de l’enfant, un décès familial ou une convocation officielle","Les courses avec ses parents","La fatigue","Un anniversaire"],"correct":0,"why":"Seuls les motifs légitimes sont acceptés (maladie avec justificatif, deuil, convocation). L’école est un droit de l’enfant !","themeLabel":"Vivre dans la société française"},{"id":"SC-164","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Où les parents inscrivent-ils leur enfant à l’école publique ?","options":["À la mairie de leur commune","À la préfecture","À l’ambassade","Directement chez le maître seulement"],"correct":0,"why":"L’inscription se fait à la mairie, qui attribue l’école du secteur (carte scolaire).","themeLabel":"Vivre dans la société française"},{"id":"SC-165","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Après l’école primaire, les élèves vont :","options":["Au collège","Au lycée","À l’université","Au travail"],"correct":0,"why":"Collège (11-15 ans) : 6e, 5e, 4e, 3e ; puis lycée jusqu’au baccalauréat, le diplôme de fin de lycée.","themeLabel":"Vivre dans la société française"},{"id":"SC-166","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quel diplôme obtient-on à la fin du lycée ?","options":["Le baccalauréat","Le brevet","Le permis de conduire","Le BTS"],"correct":0,"why":"Le « bac », créé en 1808 ! (Le brevet, lui, se passe en fin de collège.)","themeLabel":"Vivre dans la société française"},{"id":"SC-167","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Un enfant qui ne parle pas encore français :","options":["Est scolarisé normalement et reçoit un accompagnement pour apprendre le français","Ne peut pas aller à l’école","Doit d’abord apprendre le français seul à la maison","Va dans une école privée uniquement"],"correct":0,"why":"Le droit à l’éducation est pour TOUS les enfants résidant en France ; des classes spéciales (UPE2A) les aident à apprendre le français.","themeLabel":"Vivre dans la société française"},{"id":"SC-168","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Un enfant en situation de handicap :","options":["A le droit d’être scolarisé dans l’école de son secteur, avec aménagements","Ne peut pas aller à l’école publique","Doit être éduqué à la maison","Va seulement en institut"],"correct":0,"why":"L’école inclusive (loi de 2005) : chaque enfant a droit à sa place à l’école, avec un accompagnement adapté si besoin (MDPH, AESH).","themeLabel":"Vivre dans la société française"},{"id":"SC-169","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Les parents d’élèves ont le droit de :","options":["Élire des représentants, participer aux conseils et rencontrer les enseignants","Intervenir dans les cours","Refuser le programme scolaire","Critiquer les cours de religion"],"correct":0,"why":"Les parents font partie de la communauté éducative — élections de représentants en octobre, réunions, conseils d’école.","themeLabel":"Vivre dans la société française"},{"id":"SC-170","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quels risques des parents qui ne respectent pas l’obligation d’instruction de leurs enfants ?","options":["Jusqu’à 2 ans de prison et 30 000 € d’amende","Aucun risque","Une simple amende de 10 €","La perte des allocations"],"correct":0,"why":"L’instruction de 3 à 16 ans est une obligation légale sérieuse, qui protège le droit de l’enfant à apprendre.","themeLabel":"Vivre dans la société française"},{"id":"SC-171","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Auprès de quel organisme demander le remboursement des frais de santé ?","options":["À l’Assurance maladie (Sécurité sociale)","À la mairie","À la police","À la banque"],"correct":0,"why":"L’Assurance maladie rembourse une partie des soins ; la carte Vitale atteste de vos droits ; la mutuelle complète ce qui reste.","themeLabel":"Vivre dans la société française"},{"id":"SC-172","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"À quoi sert la carte Vitale ?","options":["À obtenir le remboursement des frais de santé","À payer ses courses","À voter","À prendre le bus"],"correct":0,"why":"À retenir : La carte Vitale contient les données administratives du bénéficiaire et permet la télétransmission des feuilles de soins. La carte verte Vitale : le praticien l’insère, vos remboursements arrivent automatiquement sur votre compte.","themeLabel":"Vivre dans la société française"},{"id":"SC-173","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"À quoi sert une mutuelle ?","options":["À compléter les remboursements de l’Assurance maladie","À remplacer la Sécurité sociale","À payer les impôts","À assurer sa voiture"],"correct":0,"why":"Assurance maladie de base + mutuelle (complémentaire santé) = l’essentiel du reste à charge couvert.","themeLabel":"Vivre dans la société française"},{"id":"SC-174","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"L’inscription à l’Assurance maladie est :","options":["Obligatoire pour toute personne résidant en France de manière stable","Interdite aux étrangers","Uniquement pour les salariés","Uniquement pour les plus de 18 ans"],"correct":0,"why":"À retenir : La protection universelle maladie (PUMA) garantit la prise en charge des frais de santé à toute personne qui réside en France de façon stable et régulière. Protection universelle maladie (PUMa) : toute personne résidant stablement en France a droit à la prise en charge de ses frais de santé.","themeLabel":"Vivre dans la société française"},{"id":"SC-175","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Le SMIC, c’est :","options":["Le salaire minimum légal horaire","Un impôt","Une banque","Un type de contrat"],"correct":0,"why":"Salaire Minimum Interprofessionnel de Croissance : en dessous, aucun employeur ne peut payer. Revalorisé chaque année.","themeLabel":"Vivre dans la société française"},{"id":"SC-176","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quelle est la durée légale du travail par semaine ?","options":["35 heures","40 heures","30 heures","48 heures"],"correct":0,"why":"35 heures depuis 2000. Au-delà : heures supplémentaires majorées en salaire.","themeLabel":"Vivre dans la société française"},{"id":"SC-177","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quelle est la première démarche pour chercher un emploi ?","options":["S’inscrire à France Travail (ex-Pôle emploi)","Écrire au président","Appeler le 17","Se rendre à l’ambassade"],"correct":0,"why":"France Travail accompagne la recherche d’emploi et verse les allocations chômage si vous y avez droit.","themeLabel":"Vivre dans la société française"},{"id":"SC-178","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Le travail non déclaré (« au noir ») est :","options":["Interdit : c’est un délit qui prive le salarié de protection","Toléré","Légal le soir","Légal entre voisins"],"correct":0,"why":"Sanctions sévères pour l’employeur et absence de couverture (maladie, retraite, chômage) pour le salarié. Toujours exiger un contrat !","themeLabel":"Vivre dans la société française"},{"id":"SC-179","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quel organisme juge les conflits entre un salarié et son employeur ?","options":["Le conseil de prud’hommes","La mairie","La police","Le préfet"],"correct":0,"why":"Le prud’hommes : juges salariés et employeurs à parts égales. Saisine gratuite — utile en cas de licenciement abusif ou de salaires impayés.","themeLabel":"Vivre dans la société française"},{"id":"SC-180","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Peut-on licencier une femme parce qu’elle est enceinte ?","options":["Non : c’est strictement interdit et puni par la loi","Oui, librement","Oui, après 3 mois de grossesse","Oui, sans indemnités"],"correct":0,"why":"Protection absolue de la grossesse (Code du travail). Un tel licenciement est nul et l’employeur peut être condamné.","themeLabel":"Vivre dans la société française"},{"id":"SC-181","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Depuis 2021, la durée du congé paternité est de :","options":["28 jours au total (25 + 3 de congé de naissance)","3 jours","6 mois","1 an"],"correct":0,"why":"Le congé paternité a été doublé pour accompagner bébé : les deux parents partagent l’éducation de l’enfant — c’est aussi ça, l’égalité !","themeLabel":"Vivre dans la société française"},{"id":"SC-182","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Une femme peut-elle créer son entreprise ?","options":["Oui, au même titre qu’un homme","Non","Avec l’accord de son mari","Seulement après 30 ans"],"correct":0,"why":"À retenir : Les femmes ont les mêmes droits que les hommes pour entreprendre : aucune autorisation familiale n'est exigée. Égalité totale en droit : travailler, créer une entreprise, ouvrir un compte bancaire, conduire, voter…","themeLabel":"Vivre dans la société française"},{"id":"SC-183","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Une personne étrangère en situation régulière peut-elle créer son entreprise en France ?","options":["Oui, sous conditions liées à son titre de séjour","Non, jamais","Oui, même sans titre","Seulement dans les grandes villes"],"correct":0,"why":"Selon le titre de séjour, on peut entreprendre — la France encourage l’initiative économique de tous.","themeLabel":"Vivre dans la société française"},{"id":"SC-184","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quel est l’âge de la majorité en France ?","options":["18 ans","16 ans","21 ans","15 ans"],"correct":0,"why":"Majorité à 18 ans : on devient pleinement majeur civilement (droit de vote, contrats…). On peut travailler dès 16 ans avec accord des parents.","themeLabel":"Vivre dans la société française"},{"id":"SC-185","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"À partir de quel âge un mineur peut-il travailler ?","options":["16 ans, avec l’accord de ses représentants légaux","10 ans","25 ans","Ne jamais travailler"],"correct":0,"why":"Dès 16 ans avec accord parental (14 ans en vacances pour des jobs légers). Protection renforcée des jeunes travailleurs.","themeLabel":"Vivre dans la société française"},{"id":"SC-186","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Qu’est-ce que l’aide juridictionnelle ?","options":["Une aide de l’État pour payer un avocat aux personnes à faibles revenus","Une taxe d’avocat","Un tribunal spécial","Une école de droit"],"correct":0,"why":"L’accès à la justice pour tous : selon les revenus, l’État prend en charge tout ou partie des frais d’avocat.","themeLabel":"Vivre dans la société française"},{"id":"SC-187","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Quelle aide permet d’avoir un avocat quand on a peu d’argent ?","options":["L’aide juridictionnelle","Le RSA","Les bourses d’école","La carte Vitale"],"correct":0,"why":"On la demande au tribunal ou en ligne : le droit de se défendre ne dépend pas de ses revenus.","themeLabel":"Vivre dans la société française"},{"id":"SC-188","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Se garer sur une place réservée aux personnes handicapées sans carte :","options":["C’est interdit : amende de 135 €","C’est toléré 5 minutes","C’est autorisé le dimanche","C’est autorisé la nuit"],"correct":0,"why":"Ces places sont réservées aux titulaires de la Carte Mobilité Inclusion (CMI) : respecter, c’est permettre l’autonomie de chacun.","themeLabel":"Vivre dans la société française"},{"id":"SC-189","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Une machine à laver cassée et hors d’usage peut être :","options":["Réparée, garantie, ou déposée gratuitement en déchèterie (ou reprise au 1 pour 1)","Jetée dans la rue","Brûlée au jardin","Jetée dans la nature"],"correct":0,"why":"Jamais dans la rue (jusqu’à 1 500 € d’amende) ! Garantie légale 2 ans ; le vendeur reprend l’ancien appareil lors d’un nouvel achat.","themeLabel":"Vivre dans la société française"},{"id":"SC-190","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Le locataire d’un logement peut, sans autorisation du propriétaire :","options":["Repeindre les murs, accrocher des cadres, disposer ses meubles","Abattre un mur porter","Sous-louer le logement","Changer la serrure sans rendre les clés"],"correct":0,"why":"On se sent chez soi ! Mais abattre une cloison, sous-louer ou déménager des murs : autorisation écrite obligatoire.","themeLabel":"Vivre dans la société française"},{"id":"SC-191","theme":"vivre","source":"site","themeOrigine":"Vie quotidienne","q":"Que faire si l’on est témoin de violences dans la rue ou chez un voisin ?","options":["Alerter la police (17) ou les secours : c’est un devoir citoyen","Ne rien dire, c’est « privé »","Intervenir seul physiquement","Filmer et publier en ligne"],"correct":0,"why":"Signaler protège les victimes. En cas de danger direct : 17 (police) ou 112.","themeLabel":"Vivre dans la société française"},{"id":"SS-192","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Une collègue vous demande d’adapter les horaires de l’équipe pour qu’il puisse prier pendant ses horaires religieux. Que faites-vous ?","options":["Vous l’écoutez et lui suggérez d’en parler au responsable pour trouver un arrangement possible","Vous refusez : « la religion est interdite au travail »","Vous acceptez sans en parler à personne","Vous en parlez à tous les collègues pour vous moquer"],"correct":0,"why":"La laïcité garantit la liberté de conscience : dans le privé, un aménagement raisonnable est possible. La bonne démarche : le dialogue avec la hiérarchie. Piège : Réflexe-examen : la bonne réponse passe TOUJOURS par le dialogue et le respect mutuel — jamais par l’humiliation ou l’interdiction totale.","themeLabel":"Mises en situation"},{"id":"SS-193","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Lors d’une réunion de parents d’élèves, un père refuse de s’adresser à la directrice parce que c’est une femme. Que faites-vous ?","options":["Vous lui expliquez calmement que l’égalité entre les femmes et les hommes est un principe fondamental en France","Vous respectez son choix culturel","Vous appelez immédiatement la police","Vous quittez la réunion en silence"],"correct":0,"why":"En France, une femme a exactement la même autorité qu’un homme. Refuser de s’adresser à elle est illégal lui-même discriminatoire.","themeLabel":"Mises en situation"},{"id":"SS-194","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Sur un réseau social, une personne publie des messages haineux contre une religion. Que faites-vous ?","options":["Vous signalez le contenu à la plateforme (et à la plateforme officielle PHAROS si nécessaire)","Vous partagez pour dénoncer","Vous répondez par des insultes","Vous ignorez : « c’est la liberté d’expression »"],"correct":0,"why":"La haine en ligne est un délit : on signale via les plateformes et le portail PHAROS (police). JAMAIS répondre par la haine — et « ignorer » laisse la victime seule.","themeLabel":"Mises en situation"},{"id":"SS-195","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Un parent demande que sa fille soit dispensée du cours de sport (piscine) car c’est mixte, pour des raisons religieuses. Que doit répondre le directeur ?","options":["Il refuse : le programme scolaire est obligatoire pour tous, la laïcité interdit de choisir ses cours selon sa religion","Il accepte par tolérance","Il propose un cours individuel","Il demande au rectorat d’arbitrer"],"correct":0,"why":"À l’école publique, tous les enseignements sont obligatoires ; seul un certificat médical peut dispenser d’un cours — jamais un motif religieux. Piège : Piège n°1 de l’examen : « tolérance » et « acceptation » sont de FAUSSES bonnes réponses. La bonne réponse est ferme et légale.","themeLabel":"Mises en situation"},{"id":"SS-196","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Votre voisin vous confie avoir perdu la foi et vouloir renoncer publiquement à sa religion. Sa famille le menace de l’exclure. Que lui dites-vous ?","options":["La liberté de conscience inclut le droit de changer ou d’abandonner sa religion — elle est protégée par la loi","Il doit rester dans sa religion pour sa famille","Vous lui suggérez de faire semblant","La loi interdit les « apostats »"],"correct":0,"why":"La loi de 1905 et la Constitution protègent le droit de croire ET de ne plus croire. Personne ne peut forcer quelqu’un à garder une religion.","themeLabel":"Mises en situation"},{"id":"SS-197","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Un élu municipal porte une grande croix religieuse en célébrant des mariages et refuse de la retirer. C’est :","options":["Illégal : un agent public doit respecter la neutralité religieuse dans l’exercice de ses fonctions","Légal : c’est sa liberté d’expression","Légal si c’est discret","Légal s’il est élu"],"correct":0,"why":"La neutralité s’impose aux agents publics et aux élus dans leurs fonctions officielles. En dehors, ils sont des citoyens libres.","themeLabel":"Mises en situation"},{"id":"SS-198","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Dans une mairie, une usagère voilée vient retirer sa carte d’identité. Que peut faire l’agent ?","options":["L’accueillir comme tout usager — la neutralité s’impose à l’agent ; pour la photo et la vérification d’identité, le visage doit simplement être visible","Refuser de la servir","Exiger qu’elle retire son voile pour entrer","Appeler la police"],"correct":0,"why":"La neutralité s’impose aux AGENTS, jamais aux usagers. On n’exige pas de retirer un foulard ou un voile : seul le VISAGE visible suffit à établir l’identité.","themeLabel":"Mises en situation"},{"id":"SS-199","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Votre employeur refuse de vous embaucher après avoir vu votre prénom « étranger » sur le CV. C’est :","options":["De la discrimination : un délit sanctionné (Défenseur des droits, prud’hommes)","Un choix d’entreprise normal","Illégal mais sans recours","Acceptable dans le privé"],"correct":0,"why":"La discrimination liée à l’origine, au sexe, à la religion… est un délit. On peut saisir gratuitement le Défenseur des droits.","themeLabel":"Mises en situation"},{"id":"SS-200","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Un enseignant organise un débat sur les religions en classe. Des parents écrivent au directeur pour protester. Que dit la laïcité ?","options":["Enseigner l’histoire et le fait religieux est autorisé — c’est apprendre, pas faire du prosélytisme","Il faut interdire ce cours","Seule la religion chrétienne peut être enseignée","L’école ne doit jamais parler de religion"],"correct":0,"why":"La laïcité n’efface pas l’histoire des religions : enseigner les faits (cultures, histoire) est pédagogique ; faire du prosélytisme (imposer une foi) est interdit.","themeLabel":"Mises en situation"},{"id":"SS-201","theme":"situation","source":"site","themeOrigine":"Principes et valeurs","q":"Un restaurateur refuse de servir une cliente parce qu’elle porte une tenue religieuse. C’est :","options":["De la discrimination, illégale dans un commerce ouvert au public","Son droit commercial","Légal le soir","Toléré par politesse"],"correct":0,"why":"Refuser l’accès à un bien ou service pour des motifs religieux ou liés à l’origine est un délit, puni par la loi.","themeLabel":"Mises en situation"},{"id":"SS-202","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu assistes à un accident de la route : une moto est au sol, le conducteur inconscient. Que fais-tu en premier ?","options":["Appeler le 15/18/112, sécuriser la zone si possible sans te mettre en danger, rester sur place","Déplacer le blessé","Partir vite : « appelle quelqu’un d’autre »","Publier une photo en ligne"],"correct":0,"why":"Non-assistance à personne en danger = délit. Le bon réflexe : protéger (sans se mettre en danger), alerter (15 SAMU, 18 pompiers, 112 Europe), rester jusqu’aux secours.","themeLabel":"Mises en situation"},{"id":"SS-203","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Une collègue te dit gagner moins que son collègue masculin pour exactement le même poste. Tu lui conseilles :","options":["D’en parler à la DRH puis, si besoin, de saisir l’inspection du travail ou le Défenseur des droits","De démissionner en silence","De se venger en ligne","De ne rien dire pour garder son poste"],"correct":0,"why":"L’égalité salariale femmes-hommes à poste égal est imposée par la loi. Des recours légaux existent et protègent la salariée.","themeLabel":"Mises en situation"},{"id":"SS-204","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu perçois des revenus de l’étranger que ton employeur n’a pas déclarés en France. Que dois-tu faire vis-à-vis des impôts français ?","options":["Les déclarer : tout résident fiscal français déclare l’ensemble de ses revenus mondiaux","Les garder secrets","Attendre que le fisc les trouve","Ne déclarer que ce qui dépasse 10 000 €"],"correct":0,"why":"La règle claire : résident en France = déclaration de TOUS les revenus, d’où qu’ils viennent. L’administration fiscale est aujourd’hui très connectée.","themeLabel":"Mises en situation"},{"id":"SS-205","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Un jeune te dit : « Je ne paierai pas mes impôts, les politiciens volent tout ». Que lui réponds-tu ?","options":["L’impôt est un devoir qui finance les services publics de tous (écoles, hôpitaux, routes) — le refus est un délit","Tu as raison, boycotte !","Pais-en seulement si tu es riche","Vote d’abord, paie après"],"correct":0,"why":"Payer l’impôt est un pilier de la solidarité nationale : on bénéficie tous des mêmes services publics grâce à lui.","themeLabel":"Mises en situation"},{"id":"SS-206","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Ta voisine âgée tombe chez elle ; elle ne peut plus ouvrir sa porte. Tu entends ses appels au secours. Que fais-tu ?","options":["Appeler le 15 ou le 18, rester avec elle en lui parlant, prévenir éventuellement ses proches","Appeler la voisine du dessus seulement","Frapper chez le gardien et partir","Attendre le lendemain matin"],"correct":0,"why":"Assistance à personne en danger : on alerte les secours, on rassure, on reste disponible — c’est un devoir citoyen ET humain.","themeLabel":"Mises en situation"},{"id":"SS-207","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Un « ami » te propose un travail au restaurant « payé en liquide, sans déclaration ». Tu acceptes ?","options":["Non : le travail dissimulé est un délit — tu n’aurais ni couverture maladie, ni retraite, ni droits en cas d’accident","Oui, c’est une bonne opportunité","Oui, mais seulement le week-end","Oui, si le salaire est bon"],"correct":0,"why":"Toujours REFUSER : sans déclaration, tu travailles sans aucune protection (maladie, chômage, accident du travail, retraite) et tu risques des sanctions.","themeLabel":"Mises en situation"},{"id":"SS-208","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Ton employeur te paie moins que le SMIC « parce que tu n’as pas encore de carte de séjour ». C’est :","options":["Illégal : le SMIC s’applique à tout salarié, quelle que soit sa nationalité","Légal pour les étrangers","Légal la première année","Une pratique normale"],"correct":0,"why":"Le salaire minimum et les droits du Code du travail valent pour TOUS les salariés en France, sans distinction de nationalité.","themeLabel":"Mises en situation"},{"id":"SS-209","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu vois dans la rue un enfant seul en pleurs qui dit être perdu. Que fais-tu ?","options":["Tu restes avec lui, tu le rassures et tu appelles la police (17) pour qu’on retrouve ses parents","Tu le laisses : ses parents reviendront","Tu fais détourner le regard par politesse","Tu le photographies et publies en ligne pour retrouver sa famille"],"correct":0,"why":"On protège l’enfant en restant près de lui (sans l’emmener) et on appelle le 17. Publier sa photo l’expose à des dangers.","themeLabel":"Mises en situation"},{"id":"SS-210","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Un homme frappe sa femme devant toi dans la rue. Que fais-tu ?","options":["Tu appelles immédiatement la police (17) ou le 112, et tu ne t’interposes pas physiquement seul","Tu restes spectateur : « c’est leur vie privée »","Tu frappes l’homme à ton tour","Tu cries « arrêtez » de loin et tu pars"],"correct":0,"why":"Les violences conjugales sont un CRIME grave (« la sphère privée » n’existe pas devant la loi). On alerte les forces de l’ordre, en sécurité.","themeLabel":"Mises en situation"},{"id":"SS-211","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu es témoin d’un contrôle d’identité brutal où un policier insulte un jeune pour sa couleur de peau. Que peux-tu faire ?","options":["Le signaler : on peut saisir l’IGPN (« police des polices ») et le Défenseur des droits — aucun agent n’est au-dessus de la loi","Rien, c’est leur travail","Partager une vidéo identifiante en ligne comme preuve","Insulter le policier"],"correct":0,"why":"L’État de droit vaut aussi pour les forces de l’ordre : un comportement raciste est signalé (IGPN/IGGN, Défenseur des droits, justice).","themeLabel":"Mises en situation"},{"id":"SS-212","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Quelqu’un te demande de transporter un petit paquet « pour un ami » entre deux villes contre 200 €, sans regarder dedans. Tu :","options":["Refuses : c’est potentiellement une infraction (stupéfiants, vols) — et tu signales","Acceptes, 200 € c’est facile","Acceptes mais regardes dedans","Demandes 400 €"],"correct":0,"why":"On refuse catégoriquement et on signale : les passeurs inconscients commettent un délit grave, même « sans savoir ».","themeLabel":"Mises en situation"},{"id":"SS-213","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Dans le bus, un homme harcèle verbalement une jeune femme. Réaction correcte :","options":["Tu alertes le chauffeur/conducteur, tu te rapproches pour soutenir la victime (effet de nombre) et tu appelles le 17 si besoin","Tu regardes ailleurs","Tu filmes pour poster","Tu cries sur l’homme"],"correct":0,"why":"Le harcèlement dans les transports est un délit. Soutenir la victime en groupe et alerter, sans se mettre en danger, est le bon réflexe citoyen.","themeLabel":"Mises en situation"},{"id":"SS-214","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Ton enfant de 15 ans veut arrêter l’école pour « travailler et gagner de l’argent ». Que disent les règles ?","options":["L’instruction est obligatoire jusqu’à 16 ans, puis formation jusqu’à 18 ans — il existe des alternatives comme l’apprentissage dès 15 ans","Il est libre : à lui de décider","Il peut travailler dès 14 ans","Il faut qu’il parte travailler à l’étranger"],"correct":0,"why":"Jusqu’à 16 ans : école ou instruction en famille. De 16 à 18 ans : obligation de formation (lycée, apprentissage, service civique) — il n’est pas laissé sans cadre.","themeLabel":"Mises en situation"},{"id":"SS-215","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"En déménageant, tu trouves 500 € en liquide dans un meuble de ton nouvel appartement loué. Tu :","options":["Le signales au propriétaire et si tu le gardes malgré tout, c’est du vol de chose trouvée","Le gardes : trouvé = à toi","Le dépenses vite","Ne dis rien"],"correct":0,"why":"Une chose trouvée doit être signalée au propriétaire / à la mairie / à la police : la garder est une infraction (abus de confiance/vol).","themeLabel":"Mises en situation"},{"id":"SS-216","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Ton voisin brûle ses déchets plastiques dans son jardin et la fumée envahit ta maison. Que fais-tu ?","options":["Tu lui parles calmement d’abord, puis tu signales à la mairie si ça continue (brûlage interdit, polluant et dangereux)","Tu lui verses un sceau d’eau","Tu appelles immédiatement le SAMU","Tu brûles tes déchets aussi"],"correct":0,"why":"Réflexe-examen : DIALOGUE d’abord, recours légal ensuite. Le brûlage de déchets en plein air est strictement interdit (santé, incendie).","themeLabel":"Mises en situation"},{"id":"SS-217","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Des jeunes dégradent régulièrement le hall de ton immeuble (graffitis, déjections). Meilleure démarche :","options":["En parler au gardien/syndic, signaler à la police municipale ou au commissariat — la dégradation de bien public est un délit","Casser quelque chose toi aussi pour « rendre justice »","Les insulter","Ne jamais rien dire"],"correct":0,"why":"La dégradation de bien commun ou public est un délit : on peut signaler à la police municipale (ou nationale) et au propriétaire/syndic.","themeLabel":"Mises en situation"},{"id":"SS-218","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Un homme te propose à la sortie du métro un iPhone « neuf, à 50 € ». Tu :","options":["Refuses : c’est très probablement un objet volé (recel est un délit)","Achètes : c’est une affaire","Achètes en négociant 30 €","Demandes son origine, et si c’est « trouvé », c’est bon"],"correct":0,"why":"Acheter un bien dont on sait (ou on devine) qu’il est volé = recel, un délit puni de prison et d’amende.","themeLabel":"Mises en situation"},{"id":"SS-219","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Une femme voilée intégral (niqab) circule dans l’espace public. Que dit la loi ?","options":["La dissimulation du visage dans l’espace public est interdite (hors cas spécifiques), amende possible","C’est totalement légal partout","Interdit seulement dans les banques","Autorisé avec une carte d’identité"],"correct":0,"why":"Depuis 2010, la loi interdit la dissimulation du visage dans l’espace public (rue, transports, commerces). À l’intérieur de son domicile : liberté totale.","themeLabel":"Mises en situation"},{"id":"SS-220","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu te rends compte que ta carte d’identité a expiré le jour où tu dois prendre l’avion. Tu :","options":["Contactes immédiatement la compagnie et la mairie / préfecture pour les démarches possibles (titre provisoire, procurations)","Prends ton ancien passeport étranger","Achètes un faux document en ligne","Annules et oublies"],"correct":0,"why":"On n’achète JAMAIS de faux documents — c’est un crime grave. On se tourne vers l’administration (mairie, préfecture) : ils ont des solutions.","themeLabel":"Mises en situation"},{"id":"SS-221","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"En arrivant à un feu rouge avec des enfants pressés dans la voiture, un ami te dit « passe, il n’y a personne ». Tu :","options":["T’arrêtes : le code de la route s’applique toujours — avec des enfants, donner l’exemple est aussi un devoir parental","Passes vite","Passes en klaxonnant","Demande si ton ami est sûr"],"correct":0,"why":"Le code de la route n’a pas d’exception « urgence personnelle » ; franchir un feu met en danger des vies — et transmet l’exemple aux enfants.","themeLabel":"Mises en situation"},{"id":"SS-222","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Une association de quartier propose un repas « réservé aux femmes seulement » pour des raisons religieuses. Dans un local public, c’est :","options":["Discriminatoire : un lieu ouvert au public ne peut exclure selon le sexe ou la religion","Parfaitement légal","Acceptable si c’est culturel","Toléré pour 1 fois"],"correct":0,"why":"Les services publics et lieux recevant du public ne peuvent exclure personne pour son sexe ou sa religion : c’est le principe d’égal accès.","themeLabel":"Mises en situation"},{"id":"SS-223","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Ton ami musulman diffuse en ligne un texte appelant à ne pas saluer les femmes et à ne pas leur serrer la main « car elles sont impures ». Tu lui rends service en disant :","options":["Le respect de l’égalité entre les femmes et les hommes est un principe fondamental — ces propos relèvent de la provocation à la discrimination, un délit","C’est sa religion, il dit ce qu’il veut","Supprime le message seulement","Ne réponds jamais"],"correct":0,"why":"La liberté religieuse ne couvre PAS la provocation à la haine ou à la discrimination. Dire la loi calmement est aussi un acte de citoyenneté.","themeLabel":"Mises en situation"},{"id":"SS-224","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"À la piscine municipale, une femme refuse de se changer devant d’autres personnes car « les hommes pourraient la voir ». Que peut-on faire de raisonnable ?","options":["Proposer un aménagement raisonnable (cabine individuelle) — le droit à la dignité et la pudeur sont respectés, sans séparer les sexes","Exiger qu’elle se change comme tout le monde","L’expulser de la piscine","Ne rien répondre"],"correct":0,"why":"La règle : les aménagements individuels raisonnables (cabines, casiers) existent dans beaucoup de piscines — la pudeur de chacun peut être respectée sans ségrégation.","themeLabel":"Mises en situation"},{"id":"SS-225","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Un employeur te demande en entretien « tu comptes avoir un bébé ? sinon je ne prends pas ». Cette question est :","options":["Illégale : c’est de la discrimination liée au sexe — tu peux refuser de répondre et signaler","Normale en entretien","Légale dans un petit commerce","Acceptable à l’oral"],"correct":0,"why":"Les questions sur la vie privée, la grossesse ou la religion sont INTERDITES en entretien d’embauche. Refuser poliment est un droit.","themeLabel":"Mises en situation"},{"id":"SS-226","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu apprends qu’un magasin affiche « interdit aux chiens et aux femmes voilées ». Ce panneau est :","options":["Discriminatoire et illégal : un commerce ouvert au public ne peut exclure selon la tenue religieuse","Légal si le patron est d’accord","Légal pendant les fêtes","Acceptable pour « l’image »"],"correct":0,"why":"Les lieux recevant du public (commerces) ne peuvent pas refuser l’accès pour des motifs liés à l’apparence religieuse. On peut signaler au Défenseur des droits.","themeLabel":"Mises en situation"},{"id":"SS-227","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Tu es en France depuis 3 ans et tu veux faire du bénévolat (restos du cœur, associations). C’est :","options":["Possible et encouragé à tout âge — le bénévolat est ouvert à tous, signe de l’engagement citoyen","Interdit aux étrangers","Réservé aux Français","Payant"],"correct":0,"why":"La fraternité se vit aussi par l’engagement : le bénévolat crée du lien, et les associations accueillent tous les volontaires — une belle preuve d’intégration pour ta lettre de motivation !","themeLabel":"Mises en situation"},{"id":"SS-228","theme":"situation","source":"site","themeOrigine":"Droits et devoirs","q":"Ton voisin de palier diffuse sa musique très fort chaque nuit. Que fais-tu ?","options":["Dialogue d’abord, puis tapage nocturne = contravention — la police peut dresser procès, ou tu saisis le conciliateur de justice","Tu réponds avec ta musique plus fort","Tu coupes son compteur électrique","Tu cries depuis ta fenêtre"],"correct":0,"why":"Trouble anormal de voisinage : dialogue, puis mairie/police (contravention), ou conciliateur de justice pour une solution amiable en justice. Dialogue d’abord !","themeLabel":"Mises en situation"},{"id":"S-01","theme":"situation","sous":"laicite","q":"Dans un collège public, une élève se présente en cours avec un signe religieux très visible. Que prévoit la règle applicable ?","options":["L'équipe éducative lui demande de le retirer ; en cas de refus, une procédure de dialogue puis disciplinaire est engagée","Le signe est accepté, car la liberté d'expression est totale à l'école","L'élève est immédiatement exclue définitivement de l'établissement","Seul le chef d'établissement peut décider, sans aucune règle écrite"],"correct":0,"why":"La loi de 2004 interdit les signes religieux ostentatoires dans les écoles publiques : le dialogue précède toujours une éventuelle sanction.","themeLabel":"Mises en situation"},{"id":"S-02","theme":"situation","sous":"laicite","q":"Un usager se présente à l'accueil de la mairie et demande à être reçu par un agent « de sa religion ». Que doit répondre l'agent ?","options":["Que le service public est neutre : il sera reçu par le premier agent disponible, comme tout le monde","Qu'il revienne un jour où un agent de sa religion travaille","Qu'il doit d'abord écrire au préfet pour obtenir cette dérogation","Que la mairie n'accueille pas les personnes croyantes"],"correct":0,"why":"La neutralité du service public garantit l'égalité de traitement des usagers, quelles que soient leurs convictions.","themeLabel":"Mises en situation"},{"id":"S-03","theme":"situation","sous":"urgences","q":"Vous entendez des cris et des coups provenant de l'appartement voisin : une personne semble être frappée. Que faites-vous ?","options":["J'appelle le 17 (police/secours) et, si possible, le 3919 pour les victimes de violences","Je n'interviens pas : c'est une affaire privée entre adultes","J'attends le lendemain pour en parler au gardien de l'immeuble","Je frappe à la porte pour séparer les personnes moi-même"],"correct":0,"why":"Les violences conjugales sont un délit : l'appel au 17 permet une intervention immédiate ; le 3919 informe et oriente les victimes.","themeLabel":"Mises en situation"},{"id":"S-04","theme":"situation","sous":"discriminations","q":"Au travail, un collègue tient régulièrement des propos insultants envers un autre collègue à cause de ses origines. Que faire ?","options":["Le signaler à l'employeur (ou aux représentants du personnel) : ces propos constituent une discrimination punie par la loi","Ne rien dire : le règlement intérieur protège l'auteur des propos","Répondre par des insultes pour rétablir l'équilibre","Attendre que la personne visée porte plainte seule, sans aide"],"correct":0,"why":"Les propos et agissements discriminatoires au travail sont interdits (art. L.1132-1 du Code du travail) : l'employeur a une obligation d'agir.","themeLabel":"Mises en situation"},{"id":"S-05","theme":"situation","sous":"travail","q":"Un ami en situation irrégulière vous demande de l'aider à trouver un travail non déclaré pour « se débrouiller ». Que répondez-vous ?","options":["Que c'est illégal et dangereux : sans déclaration, il n'a ni salaire garanti, ni protection, ni droit au séjour","Que c'est une bonne solution temporaire en attendant la régularisation","Que c'est autorisé si l'employeur est une petite entreprise","Que c'est légal tant qu'il travaille moins de 20 heures par semaine"],"correct":0,"why":"Le travail dissimulé prive le salarié de tous ses droits et expose employeur comme salarié à des sanctions ; il ne crée aucun droit au séjour.","themeLabel":"Mises en situation"},{"id":"S-06","theme":"situation","sous":"civilite","q":"Vous trouvez un portefeuille contenant de l'argent et des papiers dans la rue. Que devez-vous faire ?","options":["Le déposer au commissariat, à la gendarmerie ou au bureau des objets trouvés de la mairie","Le garder si personne ne le réclame dans les 24 heures","En retirer l'argent et déposer le reste","Le laisser sur place au cas où son propriétaire reviendrait"],"correct":0,"why":"S'approprier un objet trouvé sans le déclarer peut constituer un vol : le dépôt en mairie ou au commissariat est la démarche légale.","themeLabel":"Mises en situation"},{"id":"S-07","theme":"situation","sous":"secours","q":"Vous êtes le premier témoin d'un accident de la route avec un blessé inconscient. Que faites-vous ?","options":["J'appelle le 15 ou le 112, je sécurise les lieux et je reste jusqu'à l'arrivée des secours","Je pars chercher un médecin en laissant le blessé seul","Je prends des photos pour les réseaux sociaux","Je remets le blessé debout pour le rassurer"],"correct":0,"why":"Ne pas porter secours est un délit (non-assistance à personne en danger) ; il faut alerter, protéger et ne pas déplacer un blessé.","themeLabel":"Mises en situation"},{"id":"S-08","theme":"situation","sous":"civilite","q":"Un employeur vous propose un emploi en vous disant : « On ne déclare rien, tu touches plus en espèces. » Que se passe-t-il ?","options":["Il s'agit de travail dissimulé : vous perdez vos droits (retraite, maladie, chômage) et l'employeur risque des sanctions pénales","C'est avantageux et légal tant que vous êtes d'accord tous les deux","C'est autorisé pour les emplois saisonniers uniquement","C'est légal si vous travaillez moins de 3 mois"],"correct":0,"why":"Le travail dissimulé est puni par le Code du travail et le Code pénal ; le salarié non déclaré n'a aucune protection.","themeLabel":"Mises en situation"},{"id":"S-09","theme":"situation","sous":"famille","q":"Un couple se marie uniquement à l'église. Quels effets ce mariage a-t-il en droit français ?","options":["Aucun : seul le mariage civil célébré à la mairie produit des effets juridiques","Il est valable mais uniquement pour les questions d'héritage","Il est valable si les deux époux ont la même religion","Il est valable pendant 5 ans, puis doit être confirmé"],"correct":0,"why":"En France, le mariage religieux n'a aucune valeur légale : il ne peut avoir lieu qu'après le mariage civil, et il n'ouvre aucun droit.","themeLabel":"Mises en situation"},{"id":"S-10","theme":"situation","sous":"famille","q":"Votre enfant de 5 ans refuse de s'habiller le matin ; vous êtes excédé(e) et tenté(e) de le frapper. Que dit la loi ?","options":["Les violences éducatives ordinaires sont interdites : il faut trouver d'autres réponses éducatives","La loi autorise une gifle si elle ne laisse pas de trace","La loi autorise la fessée jusqu'aux 6 ans de l'enfant","Seule la mère peut être sanctionnée en cas de violence"],"correct":0,"why":"Depuis la loi du 10 juillet 2019, l'autorité parentale s'exerce sans violence physique ni psychologique.","themeLabel":"Mises en situation"},{"id":"S-11","theme":"situation","sous":"sante","q":"Vous n'avez pas les moyens de payer une consultation chez le médecin. Quelles solutions existent ?","options":["La consultation peut être prise en charge par l'Assurance maladie (tiers payant) et par la complémentaire santé solidaire","Aucune : sans argent, les soins sont refusés en France","Il faut attendre l'hôpital public les urgences uniquement","Il faut payer, puis demander le remboursement total au maire"],"correct":0,"why":"La CMU-C devenue Complémentaire santé solidaire permet aux personnes à faibles ressources d'avoir des soins pris en charge, souvent sans avance de frais.","themeLabel":"Mises en situation"},{"id":"S-12","theme":"situation","sous":"travail","q":"Votre employeur vous licencie oralement, sans lettre ni entretien, parce que vous attendez un enfant. Que pouvez-vous faire ?","options":["Contester ce licenciement devant le conseil de prud'hommes : il est nul car fondé sur la grossesse","Accepter la décision : l'employeur est toujours libre de licencier","Négocier uniquement une indemnité, sans contester la cause","Déposer une plainte au pénal contre le maire de la commune"],"correct":0,"why":"Le licenciement d'une salariée enceinte fondé sur sa grossesse est nul ; il doit être contesté devant le conseil de prud'hommes (5 ans pour agir).","themeLabel":"Mises en situation"},{"id":"S-13","theme":"situation","sous":"ecole","q":"Votre enfant de 6 ans ne parle pas encore français et vous arrivez d'un pays étranger. Que se passe-t-il à l'école ?","options":["Il est inscrit à l'école de la commune et bénéficie d'un soutien pour apprendre le français","Il doit attendre de parler français pour être scolarisé","Il est automatiquement orienté vers un établissement spécialisé","Il ne peut être scolarisé que dans une école privée payante"],"correct":0,"why":"L'instruction est obligatoire dès 3 ans pour tous les enfants résidant en France, quelle que soit leur langue d'origine (dispositif UPE2A).","themeLabel":"Mises en situation"},{"id":"S-14","theme":"situation","sous":"numérique","q":"Vous recevez une vidéo humiliante d'un camarade de classe et on vous demande de la partager dans un groupe. Que faites-vous ?","options":["Je ne la partage pas : le cyberharcèlement est puni par la loi, et je peux le signaler","Je la partage, mais uniquement dans un groupe privé","Je la garde sans la diffuser, c'est sans conséquence","Je la diffuse pour que le camarade comprenne la leçon"],"correct":0,"why":"Le harcèlement en ligne est un délit, y compris pour les mineurs ; la diffusion d'images humiliantes peut être très lourdement sanctionnée.","themeLabel":"Mises en situation"},{"id":"S-15","theme":"situation","sous":"institutions","q":"Vous constatez que des travaux publics abîment votre jardin sans autorisation. Qui peut vous aider à faire valoir vos droits ?","options":["Le maire de votre commune, puis le Défenseur des droits si le litige persiste avec l'administration","Le Conseil constitutionnel directement","La Cour pénale internationale","Le Parlement européen"],"correct":0,"why":"Le maire est l'autorité de proximité ; le Défenseur des droits est compétent pour les litiges avec les services publics, gratuitement.","themeLabel":"Mises en situation"},{"id":"S-16","theme":"situation","sous":"justice","q":"Vous recevez une convocation pour être juré d'assises, mais votre employeur vous dit de ne pas y aller. Que devez-vous faire ?","options":["Vous présenter quand même : c'est une obligation civique, le refus est sanctionné par une amende","Suivre l'avis de votre employeur, qui a toujours raison","Répondre par courrier que vous refusez sans justification","Envoyer un membre de votre famille à votre place"],"correct":0,"why":"Le juré est tiré au sort : seul un motif grave, apprécié par le juge, peut l'exempter. L'employeur n'a pas à s'y opposer.","themeLabel":"Mises en situation"},{"id":"S-17","theme":"situation","sous":"logement","q":"Vous louez un appartement et le bailleur vous interdit d'y installer une machine à laver le linge. Que disent les règles ?","options":["Les petits travaux d'équipement courant du logement sont autorisés au locataire, sauf clause contraire abusive","Le locataire n'a jamais le droit d'installer un appareil sans accord écrit","Le bailleur peut interdire tout appareil électroménager","Le locataire doit obligatoirement acheter l'appareil du bailleur"],"correct":0,"why":"Le locataire dispose de la jouissance paisible du logement et peut faire les aménagements d'usage courant ; les clauses qui suppriment ce droit sont abusives.","themeLabel":"Mises en situation"},{"id":"S-18","theme":"situation","sous":"politique","q":"Vous n'êtes pas encore inscrit(e) sur les listes électorales et vous voulez voter à la prochaine élection. Que faites-vous ?","options":["Je m'inscris en mairie ou en ligne, avec une pièce d'identité et un justificatif de domicile","J'attends la convocation : l'inscription est automatique pour tous","Je demande au préfet de m'inscrire d'office","Je me présente au bureau de vote le jour J, l'inscription se fera sur place"],"correct":0,"why":"L'inscription est automatique à 18 ans après recensement, mais en cas de déménagement ou d'oubli elle doit être faite en mairie (ou en ligne).","themeLabel":"Mises en situation"},{"id":"S-19","theme":"situation","sous":"laicite","q":"Un gestionnaire d'un service public refuse de servir une personne portant un vêtement religieux visible. Ce refus est-il conforme ?","options":["Non : les usagers sont libres de leurs convictions, seuls les agents doivent être neutres","Oui : les usagers n'ont pas le droit d'exprimer leurs convictions","Oui, si le chef de service l'a autorisé par écrit","Non, sauf pour les services d'état civil"],"correct":0,"why":"La neutralité religieuse s'impose aux agents publics, pas aux usagers : refuser de servir un usager pour ce motif est une discrimination.","themeLabel":"Mises en situation"},{"id":"S-20","theme":"situation","sous":"civisme","q":"Vous conduisez et renversez un piéton sans le blesser gravement : vous êtes tenté(e) de partir. Que risque-t-on en fuyant ?","options":["Des peines aggravées : la fuite est un délit puni plus lourdement que l'accident lui-même","Rien si la victime n'est pas blessée","Une simple contravention de stationnement","Une amende de 20 €, payée plus tard à l'assurance"],"correct":0,"why":"La délit de fuite est puni de 3 ans d'emprisonnement et 75 000 € d'amende ; il faut s'arrêter, porter secours et laisser ses coordonnées.","themeLabel":"Mises en situation"},{"id":"S-21","theme":"situation","sous":"famille","q":"Vous attendez un enfant et vous vous demandez quelles démarches faire à la naissance. Que devez-vous faire ?","options":["Déclarer la naissance à la mairie du lieu de naissance dans les 5 jours","Déclarer la naissance seulement si les parents ne sont pas mariés","Déclarer la naissance au consulat du pays d'origine","Ne rien faire : l'hôpital déclare automatiquement l'enfant"],"correct":0,"why":"La déclaration à l'état civil doit être faite dans les 5 jours suivant la naissance ; elle est indispensable pour l'état civil de l'enfant.","themeLabel":"Mises en situation"},{"id":"S-22","theme":"situation","sous":"sante","q":"Un médecin refuse de vous soigner en apprenant que vous n'avez pas de papiers. Est-ce légal ?","options":["Non : tout médecin doit porter assistance ; les soins sont dus, quelle que soit la situation administrative","Oui : seuls les patients réguliers peuvent consulter","Oui, si le médecin redoute des complications administratives","Oui, sauf en cas d'urgence vitale uniquement"],"correct":0,"why":"Les personnes en situation irrégulière ont accès aux soins (AME, PASS) ; le refus de soins est interdit et peut être sanctionné.","themeLabel":"Mises en situation"},{"id":"S-23","theme":"situation","sous":"civilite","q":"Votre voisin ne respecte pas les règles de tri des déchets et brûle ses ordures dans son jardin. Que pouvez-vous faire ?","options":["Le signaler à la mairie : le brûlage des déchets est interdit et la mairie a un pouvoir de police","Rien : chacun fait ce qu'il veut dans son jardin","Brûler aussi vos déchets pour être traité à égalité","Attendre qu'un voisin appelle les pompiers"],"correct":0,"why":"Le brûlage à l'air libre des déchets (même verts) est interdit, pour des raisons de sécurité et de pollution ; la mairie est compétente.","themeLabel":"Mises en situation"},{"id":"S-24","theme":"situation","sous":"travail","q":"Votre employeur vous demande de travailler 50 heures par semaine sans heures supplémentaires payées. Que pouvez-vous faire ?","options":["Refuser cette charge au-delà des limites légales et saisir le conseil de prud'hommes si besoin","Obéir : l'employeur fixe librement la durée du travail","Négocier seulement un jour de congé en plus","Démissionner immédiatement, sans autre recours"],"correct":0,"why":"La durée légale est de 35 h et les heures supplémentaires doivent être payées ou récupérées ; l'employeur ne peut imposer un temps de travail illimité.","themeLabel":"Mises en situation"},{"id":"S-25","theme":"situation","sous":"institutions","q":"Vous voulez connaître le nom de votre député et le contacter. Où trouvez-vous cette information ?","options":["Sur le site de l'Assemblée nationale, en indiquant votre commune","Sur le site du Conseil constitutionnel","En appelant la Cour d'assises","Sur le site de la Banque de France"],"correct":0,"why":"Les 577 députés sont identifiables par circonscription sur le site de l'Assemblée nationale ; chacun dispose d'une permanence parlementaire.","themeLabel":"Mises en situation"},{"id":"S-26","theme":"situation","sous":"ecole","q":"Votre enfant est en situation de handicap et vous souhaitez qu'il soit scolarisé à l'école du quartier. Que faut-il savoir ?","options":["C'est un droit : l'école doit l'accueillir avec les aménagements nécessaires (AESH, matériel adapté)","L'inscription dépend d'un vote des autres parents d'élèves","Il doit être scolarisé uniquement en établissement spécialisé","L'accueil est possible seulement après 6 ans"],"correct":0,"why":"La loi du 11 février 2005 pose le principe de la scolarisation en milieu ordinaire : la MDPH évalue les besoins et l'Éducation nationale organise l'accompagnement.","themeLabel":"Mises en situation"},{"id":"S-27","theme":"situation","sous":"discriminations","q":"À l'entretien d'embauche, la recruteuse vous demande votre religion et si vous comptez avoir des enfants. Que pouvez-vous faire ?","options":["Répondre que ces questions sont interdites par la loi et saisir le Défenseur des droits si nécessaire","Répondre à tout : le recruteur a droit à ces informations","Mentir pour obtenir le poste, sans rien dire","Interrompre l'entretien et porter plainte au pénal immédiatement"],"correct":0,"why":"Ces questions sont discriminatoires ; le Défenseur des droits peut être saisi gratuitement, et l'employeur encourt des sanctions civiles et pénales.","themeLabel":"Mises en situation"},{"id":"S-28","theme":"situation","sous":"numérique","q":"Vous recevez un SMS vous annonçant un remboursement d'impôt et demandant vos coordonnées bancaires. Que faites-vous ?","options":["Je ne clique pas, je vérifie sur impots.gouv.fr et je signale le message (33700 ou signal-spam)","Je remplis le formulaire : l'administration a bien besoin de mon RIB","Je transfère le SMS à mes proches pour les prévenir","Je réponds avec mes coordonnées, mais sans mot de passe"],"correct":0,"why":"C'est une tentative d'hameçonnage (« phishing ») : l'administration fiscale ne demande jamais de données bancaires par SMS ou courriel.","themeLabel":"Mises en situation"},{"id":"S-29","theme":"situation","sous":"justice","q":"Vous êtes témoin d'un vol dans un magasin et on vous demande témoigner. Quel est votre devoir ?","options":["Témoigner devant la justice : refuser de témoigner peut être puni et peut coûter l'innocence d'une personne","Refuser de parler pour ne pas perdre de temps","Accepter uniquement si le gérant vous paye","Déposer une lettre anonyme pour ne pas être identifié"],"correct":0,"why":"En France, témoigner en justice est un devoir civique ; le faux témoignage et l'abstention sont susceptibles d'entraîner des sanctions.","themeLabel":"Mises en situation"},{"id":"S-30","theme":"situation","sous":"ecologie","q":"Vous voulez agir à votre échelle pour l'environnement. Quelles actions relèvent d'une démarche citoyenne ?","options":["Trier ses déchets, réduire sa consommation d'énergie et participer aux décisions locales (conseil de quartier, associations)","Attendre que les pays voisins agissent seuls","Brûler ses déchets pour éviter les décharges","Ignorer les consignes de tri : cela ne change rien"],"correct":0,"why":"La transition écologique repose aussi sur les gestes quotidiens et la participation citoyenne aux décisions locales (Charte de l'environnement, 2005).","themeLabel":"Mises en situation"},{"id":"V-01","theme":"vivre","page":"1789657471668","q":"Qui a le droit de se syndiquer ?","options":["Tout salarié, quel que soit son contrat de travail (CDI, CDD, intérim)","Uniquement les fonctionnaires titulaires","Uniquement les salariés en CDI depuis plus d'un an","Uniquement les salariés des entreprises de plus de 50 salariés"],"correct":0,"why":"La liberté syndicale est un droit fondamental reconnu à tout salarié (art. L.2141-1 du Code du travail).","themeLabel":"Vivre dans la société française"},{"id":"V-02","theme":"vivre","page":"1789657471668","q":"Est-il possible de licencier une femme enceinte ou en congé maternité, en raison de sa grossesse ?","options":["Oui, si l'employeur respecte un préavis de 15 jours","Non : la grossesse ne peut jamais être un motif de licenciement","Oui, mais seulement dans les entreprises de moins de 10 salariés","Oui, si la salariée est encore en période d'essai"],"correct":1,"why":"La salariée enceinte bénéficie d'une protection renforcée : le licenciement fondé sur la grossesse est nul (art. L.1225-4 du Code du travail).","themeLabel":"Vivre dans la société française"},{"id":"V-03","theme":"vivre","page":"1789657471668","q":"L'instruction des enfants est obligatoire de :","options":["6 ans à 16 ans","6 ans à 18 ans","3 ans à 16 ans","3 ans à 18 ans"],"correct":2,"why":"Depuis la loi du 26 juillet 2019, l'instruction est obligatoire dès 3 ans et jusqu'à 16 ans.","themeLabel":"Vivre dans la société française"},{"id":"V-04","theme":"vivre","page":"1789657471668","q":"Des parents ne respectent pas l'obligation d'instruction pour leurs enfants. Quelle sanction maximale risquent-ils ?","options":["6 mois d'emprisonnement et 5 000 € d'amende","1 an d'emprisonnement et 15 000 € d'amende","3 ans d'emprisonnement et 45 000 € d'amende","2 ans d'emprisonnement et 30 000 € d'amende"],"correct":3,"why":"Art. 227-17-1 du Code pénal : 2 ans d'emprisonnement et 30 000 € d'amende pour défaut d'instruction sans motif légitime.","themeLabel":"Vivre dans la société française"},{"id":"V-05","theme":"vivre","page":"1789657471668","q":"Quelle est la définition de l'autorité parentale ?","options":["Un ensemble de droits et de devoirs exercés dans l'intérêt de l'enfant (santé, sécurité, éducation, patrimoine)","Le droit du père de décider seul de l'éducation de l'enfant","Le droit d'éduquer son enfant comme on le souhaite, sans aucune limite","L'obligation d'héberger et d'entretenir son enfant jusqu'à ses 25 ans"],"correct":0,"why":"Art. 371-1 du Code civil : elle appartient aux deux parents en commun, jusqu'aux 18 ans de l'enfant.","themeLabel":"Vivre dans la société française"},{"id":"V-06","theme":"vivre","page":"1789657471668","q":"Quel motif d'absence est accepté par l'école ?","options":["Des vacances familiales prises en période scolaire","La fatigue de l'enfant invoquée par les parents","Une maladie de l'enfant, justifiée par un écrit des parents ou un certificat médical","Une sortie de loisirs organisée par la famille"],"correct":2,"why":"Seuls les motifs légitimes (maladie, convocation, événement familial grave) justifient une absence ; l'école exige un justificatif.","themeLabel":"Vivre dans la société française"},{"id":"V-07","theme":"vivre","page":"1789657471668","q":"Jusqu'à quel âge l'école est-elle obligatoire ?","options":["14 ans","16 ans","17 ans","18 ans"],"correct":1,"why":"L'instruction est obligatoire jusqu'à 16 ans révolus ; au-delà, elle reste possible (lycée, apprentissage).","themeLabel":"Vivre dans la société française"},{"id":"V-08","theme":"vivre","page":"1789657471668","q":"À quel âge commence l'instruction obligatoire des enfants ?","options":["2 ans","3 ans","5 ans","6 ans"],"correct":1,"why":"Depuis 2019, l'instruction est obligatoire à partir de 3 ans (avant, c'était 6 ans).","themeLabel":"Vivre dans la société française"},{"id":"V-09","theme":"vivre","page":"1789657471668","q":"Comment s'appellent les établissements scolaires que les élèves intègrent après l'école élémentaire ?","options":["Le lycée","L'université","Le collège","L'école maternelle"],"correct":2,"why":"Après l'école élémentaire (CP à CM2), les élèves entrent au collège, de la 6e à la 3e.","themeLabel":"Vivre dans la société française"},{"id":"V-10","theme":"vivre","page":"1789657471668","q":"En tant que parent d'élève, il est possible de :","options":["Choisir le professeur de son enfant pour l'année","Assister aux cours à la place de son enfant","Rencontrer les enseignants et voter aux élections des représentants de parents d'élèves","Modifier le programme scolaire de la classe"],"correct":2,"why":"Les parents sont représentés au conseil d'école ou d'administration et peuvent rencontrer les enseignants.","themeLabel":"Vivre dans la société française"},{"id":"V-11","theme":"vivre","page":"1789657471668","q":"Quelle instruction est prévue pour les enfants qui ne parlent pas français ?","options":["Ils sont inscrits une année en classe de CP quelle que soit leur classe d'âge","Ils bénéficient d'un dispositif d'apprentissage du français (UPE2A) et rejoignent progressivement une classe ordinaire","Ils ne sont scolarisés qu'après avoir appris le français seuls","Ils suivent les cours uniquement dans leur langue d'origine"],"correct":1,"why":"Les unités pédagogiques pour élèves allophones arrivants (UPE2A) assurent l'apprentissage intensif du français et l'inclusion en classe ordinaire.","themeLabel":"Vivre dans la société française"},{"id":"V-12","theme":"vivre","page":"1789657471668","q":"S'agissant de l'accueil des enfants en situation de handicap à l'école, laquelle des propositions est vraie ?","options":["L'enfant doit être scolarisé exclusivement en établissement spécialisé","L'école doit accueillir l'enfant, avec si nécessaire un accompagnant (AESH)","L'accueil en classe ordinaire exige l'accord écrit de tous les autres parents","L'État ne prend en charge aucun accompagnement"],"correct":1,"why":"La loi de 2005 pose le principe de l'école inclusive : la scolarisation en milieu ordinaire est la règle, avec les aménagements nécessaires.","themeLabel":"Vivre dans la société française"},{"id":"V-13","theme":"vivre","page":"1789657471668","q":"Depuis le 1er juillet 2021, quelle est la durée du congé paternité ?","options":["11 jours calendaires","18 jours calendaires","25 jours calendaires","30 jours calendaires"],"correct":2,"why":"Le congé de paternité et d'accueil de l'enfant est passé à 25 jours calendaires (28 jours en cas de naissances multiples).","themeLabel":"Vivre dans la société française"},{"id":"V-14","theme":"vivre","page":"1789657471668","q":"Est-ce possible de punir physiquement ses enfants ?","options":["Oui, tant que cela ne laisse pas de trace","Non : les violences éducatives ordinaires sont interdites par la loi","Oui, si l'enfant a plus de 8 ans","Oui, c'est laissé à l'appréciation de chaque famille"],"correct":1,"why":"La loi du 10 juillet 2019 a inscrit dans le Code civil l'interdiction de tout traitement cruel ou dégradant envers l'enfant.","themeLabel":"Vivre dans la société française"},{"id":"V-16","theme":"vivre","page":"1789657471675","q":"Quelle action peut réaliser le locataire d'un logement sans l'autorisation du propriétaire ?","options":["Abattre une cloison pour agrandir le séjour","Effectuer les menus travaux d'entretien courant du logement","Sous-louer une chambre à un tiers","Remplacer les fenêtres par du double vitrage"],"correct":1,"why":"Le locataire doit entretenir le logement (menues réparations) ; les transformations et travaux importants exigent l'accord du bailleur.","themeLabel":"Vivre dans la société française"},{"id":"V-17","theme":"vivre","page":"1789657471675","q":"Quel mariage est reconnu légalement ?","options":["Le mariage religieux célébré à l'église ou à la mosquée","Le mariage civil célébré à la mairie","La cérémonie célébrée devant un notaire","Le mariage célébré par un chef de communauté religieuse"],"correct":1,"why":"Seul le mariage civil célébré par l'officier d'état civil a une valeur juridique en France ; le mariage religieux peut suivre, mais ne le remplace pas.","themeLabel":"Vivre dans la société française"},{"id":"V-18","theme":"vivre","page":"1789657471675","q":"Le stationnement sur une place réservée aux personnes handicapées :","options":["Est autorisé pour un arrêt de moins de 10 minutes","Est interdit sans la carte mobilité inclusion (CMI) et passible d'une amende","Est autorisé si toutes les autres places sont occupées","Est autorisé pour les professionnels de santé en intervention"],"correct":1,"why":"L'usage de ces places est réservé aux titulaires de la CMI mention « stationnement » ; l'infraction est punie d'une amende (135 €).","themeLabel":"Vivre dans la société française"},{"id":"V-19","theme":"vivre","page":"1789657471675","q":"Si une machine à laver est cassée, il est possible de :","options":["Exiger un remboursement immédiat auprès du fabricant, sans démarche","Faire jouer la garantie légale de conformité auprès du vendeur (2 ans)","Porter plainte contre l'État pour défaut de contrôle","Rien : la garantie ne s'applique qu'aux téléphones"],"correct":1,"why":"La garantie légale de conformité est de 2 ans à compter de la livraison ; elle se demande au vendeur, pas au fabricant.","themeLabel":"Vivre dans la société française"},{"id":"V-20","theme":"vivre","page":"1789657471675","q":"Dans quel cas faut-il déclarer son enfant au service d'état civil ?","options":["Dans tous les cas : toute naissance doit être déclarée","Uniquement si les parents ne sont pas mariés","Uniquement si l'enfant naît à l'étranger","Uniquement si le père reconnaît l'enfant avant la naissance"],"correct":0,"why":"Toute naissance doit être déclarée à l'état civil, que les parents soient mariés ou non.","themeLabel":"Vivre dans la société française"},{"id":"V-21","theme":"vivre","page":"1789657471675","q":"Quand faut-il déclarer son enfant au service d'état civil ?","options":["Dans les 24 heures suivant la naissance","Dans les 5 jours suivant la naissance","Dans le mois suivant la naissance","Avant les 3 mois de l'enfant, lors de la première visite médicale"],"correct":1,"why":"Art. 55 du Code civil : la déclaration doit être faite dans les 5 jours de la naissance.","themeLabel":"Vivre dans la société française"},{"id":"V-22","theme":"vivre","page":"1789657471675","q":"Quel numéro d'urgence permet d'appeler la police ?","options":["Le 15","Le 17","Le 18","Le 19"],"correct":1,"why":"Le 17 permet de joindre la police ou la gendarmerie ; le 112 est le numéro d'urgence unique européen.","themeLabel":"Vivre dans la société française"},{"id":"V-23","theme":"vivre","page":"1789657471675","q":"Quel numéro d'urgence permet d'appeler le SAMU ?","options":["Le 15","Le 17","Le 18","Le 115"],"correct":0,"why":"Le 15 joint le SAMU (urgences médicales) ; le 115 est le numéro d'urgence sociale, le 18 celui des pompiers.","themeLabel":"Vivre dans la société française"},{"id":"V-24","theme":"vivre","page":"1789657471675","q":"Auprès de quelle institution les parents peuvent inscrire leurs enfants à l'école publique ?","options":["Le rectorat de l'académie","La mairie de leur commune","La préfecture du département","La direction de l'école, uniquement sur décision du directeur"],"correct":1,"why":"L'inscription en école maternelle ou élémentaire publique se fait à la mairie de la commune de résidence.","themeLabel":"Vivre dans la société française"},{"id":"V-26","theme":"vivre","page":"1789657471675","q":"Quelle aide permet aux personnes qui ont des difficultés financières d'avoir un avocat ?","options":["L'aide juridictionnelle","L'aide sociale à l'enfance","La protection juridique de la mairie","Le fonds de solidarité des avocats de France"],"correct":0,"why":"L'aide juridictionnelle prend en charge tout ou partie des frais d'avocat et de procédure selon les ressources.","themeLabel":"Vivre dans la société française"},{"id":"V-27","theme":"vivre","page":"1789657471675","q":"Qui peut demander le divorce de personnes mariées ?","options":["Uniquement le mari","Chacun des époux, ou les deux ensemble","Uniquement l'époux qui n'a commis aucune faute","Le maire de la commune, après 2 ans de séparation"],"correct":1,"why":"Le divorce peut être demandé par les deux époux (consentement mutuel) ou par un seul (divorce accepté ou contentieux).","themeLabel":"Vivre dans la société française"},{"id":"V-28","theme":"vivre","page":"1789657471675","q":"Auprès de quel organisme faut-il demander le remboursement des frais de santé ?","options":["La mairie de son domicile","Le département","L'Assurance maladie (CPAM)","La mutuelle uniquement"],"correct":2,"why":"L'Assurance maladie rembourse les soins selon les tarifs de la Sécurité sociale ; la mutuelle complète ce remboursement.","themeLabel":"Vivre dans la société française"},{"id":"V-29","theme":"vivre","page":"1789657471675","q":"La contraception :","options":["Est interdite aux personnes mineures","Nécessite l'accord écrit du conjoint","Est gratuite et anonyme pour les mineures et prise en charge jusqu'à 26 ans","Est réservée aux personnes mariées"],"correct":2,"why":"Depuis 2013 la contraception est gratuite et anonyme pour les mineures ; la prise en charge est étendue jusqu'à 26 ans.","themeLabel":"Vivre dans la société française"},{"id":"V-30","theme":"vivre","page":"1789657471675","q":"Qu'est-ce que le principe de confidentialité dans le domaine de la santé ?","options":["Le secret médical : ce qui est confié au médecin reste confidentiel","Le médecin doit informer la famille de tous les diagnostics","L'employeur a accès au dossier médical de ses salariés","Le patient ne peut pas consulter son propre dossier médical"],"correct":0,"why":"Le secret médical est garanti par la loi : il protège les informations de santé du patient, qui y a lui-même accès.","themeLabel":"Vivre dans la société française"},{"id":"V-32","theme":"vivre","page":"1789657471675","q":"À quoi sert une mutuelle santé ?","options":["À remplacer l'Assurance maladie pour tous les soins","À compléter les remboursements de l'Assurance maladie (complémentaire santé)","À payer moins d'impôts sur le revenu","À donner accès gratuitement à l'hôpital public"],"correct":1,"why":"La complémentaire santé (mutuelle) rembourse la part des frais non pris en charge par l'Assurance maladie.","themeLabel":"Vivre dans la société française"},{"id":"V-33","theme":"vivre","page":"1789657471675","q":"Qu'est-ce que le tiers payant ?","options":["Un tiers de la consultation reste à la charge du patient","Le patient ne paie pas le professionnel de santé : l'Assurance maladie le règle directement","Le patient doit payer pour trois personnes de sa famille","L'employeur rembourse la consultation de son salarié"],"correct":1,"why":"Le tiers payant dispense le patient d'avancer les frais : la caisse d'assurance maladie règle directement le professionnel de santé.","themeLabel":"Vivre dans la société française"},{"id":"V-35","theme":"vivre","page":"1789657471675","q":"L'avortement est-il possible en France ?","options":["Non, il est interdit sauf danger vital pour la mère","Oui : c'est un droit reconnu depuis la loi Veil de 1975, dans un délai légal de 14 semaines","Oui, jusqu'à 6 mois de grossesse","Oui, mais uniquement avec l'autorisation d'un juge"],"correct":1,"why":"La loi Veil (1975) a depénalisé l'IVG ; le délai légal est de 14 semaines de grossesse, et l'accès est garanti depuis 2024 par la Constitution.","themeLabel":"Vivre dans la société française"},{"id":"V-36","theme":"vivre","page":"1789657471675","q":"Travailler sans être déclaré est :","options":["Autorisé pour un emploi de moins de 3 mois","Autorisé si l'employeur et le salarié sont d'accord","Illégal : c'est le travail dissimulé, puni par le Code du travail et le Code pénal","Autorisé pour les personnes étrangères non résidentes"],"correct":2,"why":"Le travail dissimulé prive le salarié de ses droits (salaire minimum, retraite, assurance chômage) et expose l'employeur à des sanctions lourdes.","themeLabel":"Vivre dans la société française"},{"id":"V-37","theme":"vivre","page":"1789657471675","q":"Qu'est-ce que le SMIC ?","options":["Le salaire minimum légal en France (salaire minimum interprofessionnel de croissance)","Le salaire moyen des salariés français","Le montant maximum du salaire pour un débutant","Une aide de l'État versée aux salariés à temps partiel"],"correct":0,"why":"Le SMIC est le salaire minimum horaire en dessous duquel aucun salarié ne peut être payé (hors cas particuliers encadrés).","themeLabel":"Vivre dans la société française"},{"id":"V-38","theme":"vivre","page":"1789657471675","q":"Quelle est la première démarche à réaliser pour chercher un emploi ?","options":["Déposer une demande à la mairie de sa commune","S'inscrire à France Travail (anciennement Pôle emploi)","Créer sa propre entreprise","Demander une carte de séjour de travail"],"correct":1,"why":"L'inscription à France Travail permet d'être accompagné, d'accéder aux offres et de demander l'allocation chômage.","themeLabel":"Vivre dans la société française"},{"id":"V-39","theme":"vivre","page":"1789657471675","q":"Quelle est la durée légale du temps de travail par semaine ?","options":["32 heures","35 heures","39 heures","40 heures"],"correct":1,"why":"Depuis 2000, la durée légale du travail est de 35 heures par semaine pour un salarié à temps plein.","themeLabel":"Vivre dans la société française"},{"id":"V-40","theme":"vivre","page":"1789657471675","q":"Qui peut demander un congé parental d'éducation ?","options":["Uniquement la mère","Les deux parents salariés (père ou mère), après une naissance ou une adoption","Uniquement les fonctionnaires","Uniquement les parents d'au moins trois enfants"],"correct":1,"why":"Le congé parental d'éducation est ouvert au père comme à la mère, sans condition de rang de naissance.","themeLabel":"Vivre dans la société française"},{"id":"V-41","theme":"vivre","page":"1789657471675","q":"Une personne étrangère, en situation régulière, peut créer son entreprise :","options":["Non, jamais","Uniquement une entreprise individuelle","Oui, si son titre de séjour l'autorise à exercer une activité professionnelle","Uniquement après 10 ans de séjour en France"],"correct":2,"why":"La création d'entreprise est ouverte aux étrangers titulaires d'un titre de séjour autorisant le travail ou l'activité commerciale.","themeLabel":"Vivre dans la société française"},{"id":"V-43","theme":"vivre","page":"1789657471675","q":"Quels sont les textes qui définissent les règles au travail ?","options":["Le seul règlement intérieur de l'entreprise","Le Code du travail et la convention collective applicable à l'entreprise","Les usages fixés librement par l'employeur","Les accords internationaux des Nations unies"],"correct":1,"why":"Le Code du travail fixe les règles minimales et la convention collective les adapte au secteur ; le règlement intérieur ne peut y déroger défavorablement.","themeLabel":"Vivre dans la société française"},{"id":"V-44","theme":"vivre","page":"1789657471675","q":"Quelles sont les affaires traitées par le conseil de prud'hommes ?","options":["Les crimes les plus graves","Les divorces et les pensions alimentaires","Les litiges individuels entre salariés et employeurs liés au contrat de travail","Les litiges entre commerçants et leurs clients"],"correct":2,"why":"Le conseil de prud'hommes est la juridiction du travail : litiges individuels sur le contrat de travail (licenciement, salaires, heures...).","themeLabel":"Vivre dans la société française"},{"id":"H-01","theme":"histoire","page":"1789657471681","q":"Quel monument historique se trouve sur une île en Normandie ?","options":["Le Mont-Saint-Michel","Le château de Chambord","Le pont du Gard","La cathédrale de Reims"],"correct":0,"why":"Le Mont-Saint-Michel, en Normandie, est bâti sur un îlot rocheux ; Chambord est en Loir-et-Cher, le pont du Gard dans le Gard, Reims en Champagne.","themeLabel":"Histoire, géographie et culture"},{"id":"H-02","theme":"histoire","page":"1789657471681","q":"Quelle ville française fait partie des 10 plus grandes métropoles du pays ?","options":["Toulouse","Annecy","Lorient","Arles"],"correct":0,"why":"Toulouse est la 4e ville de France ; Annecy, Lorient et Arles sont des villes moyennes.","themeLabel":"Histoire, géographie et culture"},{"id":"H-03","theme":"histoire","page":"1789657471681","q":"Quelle île fait partie des Antilles françaises ?","options":["La Martinique","La Réunion","Mayotte","La Corse"],"correct":0,"why":"La Martinique et la Guadeloupe forment les Antilles françaises ; La Réunion, Mayotte et la Corse sont ailleurs.","themeLabel":"Histoire, géographie et culture"},{"id":"H-04","theme":"histoire","page":"1789657471681","q":"Quelle île est française ?","options":["La Réunion","Madagascar","L'île Maurice","Madère"],"correct":0,"why":"La Réunion est un département et région d'outre-mer français ; Madagascar, Maurice et Madère sont des États ou territoires étrangers.","themeLabel":"Histoire, géographie et culture"},{"id":"H-06","theme":"histoire","page":"1789657471681","q":"Quelle île française est située dans l'océan Indien ?","options":["La Réunion","La Guadeloupe","La Martinique","Saint-Pierre-et-Miquelon"],"correct":0,"why":"La Réunion et Mayotte sont les deux îles françaises de l'océan Indien.","themeLabel":"Histoire, géographie et culture"},{"id":"H-07","theme":"histoire","page":"1789657471681","q":"Quel département français a une frontière avec le Brésil ?","options":["La Guyane","La Guadeloupe","La Martinique","Saint-Barthélemy"],"correct":0,"why":"La Guyane, en Amérique du Sud, partage une frontière avec le Brésil et le Suriname.","themeLabel":"Histoire, géographie et culture"},{"id":"H-08","theme":"histoire","page":"1789657471681","q":"De quelle ville française décolle la fusée Ariane ?","options":["Kourou, en Guyane","Toulouse","Biscarrosse","Brétigny-sur-Orge"],"correct":0,"why":"Le Centre spatial guyanais, à Kourou, tire les lanceurs Ariane ; Toulouse abrite l'industrie aéronautique mais pas les tirs.","themeLabel":"Histoire, géographie et culture"},{"id":"H-09","theme":"histoire","page":"1789657471681","q":"Quelle mer ou océan borde la France métropolitaine ?","options":["La mer Méditerranée","La mer Noire","La mer Baltique","La mer Rouge"],"correct":0,"why":"La France métropolitaine est bordée par la mer du Nord, la Manche, l'océan Atlantique et la mer Méditerranée.","themeLabel":"Histoire, géographie et culture"},{"id":"H-10","theme":"histoire","page":"1789657471681","q":"Quelle mer se situe entre la France et l'Angleterre ?","options":["La Manche","La mer du Nord","Le golfe de Gascogne","La mer d'Irlande"],"correct":0,"why":"La Manche sépare la côte française (Normandie, Hauts-de-France) du sud de l'Angleterre ; le tunnel sous la Manche la traverse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-11","theme":"histoire","page":"1789657471681","q":"Quelle île est un département d'outre-mer français ?","options":["La Réunion","Madagascar","Haïti","Les îles Canaries"],"correct":0,"why":"La Réunion, la Guadeloupe, la Martinique, Mayotte et la Guyane sont les cinq départements d'outre-mer.","themeLabel":"Histoire, géographie et culture"},{"id":"H-12","theme":"histoire","page":"1789657471681","q":"Qu'est-ce que la France d'outre-mer ?","options":["L'ensemble des territoires français situés hors de la métropole, dont les DROM-COM","Les anciennes colonies françaises devenues indépendantes","Les pays où le français est la langue officielle","Les territoires français gérés par l'Union européenne"],"correct":0,"why":"La France d'outre-mer rassemble les DROM (Guadeloupe, Martinique, Guyane, La Réunion, Mayotte) et les COM, peuplés d'environ 2,8 millions d'habitants.","themeLabel":"Histoire, géographie et culture"},{"id":"H-13","theme":"histoire","page":"1789657471681","q":"Quelle est la population approximative de la France en 2025 ?","options":["Environ 68 millions d'habitants","Environ 52 millions d'habitants","Environ 80 millions d'habitants","Environ 95 millions d'habitants"],"correct":0,"why":"La France compte près de 68 millions d'habitants, métropole et outre-mer compris.","themeLabel":"Histoire, géographie et culture"},{"id":"H-14","theme":"histoire","page":"1789657471681","q":"Quel est le principal port maritime de France ?","options":["Marseille","Cherbourg","Saint-Malo","La Rochelle"],"correct":0,"why":"Marseille (avec Fos-sur-Mer) est le premier port français et méditerranéen ; Le Havre est le premier port à conteneurs.","themeLabel":"Histoire, géographie et culture"},{"id":"H-15","theme":"histoire","page":"1789657471681","q":"Combien y a-t-il de régions en France métropolitaine ?","options":["13","12","18","22"],"correct":0,"why":"Depuis 2016, la métropole compte 13 régions ; avec les 5 régions d'outre-mer, la France en compte 18.","themeLabel":"Histoire, géographie et culture"},{"id":"H-16","theme":"histoire","page":"1789657471681","q":"Quelle chaîne de montagnes est située entre la France et l'Espagne ?","options":["Les Pyrénées","Les Alpes","Le Jura","Les Vosges"],"correct":0,"why":"Les Pyrénées forment la frontière naturelle entre la France et l'Espagne (ou Andorre) sur environ 650 km.","themeLabel":"Histoire, géographie et culture"},{"id":"H-17","theme":"histoire","page":"1789657471681","q":"Quelle île française se trouve au sud-est du continent africain ?","options":["La Réunion","Mayotte","La Corse","Madagascar"],"correct":0,"why":"La Réunion se situe dans l'océan Indien, à environ 700 km à l'est de Madagascar.","themeLabel":"Histoire, géographie et culture"},{"id":"H-18","theme":"histoire","page":"1789657471681","q":"Quel est le chef-lieu de la région Auvergne-Rhône-Alpes ?","options":["Lyon","Clermont-Ferrand","Grenoble","Saint-Étienne"],"correct":0,"why":"Lyon est la préfecture de région Auvergne-Rhône-Alpes et la 3e ville de France ; Clermont-Ferrand est le chef-lieu du Puy-de-Dôme.","themeLabel":"Histoire, géographie et culture"},{"id":"H-19","theme":"histoire","page":"1789657471681","q":"Quel est le chef-lieu de la région Bretagne ?","options":["Rennes","Nantes","Quimper","Brest"],"correct":0,"why":"Rennes est la préfecture de la région Bretagne ; Nantes est la préfecture de la Loire-Atlantique, en Pays de la Loire depuis 1956.","themeLabel":"Histoire, géographie et culture"},{"id":"H-20","theme":"histoire","page":"1789657471681","q":"Quel est le chef-lieu de la région Provence-Alpes-Côte d'Azur ?","options":["Marseille","Nice","Toulon","Avignon"],"correct":0,"why":"Marseille est la préfecture de la région PACA et la 2e ville de France ; Nice et Toulon sont des préfectures de département.","themeLabel":"Histoire, géographie et culture"},{"id":"H-21","theme":"histoire","page":"1789657471681","q":"Quel est le 101ᵉ département français depuis 2011 ?","options":["Mayotte","La Réunion","La Guyane","La Corse-du-Sud"],"correct":0,"why":"Mayotte est devenue le 101e département français le 31 mars 2011, après la Corse-du-Sud et la Haute-Corse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-22","theme":"histoire","page":"1789657471681","q":"Quelle région française est réputée pour ses stations de ski ?","options":["Auvergne-Rhône-Alpes","La Bretagne","Les Hauts-de-France","Le Grand Est"],"correct":0,"why":"Les plus grandes stations (Chamonix, Val-d'Isère, Les Deux-Alpes, Courchevel) se trouvent en Savoie, Haute-Savoie et Isère, en Auvergne-Rhône-Alpes.","themeLabel":"Histoire, géographie et culture"},{"id":"H-24","theme":"histoire","page":"1789657471689","q":"Quelle organisation a été créée en 1945 après la Seconde Guerre mondiale ?","options":["L'Organisation des Nations unies (ONU)","L'Union européenne","L'OTAN","Le Conseil de l'Europe"],"correct":0,"why":"L'ONU a été fondée le 24 octobre 1945 à San Francisco ; l'OTAN et le Conseil de l'Europe datent de 1949.","themeLabel":"Histoire, géographie et culture"},{"id":"H-25","theme":"histoire","page":"1789657471689","q":"En quelle année l'euro est-il devenu la monnaie officielle de la France ?","options":["2002","1992","1999","2005"],"correct":0,"why":"Les pièces et billets en euros ont circulé à partir du 1er janvier 2002 ; l'euro existait comme monnaie scripturale depuis 1999.","themeLabel":"Histoire, géographie et culture"},{"id":"H-26","theme":"histoire","page":"1789657471689","q":"Lors de la Seconde Guerre mondiale, à quelle date la ville de Paris a-t-elle été libérée ?","options":["Le 25 août 1944","Le 6 juin 1944","Le 8 mai 1945","Le 11 novembre 1918"],"correct":0,"why":"Paris a été libérée le 25 août 1944 ; le 6 juin 1944 est le Débarquement en Normandie, le 8 mai 1945 la capitulation allemande.","themeLabel":"Histoire, géographie et culture"},{"id":"H-27","theme":"histoire","page":"1789657471689","q":"Quel était le principal port français impliqué dans la traite négrière au XVIIᵉ siècle ?","options":["Nantes","Bordeaux","Marseille","Rouen"],"correct":0,"why":"Nantes, La Rochelle et Bordeaux ont été les grands ports négriers : Nantes a armé environ 45 % des expéditions françaises.","themeLabel":"Histoire, géographie et culture"},{"id":"H-28","theme":"histoire","page":"1789657471689","q":"Quel célèbre philosophe des Lumières a dénoncé l'esclavage ?","options":["Montesquieu","Molière","Jean Racine","Bossuet"],"correct":0,"why":"Montesquieu (1689-1755) a dénoncé l'esclavage dans De l'esprit des lois ; les autres auteurs cités étaient du XVIIe siècle et ne traitaient pas ce sujet.","themeLabel":"Histoire, géographie et culture"},{"id":"H-29","theme":"histoire","page":"1789657471689","q":"Quelle œuvre a été écrite par Victor Hugo ?","options":["Les Misérables","Le Rouge et le Noir","Madame Bovary","La Comédie humaine"],"correct":0,"why":"Les Misérables (1862) est de Victor Hugo ; Le Rouge et le Noir est de Stendhal, Madame Bovary de Flaubert, La Comédie humaine de Balzac.","themeLabel":"Histoire, géographie et culture"},{"id":"H-30","theme":"histoire","page":"1789657471689","q":"Quel peintre est français ?","options":["Claude Monet","Pablo Picasso","Vincent van Gogh","Léonard de Vinci"],"correct":0,"why":"Claude Monet (1840-1926) est un peintre français, chef de file de l'impressionnisme ; Picasso était espagnol, Van Gogh néerlandais, Vinci italien.","themeLabel":"Histoire, géographie et culture"},{"id":"H-34","theme":"histoire","page":"1789657471689","q":"Dans quel grand musée parisien est exposée la Joconde ?","options":["Le musée du Louvre","Le musée d'Orsay","Le Centre Pompidou","Le musée de l'Orangerie"],"correct":0,"why":"La Joconde (Léonard de Vinci) est exposée au Louvre, dans la salle des États.","themeLabel":"Histoire, géographie et culture"},{"id":"H-35","theme":"histoire","page":"1789657471689","q":"Quel château célèbre se trouve près de Paris et symbolise le pouvoir royal de Louis XIV ?","options":["Le château de Versailles","Le château de Chambord","Le château de Chenonceau","Le château du Haut-Kœnigsbourg"],"correct":0,"why":"Versailles, à 20 km de Paris, a été agrandi par Louis XIV qui y installe la cour à partir de 1682.","themeLabel":"Histoire, géographie et culture"},{"id":"H-37","theme":"histoire","page":"1789657471689","q":"Quel peintre célèbre a peint les Nymphéas ?","options":["Claude Monet","Édouard Manet","Paul Gauguin","Henri Matisse"],"correct":0,"why":"Monet a peint sa série des Nymphéas à Giverny ; elles sont exposées au musée de l'Orangerie à Paris.","themeLabel":"Histoire, géographie et culture"},{"id":"H-38","theme":"histoire","page":"1789657471689","q":"Pendant quelles journées peut-on visiter gratuitement des lieux culturels en France ?","options":["Les Journées européennes du patrimoine, le 3ᵉ week-end de septembre","La Fête de la musique, le 21 juin","Le 14 juillet","Le 1ᵉʳ janvier"],"correct":0,"why":"Les Journées du patrimoine (créées en 1984) ouvrent gratuitement de nombreux monuments ; de nombreux musées nationaux sont aussi gratuits toute l'année pour les moins de 26 ans.","themeLabel":"Histoire, géographie et culture"},{"id":"H-39","theme":"histoire","page":"1789657471689","q":"Que symbolise le 1ᵉʳ mai ?","options":["La fête du Travail","La victoire des Alliés en 1945","La prise de la Bastille","L'armistice de 1918"],"correct":0,"why":"Le 1er mai est la Journée internationale des travailleurs, fériée et chômée en France ; le muguet y est traditionnellement offert.","themeLabel":"Histoire, géographie et culture"},{"id":"H-40","theme":"histoire","page":"1789657471689","q":"Qui était Monsieur Rouget de Lisle ?","options":["L'auteur de La Marseillaise","L'auteur de l'hymne européen","Un roi de France","L'inventeur du drapeau tricolore"],"correct":0,"why":"Claude Joseph Rouget de Lisle a composé en 1792 le Chant de guerre pour l'armée du Rhin, devenu La Marseillaise en 1795, hymne national en 1879.","themeLabel":"Histoire, géographie et culture"},{"id":"H-41","theme":"histoire","page":"1789657471689","q":"À quelle occasion a été construite la Tour Eiffel ?","options":["L'Exposition universelle de 1889","L'Exposition universelle de 1900","Le bicentenaire de la Révolution, en 1989","Les Jeux olympiques de 1924"],"correct":0,"why":"Gustave Eiffel a construit la tour pour l'Exposition universelle de 1889, qui célébrait le centenaire de la Révolution française.","themeLabel":"Histoire, géographie et culture"},{"id":"H-42","theme":"histoire","page":"1789657471689","q":"Quelle chaîne de montagnes est située entre la France et l'Italie ?","options":["Les Alpes","Les Pyrénées","Le Jura","Le Massif central"],"correct":0,"why":"Les Alpes séparent la France de l'Italie (et de la Suisse) ; le Jura marque la frontière avec la Suisse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-48","theme":"histoire","page":"1789657471689","q":"Qui était Marguerite Yourcenar ?","options":["Une écrivaine, première femme élue à l'Académie française","Une chanteuse lyrique","Une physicienne","Une femme politique des années 1930"],"correct":0,"why":"Marguerite Yourcenar (1903-1987), auteure des Mémoires d'Hadrien, est entrée à l'Académie française en 1980.","themeLabel":"Histoire, géographie et culture"},{"id":"H-49","theme":"histoire","page":"1789657471689","q":"Qui était Paul Cézanne ?","options":["Un peintre post-impressionniste, précurseur du cubisme","Un écrivain naturaliste","Un compositeur de musique classique","Un architecte des châteaux de la Loire"],"correct":0,"why":"Cézanne (1839-1906), né à Aix-en-Provence, a peint la montagne Sainte-Victoire et inspiré Picasso.","themeLabel":"Histoire, géographie et culture"},{"id":"H-51","theme":"histoire","page":"1789657471689","q":"Qui était un célèbre compositeur français ?","options":["Maurice Ravel","Wolfgang Amadeus Mozart","Ludwig van Beethoven","Frédéric Chopin"],"correct":0,"why":"Ravel (1875-1937), auteur du Boléro, est français ; Mozart était autrichien, Beethoven allemand, Chopin polonais.","themeLabel":"Histoire, géographie et culture"},{"id":"H-52","theme":"histoire","page":"1789657471689","q":"Qui était Auguste Renoir ?","options":["Un peintre impressionniste","Un sculpteur","Un écrivain","Un musicien"],"correct":0,"why":"Pierre-Auguste Renoir (1841-1919) a peint Le Bal du moulin de la Galette et Les Baigneuses.","themeLabel":"Histoire, géographie et culture"},{"id":"H-53","theme":"histoire","page":"1789657471689","q":"Quel musée est situé à Paris ?","options":["Le Centre Pompidou","Le MuCEM","Le musée des Confluences","La Cité de l'espace"],"correct":0,"why":"Le Centre Pompidou (Beaubourg) est à Paris ; le MuCEM est à Marseille, les Confluences à Lyon, la Cité de l'espace à Toulouse.","themeLabel":"Histoire, géographie et culture"},{"id":"H-54","theme":"histoire","page":"1789657471698","q":"Parmi ces textes, lequel a été adopté sous Napoléon Iᵉʳ ?","options":["Le Code civil","La Déclaration des droits de l'homme et du citoyen","La loi de séparation des Églises et de l'État","La Constitution de la Vᵉ République"],"correct":0,"why":"Le Code civil (1804) organise le droit des personnes et des biens ; la Déclaration date de 1789, la loi de 1905, la Constitution de 1958.","themeLabel":"Histoire, géographie et culture"},{"id":"H-55","theme":"histoire","page":"1789657471698","q":"Qui a été président de la Vᵉ République ?","options":["Charles de Gaulle","Napoléon III","Louis XVI","Georges Clemenceau"],"correct":0,"why":"Charles de Gaulle a été le premier président de la Ve République (1959-1969) ; Clemenceau a été président du Conseil, jamais président de la République.","themeLabel":"Histoire, géographie et culture"},{"id":"H-56","theme":"histoire","page":"1789657471698","q":"Quel est l'objectif des lois scolaires de la IIIᵉ République ?","options":["Rendre l'école gratuite, laïque et obligatoire","Créer les premières universités","Développer l'enseignement privé religieux","Rendre l'école payante pour financer l'État"],"correct":0,"why":"Les lois Jules Ferry (1881-1882) instaurent gratuité, laïcité et obligation scolaire ; l'école publique était jusque-là souvent tenue par des congrégations.","themeLabel":"Histoire, géographie et culture"},{"id":"H-57","theme":"histoire","page":"1789657471698","q":"Que signifie la date du 14 juillet pour les Français ?","options":["La fête nationale, qui commémore la prise de la Bastille et la Fête de la Fédération","La fin de la Première Guerre mondiale","La libération de Paris","La capitulation de l'Allemagne en 1945"],"correct":0,"why":"Depuis 1880, le 14 juillet est la fête nationale : elle rappelle la prise de la Bastille (1789) et la Fête de la Fédération (1790).","themeLabel":"Histoire, géographie et culture"},{"id":"H-58","theme":"histoire","page":"1789657471698","q":"Pourquoi l'année 1958 est importante pour la France ?","options":["La Constitution de la Vᵉ République est adoptée","La Seconde Guerre mondiale se termine","L'euro est créé","L'esclavage est définitivement aboli"],"correct":0,"why":"La Constitution du 4 octobre 1958 fonde la Ve République et renforce le pouvoir du président ; de Gaulle revient au pouvoir.","themeLabel":"Histoire, géographie et culture"},{"id":"H-59","theme":"histoire","page":"1789657471698","q":"Lequel de ces pays est un pays fondateur de l'Union européenne ?","options":["L'Italie","L'Espagne","Le Royaume-Uni","La Pologne"],"correct":0,"why":"Les six membres fondateurs (1951-1957) sont la France, l'Allemagne, l'Italie, la Belgique, les Pays-Bas et le Luxembourg ; l'Espagne est entrée en 1986, le Royaume-Uni en 1973, la Pologne en 2004.","themeLabel":"Histoire, géographie et culture"},{"id":"H-60","theme":"histoire","page":"1789657471698","q":"Simone Veil est une figure importante de l'histoire française. Elle a notamment :","options":["Fait adopter la loi de 1975 sur l'interruption volontaire de grossesse","Aboli la peine de mort en 1981","Fait voter la loi de séparation des Églises et de l'État","Créé la Sécurité sociale en 1945"],"correct":0,"why":"Ministre de la Santé, Simone Veil a porté la loi dépénalisant l'IVG (1975) ; elle a aussi été la première présidente du Parlement européen.","themeLabel":"Histoire, géographie et culture"},{"id":"H-61","theme":"histoire","page":"1789657471698","q":"Dans quelle région est située une partie des plages du débarquement ayant permis d'engager la libération de la France ?","options":["La Normandie","La Bretagne","Les Hauts-de-France","La Nouvelle-Aquitaine"],"correct":0,"why":"Le 6 juin 1944, les Alliés débarquent sur cinq plages normandes (Utah, Omaha, Gold, Juno, Sword) ; un second débarquement a lieu en Provence en août 1944.","themeLabel":"Histoire, géographie et culture"},{"id":"H-62","theme":"histoire","page":"1789657471698","q":"Dans quelle ville les rois de France étaient-ils couronnés ?","options":["Reims","Paris","Versailles","Orléans"],"correct":0,"why":"La cathédrale de Reims accueillait le sacre des rois de France depuis Clovis ; le dernier sacre est celui de Charles X en 1825.","themeLabel":"Histoire, géographie et culture"},{"id":"H-63","theme":"histoire","page":"1789657471698","q":"Quel roi de France a été guillotiné pendant la Révolution française ?","options":["Louis XVI","Louis XIV","Louis-Philippe","Napoléon III"],"correct":0,"why":"Louis XVI a été exécuté le 21 janvier 1793 place de la Révolution (aujourd'hui place de la Concorde) ; Louis XIV est mort en 1715, les deux autres ont régné après.","themeLabel":"Histoire, géographie et culture"},{"id":"H-64","theme":"histoire","page":"1789657471698","q":"En quelle année a débuté la Révolution française ?","options":["1789","1792","1799","1815"],"correct":0,"why":"La Révolution débute en 1789 (États généraux, prise de la Bastille le 14 juillet, Déclaration des droits de l'homme) ; 1792 marque la proclamation de la République.","themeLabel":"Histoire, géographie et culture"},{"id":"H-65","theme":"histoire","page":"1789657471698","q":"En quelle année Napoléon Iᵉʳ est-il devenu empereur ?","options":["1804","1789","1799","1815"],"correct":0,"why":"Napoléon est sacré empereur le 2 décembre 1804 ; 1799 est son arrivée au pouvoir (18 Brumaire), 1815 Waterloo et sa chute définitive.","themeLabel":"Histoire, géographie et culture"},{"id":"H-66","theme":"histoire","page":"1789657471698","q":"Lequel de ces personnages a un lien avec la République française ?","options":["Marianne","Louis XIV","Napoléon III","Marie-Antoinette"],"correct":0,"why":"Marianne incarne la République depuis la Révolution : son buste figure dans les mairies et sur les documents officiels ; les autres sont des figures de la monarchie ou de l'Empire.","themeLabel":"Histoire, géographie et culture"},{"id":"H-69","theme":"histoire","page":"1789657471698","q":"Quel pays a été une colonie française ?","options":["Le Sénégal","Le Portugal","La Belgique","La Grèce"],"correct":0,"why":"Le Sénégal a été une colonie française jusqu'en 1960 ; le Portugal, la Belgique et la Grèce n'ont jamais été colonisés par la France.","themeLabel":"Histoire, géographie et culture"},{"id":"H-71","theme":"histoire","page":"1789657471698","q":"Depuis quand les Français élisent-ils le président de la République au suffrage universel direct ?","options":["Depuis 1962","Depuis 1958","Depuis 1946","Depuis 1981"],"correct":0,"why":"Le référendum du 28 octobre 1962 a instauré l'élection du président au suffrage universel direct ; la première élection de ce type a eu lieu en 1965.","themeLabel":"Histoire, géographie et culture"},{"id":"H-72","theme":"histoire","page":"1789657471698","q":"En quelle année l'Union européenne a-t-elle été fondée ?","options":["1992","1951","1957","2002"],"correct":0,"why":"Le traité de Maastricht (1992) crée l'Union européenne ; 1951 (CECA) et 1957 (traité de Rome) sont les étapes de la construction européenne.","themeLabel":"Histoire, géographie et culture"},{"id":"H-73","theme":"histoire","page":"1789657471698","q":"Quand a eu lieu la Seconde Guerre mondiale ?","options":["De 1939 à 1945","De 1914 à 1918","De 1940 à 1944","De 1936 à 1946"],"correct":0,"why":"La Seconde Guerre mondiale dure du 1er septembre 1939 au 2 septembre 1945 ; la France est occupée à partir de juin 1940.","themeLabel":"Histoire, géographie et culture"},{"id":"H-74","theme":"histoire","page":"1789657471698","q":"Quand a eu lieu la Première Guerre mondiale ?","options":["De 1914 à 1918","De 1870 à 1871","De 1939 à 1945","De 1905 à 1910"],"correct":0,"why":"La Première Guerre mondiale (la « Grande Guerre ») oppose les Alliés aux Empires centraux de 1914 à 1918 ; l'armistice est signé le 11 novembre 1918.","themeLabel":"Histoire, géographie et culture"},{"id":"H-75","theme":"histoire","page":"1789657471698","q":"Sous quel président a été abolie la peine de mort en France ?","options":["François Mitterrand","Valéry Giscard d'Estaing","Jacques Chirac","Charles de Gaulle"],"correct":0,"why":"La loi du 9 octobre 1981, portée par le garde des Sceaux Robert Badinter sous la présidence de François Mitterrand, a aboli la peine de mort ; la dernière exécution datait de 1977.","themeLabel":"Histoire, géographie et culture"},{"id":"H-76","theme":"histoire","page":"1789657471698","q":"Que célèbre-t-on le 8 mai ?","options":["La capitulation de l'Allemagne nazie et la victoire des Alliés en 1945","L'armistice de 1918","La libération de Paris","La fin de la guerre d'Algérie"],"correct":0,"why":"Le 8 mai 1945 marque la fin des combats en Europe ; commémoré d'abord en 1953, il est jour férié depuis 1981.","themeLabel":"Histoire, géographie et culture"},{"id":"H-77","theme":"histoire","page":"1789657471698","q":"Quelle est la première étape de la construction européenne en 1951 ?","options":["La Communauté européenne du charbon et de l'acier (CECA)","Le traité de Rome","Le traité de Maastricht","La création de l'euro"],"correct":0,"why":"Six pays (dont la France) fondent la CECA en 1951 ; le traité de Rome crée la CEE en 1957.","themeLabel":"Histoire, géographie et culture"},{"id":"H-78","theme":"histoire","page":"1789657471698","q":"Qui était une figure de la Résistance française pendant la Seconde Guerre mondiale ?","options":["Jean Moulin","Le maréchal Pétain","Pierre Laval","Napoléon III"],"correct":0,"why":"Jean Moulin a unifié les mouvements de résistance pour le Conseil national de la Résistance en 1943 ; Pétain et Laval ont collaboré avec l'occupant.","themeLabel":"Histoire, géographie et culture"},{"id":"H-79","theme":"histoire","page":"1789657471698","q":"Le 11 novembre est un jour férié. À quoi correspond cette date ?","options":["L'armistice de 1918, qui met fin aux combats de la Première Guerre mondiale","La fin de la Seconde Guerre mondiale","La prise de la Bastille","L'appel du 18 juin"],"correct":0,"why":"L'armistice de Rethondes est signé le 11 novembre 1918 ; la date est commémorée depuis 1922.","themeLabel":"Histoire, géographie et culture"},{"id":"H-80","theme":"histoire","page":"1789657471698","q":"Depuis quand l'esclavage a-t-il été aboli définitivement en France ?","options":["1848","1789","1794","1905"],"correct":0,"why":"Le décret du 27 avril 1848, porté par Victor Schœlcher, abolit définitivement l'esclavage. La Convention l'avait aboli en 1794, mais Napoléon l'avait rétabli en 1802.","themeLabel":"Histoire, géographie et culture"},{"id":"H-81","theme":"histoire","page":"1789657471698","q":"Qui a aboli l'esclavage en France en 1848 ?","options":["Victor Schœlcher","Jules Ferry","Montesquieu","Napoléon Iᵉʳ"],"correct":0,"why":"Victor Schœlcher, sous-secrétaire d'État à la Marine, a rédigé le décret d'abolition ; une journée nationale lui est consacrée le 10 mai.","themeLabel":"Histoire, géographie et culture"},{"id":"H-82","theme":"histoire","page":"1789657471698","q":"Depuis quelle année l'école publique est-elle gratuite ?","options":["1881","1789","1905","1958"],"correct":0,"why":"La loi du 16 juin 1881 rend l'enseignement primaire public gratuit ; la loi du 28 mars 1882 le rend laïque et obligatoire.","themeLabel":"Histoire, géographie et culture"},{"id":"H-83","theme":"histoire","page":"1789657471698","q":"En 1944, qu'est-ce qui a changé pour les femmes ?","options":["Elles ont obtenu le droit de vote","Elles ont obtenu le droit à l'avortement","Elles ont obtenu le droit de divorcer","Elles ont obtenu le droit d'ouvrir un compte bancaire"],"correct":0,"why":"L'ordonnance du 21 avril 1944 accorde le droit de vote aux femmes, qui votent pour la première fois aux municipales d'avril 1945.","themeLabel":"Histoire, géographie et culture"},{"id":"D-01","theme":"droits","page":"1789657471705","q":"Que doit faire un citoyen s'il est appelé à être juré dans un procès d'assises ?","options":["Se présenter à la date indiquée et accomplir son devoir de juré","Renvoyer la convocation sans justification","Payer une amende pour se faire dispenser","Envoyer un proche pour le remplacer"],"correct":0,"why":"Être juré est une obligation civique : la convocation doit être honorée, sauf motif grave examiné par le juge. Refuser expose à une amende.","themeLabel":"Droits et devoirs"},{"id":"D-02","theme":"droits","page":"1789657471705","q":"Quel est l'âge de la majorité civile en France ?","options":["18 ans","16 ans","21 ans","25 ans"],"correct":0,"why":"Depuis 1974, la majorité est fixée à 18 ans : on devient pleinement capable de ses droits et devoirs (vote, contrat, responsabilité).","themeLabel":"Droits et devoirs"},{"id":"D-03","theme":"droits","page":"1789657471705","q":"Quel est l'un des devoirs principaux d'un citoyen français ?","options":["Respecter la loi et participer aux charges publiques en payant ses impôts","Voter à toutes les élections","Adhérer à un parti politique","Résider en France toute l'année"],"correct":0,"why":"Le respect de la loi, le paiement de l'impôt, le devoir de solidarité et le devoir de mémoire sont les devoirs du citoyen ; le vote est un droit, non une obligation.","themeLabel":"Droits et devoirs"},{"id":"D-04","theme":"droits","page":"1789657471705","q":"Quelle est l'infraction la plus grave ?","options":["Le crime","La contravention","Le délit","L'incivilité"],"correct":0,"why":"Les infractions se classent en trois niveaux : la contravention (amende), le délit (tribunal correctionnel), le crime (cour d'assises, peine de prison la plus lourde).","themeLabel":"Droits et devoirs"},{"id":"D-05","theme":"droits","page":"1789657471705","q":"Qu'est-ce que la citoyenneté numérique ?","options":["L'usage responsable et respectueux des outils numériques et des réseaux sociaux","Le fait de posséder un ordinateur et un smartphone","L'obligation de déclarer ses impôts en ligne","Le droit de créer une entreprise sur internet"],"correct":0,"why":"La citoyenneté numérique regroupe les règles de respect d'autrui en ligne, la protection des données personnelles et le refus du cyberharcèlement.","themeLabel":"Droits et devoirs"},{"id":"D-06","theme":"droits","page":"1789657471705","q":"Qu'est-ce que le devoir de mémoire ?","options":["L'obligation morale de transmettre le souvenir des événements douloureux du passé pour qu'ils ne se reproduisent pas","L'obligation d'apprendre par cœur toutes les dates de l'histoire de France","L'entretien obligatoire des monuments aux morts par chaque citoyen","La célébration des victoires militaires de la France"],"correct":0,"why":"Le devoir de mémoire, notamment de la Shoah, se traduit par une journée nationale du souvenir (27 janvier) et par la transmission aux jeunes générations.","themeLabel":"Droits et devoirs"},{"id":"D-07","theme":"droits","page":"1789657471705","q":"Qui peut être appelé à faire partie d'un jury d'assises en France ?","options":["Tout citoyen français majeur inscrit sur les listes électorales, sachant lire et écrire","Uniquement les personnes ayant fait des études de droit","Uniquement les fonctionnaires en activité","Uniquement les personnes volontaires"],"correct":0,"why":"Le jury d'assises est composé de citoyens tirés au sort sur les listes électorales : c'est une participation directe du peuple à la justice.","themeLabel":"Droits et devoirs"},{"id":"D-08","theme":"droits","page":"1789657471705","q":"Une personne est privée de ses droits civils et politiques pendant 5 ans suite à une condamnation. Parmi ces propositions, laquelle est correcte ? « Pendant 5 ans… »","options":["Elle ne peut pas voter ni être candidate à une élection","Elle ne peut pas travailler","Elle ne peut pas se marier","Elle ne peut pas quitter le territoire français"],"correct":0,"why":"L'article 131-26 du Code pénal sanctionne la privation du droit de vote, d'éligibilité, d'exercer une fonction publique ou d'être juré.","themeLabel":"Droits et devoirs"},{"id":"D-09","theme":"droits","page":"1789657471714","q":"À quoi sert le droit de grève ?","options":["À exprimer des revendications professionnelles et collectives (salaires, conditions de travail)","À renverser un gouvernement élu","À empêcher les non-grévistes de travailler","À protester contre n'importe quelle loi, même sans lien avec le travail"],"correct":0,"why":"Le droit de grève est reconnu par la Constitution (préambule de 1946) : il sert à défendre des revendications professionnelles. Bloquer les non-grévistes est illégal.","themeLabel":"Droits et devoirs"},{"id":"D-10","theme":"droits","page":"1789657471714","q":"Au nom de quoi l'État justifie-t-il la restriction des droits ?","options":["L'intérêt général et la protection des droits d'autrui","La volonté personnelle du président de la République","La tradition et les coutumes locales","L'accord de la majorité religieuse du pays"],"correct":0,"why":"Les droits ne sont pas absolus : le législateur peut les encadrer pour protéger l'ordre public, la sécurité et les droits des autres, sous le contrôle du juge.","themeLabel":"Droits et devoirs"},{"id":"D-11","theme":"droits","page":"1789657471714","q":"Laquelle de ces citations est inscrite dans la Déclaration des droits de l'homme et du citoyen de 1789 ?","options":["« Les hommes naissent et demeurent libres et égaux en droits »","« L'État, c'est moi »","« Nul n'est censé ignorer la loi »","« La propriété, c'est le vol »"],"correct":0,"why":"L'article 1er de la Déclaration de 1789 ouvre sur cette phrase ; « L'État, c'est moi » est attribué à Louis XIV, les autres sont des adages ou des citations d'auteurs.","themeLabel":"Droits et devoirs"},{"id":"D-12","theme":"droits","page":"1789657471714","q":"L'article 4 de la Déclaration des droits de l'homme et du citoyen affirme que « la liberté consiste à pouvoir faire tout ce qui ne nuit pas à autrui ». Qu'est-ce que cela signifie ?","options":["La liberté s'exerce dans les limites du respect des droits des autres","On peut tout faire tant que la loi ne nous a pas punis","La liberté est un droit sans aucune limite","La liberté dépend de la fortune de chacun"],"correct":0,"why":"La liberté individuelle s'arrête là où commence celle des autres : la loi fixe ces limites (article 4 de la Déclaration de 1789).","themeLabel":"Droits et devoirs"},{"id":"D-13","theme":"droits","page":"1789657471714","q":"Que dit l'article 1er de la Constitution française ?","options":["La France est une République indivisible, laïque, démocratique et sociale","Le français est la langue de la République","Le président de la République est élu pour cinq ans","La devise de la République est « Liberté, Égalité, Fraternité »"],"correct":0,"why":"L'article 1er pose aussi l'égalité devant la loi et le respect de toutes les croyances ; la langue, l'emblème et la devise figurent à l'article 2.","themeLabel":"Droits et devoirs"},{"id":"D-14","theme":"droits","page":"1789657471714","q":"Que garantit la liberté de la presse ?","options":["La liberté d'informer et d'être informé, dans le respect de la loi","Le droit de publier des informations fausses sans conséquence","L'interdiction de critiquer le gouvernement","L'obligation pour les journaux de soutenir la majorité"],"correct":0,"why":"La loi du 29 juillet 1881 garantit la liberté de la presse ; ses abus (diffamation, fausses nouvelles, incitation à la haine) sont punis.","themeLabel":"Droits et devoirs"},{"id":"D-15","theme":"droits","page":"1789657471714","q":"Que permet la liberté de circulation ?","options":["Se déplacer librement dans le pays, le quitter et y revenir","Circuler sans aucun titre d'identité","Conduire sans permis sur les routes secondaires","S'installer sans formalité dans n'importe quel pays étranger"],"correct":0,"why":"La liberté d'aller et venir est une liberté fondamentale en France ; elle s'exerce dans le respect des règles d'identité et de police.","themeLabel":"Droits et devoirs"},{"id":"D-16","theme":"droits","page":"1789657471714","q":"Que signifie être citoyen d'un État ?","options":["Exercer les droits civils et politiques et participer à la vie de la cité, tout en respectant ses devoirs","Posséder un passeport du pays","Résider dans le pays depuis sa naissance","Payer des impôts, sans autre engagement"],"correct":0,"why":"La citoyenneté associe des droits (vote, protection, accès aux services publics) et des devoirs (loi, impôts, solidarité, défense).","themeLabel":"Droits et devoirs"},{"id":"D-17","theme":"droits","page":"1789657471714","q":"Que sont les droits fondamentaux ?","options":["Des droits essentiels garantis à toute personne : dignité, vie, liberté, égalité","Des droits réservés aux citoyens français de naissance","Des avantages accordés aux personnes élues","Des règles propres à chaque entreprise"],"correct":0,"why":"Les droits fondamentaux sont garantis par la Constitution, la Déclaration de 1789, la Convention européenne des droits de l'homme et d'autres textes internationaux.","themeLabel":"Droits et devoirs"},{"id":"D-18","theme":"droits","page":"1789657471714","q":"Quel droit protège une personne contre une arrestation arbitraire ?","options":["Le droit à la liberté et à la sûreté, qui soumet la détention au contrôle d'un juge","Le droit de grève","Le droit de vote","Le droit de propriété"],"correct":0,"why":"Nul ne peut être détenu arbitrairement : la garde à vue est limitée dans le temps et contrôlée par le procureur puis le juge.","themeLabel":"Droits et devoirs"},{"id":"D-19","theme":"droits","page":"1789657471714","q":"Quel est le texte fondateur établissant les droits de chaque citoyen ?","options":["La Déclaration des droits de l'homme et du citoyen de 1789","Le Code civil de 1804","Le Code du travail","Le traité de Maastricht"],"correct":0,"why":"Adoptée le 26 août 1789, la Déclaration fait partie du « bloc de constitutionnalité » : elle a valeur constitutionnelle en France.","themeLabel":"Droits et devoirs"},{"id":"D-20","theme":"droits","page":"1789657471714","q":"Quel texte affirme que tous les hommes naissent libres et égaux en droits ?","options":["La Déclaration des droits de l'homme et du citoyen de 1789","La Constitution de 1958 uniquement","Le Code du travail","La Charte de l'environnement"],"correct":0,"why":"Cette formule est l'article 1er de la Déclaration de 1789 ; la Constitution de 1958 y renvoie dans son préambule.","themeLabel":"Droits et devoirs"},{"id":"D-21","theme":"droits","page":"1789657471714","q":"Quelle situation est une atteinte à la dignité humaine ?","options":["Imposer à une personne de travailler sans salaire et de vivre dans des conditions indignes","Demander à un salarié de faire des heures supplémentaires rémunérées","Refuser une augmentation de salaire","Licencier un salarié pour faute professionnelle"],"correct":0,"why":"La traite des êtres humains, le travail forcé et l'hébergement indigne portent atteinte à la dignité, protégée par la loi et la Constitution.","themeLabel":"Droits et devoirs"},{"id":"D-22","theme":"droits","page":"1789657471714","q":"Qu'est-ce que la liberté d'expression ?","options":["Le droit d'exprimer ses opinions et ses idées, dans les limites fixées par la loi","Le droit de tout dire, sans aucune limite","Le droit de mentir devant un tribunal","Le droit de publier un journal sans en être responsable"],"correct":0,"why":"La liberté d'expression est garantie, mais ses abus (diffamation, injure, incitation à la haine, négation de crimes contre l'humanité) sont sanctionnés.","themeLabel":"Droits et devoirs"},{"id":"D-23","theme":"droits","page":"1789657471714","q":"Suite à une interpellation par la police, il est possible de :","options":["Demander à être assisté d'un avocat et faire prévenir un proche","Refuser de donner son identité","Quitter le commissariat librement pendant la garde à vue","Refuser de signer le procès-verbal sans en recevoir copie"],"correct":0,"why":"Pendant une garde à vue, la personne peut demander un avocat, faire prévenir un proche et un employeur, et être examinée par un médecin.","themeLabel":"Droits et devoirs"},{"id":"D-24","theme":"droits","page":"1789657471714","q":"Tous les citoyens français ont-ils une religion ?","options":["Non : la liberté de conscience permet d'être croyant, athée ou agnostique","Oui, la République repose sur une religion officielle","Oui, tous les Français sont catholiques","Non, sauf les personnes naturalisées"],"correct":0,"why":"La laïcité garantit la liberté de croire ou de ne pas croire : l'article 1er de la Constitution assure le respect de toutes les croyances.","themeLabel":"Droits et devoirs"},{"id":"D-25","theme":"droits","page":"1789657471714","q":"À quel âge est la majorité numérique en France ?","options":["15 ans","13 ans","16 ans","18 ans"],"correct":0,"why":"Depuis la loi de 2023, les plateformes doivent obtenir l'accord d'un parent pour l'inscription d'un mineur de moins de 15 ans ; le droit à l'oubli numérique est renforcé à 15 ans.","themeLabel":"Droits et devoirs"},{"id":"D-26","theme":"droits","page":"1789657471714","q":"Dans lequel de ces endroits est-on autorisé à fumer ?","options":["Chez soi, dans un lieu privé","Dans la salle d'un restaurant","Dans la cour d'un lycée","Dans le métro"],"correct":0,"why":"Fumer est interdit dans tous les lieux publics fermés et couverts (loi de 2006) ; c'est autorisé dans les lieux privés, hors espaces fermés accueillant du public.","themeLabel":"Droits et devoirs"},{"id":"D-27","theme":"droits","page":"1789657471714","q":"En France, la conduite sans permis d'une moto est :","options":["Une infraction punie d'une amende et pouvant entraîner une peine de prison","Autorisée pour les mineurs de plus de 16 ans","Autorisée avec un permis voiture (catégorie B)","Sanctionnée d'un simple rappel à l'ordre"],"correct":0,"why":"Conduire sans permis est un délit : 15 000 € d'amende et jusqu'à un an d'emprisonnement, avec confiscation possible du véhicule.","themeLabel":"Droits et devoirs"},{"id":"D-28","theme":"droits","page":"1789657471714","q":"En quoi consiste le devoir de solidarité ?","options":["Contribuer à la solidarité nationale (impôts, cotisations, entraide) pour aider les personnes les plus fragiles","Verser chaque mois une somme à un voisin dans le besoin","Aider uniquement les membres de sa famille","Adhérer obligatoirement à une association caritative"],"correct":0,"why":"La solidarité est un principe constitutionnel : elle finance la Sécurité sociale, les minima sociaux et l'aide aux personnes en difficulté.","themeLabel":"Droits et devoirs"},{"id":"D-29","theme":"droits","page":"1789657471714","q":"Est-ce légal d'être marié à plusieurs personnes en même temps en France ?","options":["Non : la bigamie est interdite et punie par la loi","Oui, si les époux sont tous d'accord","Oui, avec l'autorisation du maire","Oui, si la première épouse réside à l'étranger"],"correct":0,"why":"Le mariage français est monogame : la bigamie est un délit puni d'un an d'emprisonnement et de 45 000 € d'amende.","themeLabel":"Droits et devoirs"},{"id":"D-30","theme":"droits","page":"1789657471714","q":"Est-ce obligatoire de déclarer ses impôts chaque année en France ?","options":["Oui : la déclaration de revenus est une obligation pour les personnes concernées","Non, la déclaration est purement facultative","Oui, mais uniquement pour les propriétaires immobiliers","Non, sauf si l'on demande une aide sociale"],"correct":0,"why":"Chaque foyer fiscal doit déclarer ses revenus, même si le montant à payer est nul : cette déclaration sert aussi à calculer certaines aides.","themeLabel":"Droits et devoirs"},{"id":"D-31","theme":"droits","page":"1789657471714","q":"Est-il obligatoire de porter secours à une personne en danger ?","options":["Oui : la non-assistance à personne en danger est un délit puni par la loi","Non, chacun est libre d'intervenir ou non","Oui, mais seulement pour les médecins et les secouristes","Oui, uniquement si la personne est sur le point de mourir"],"correct":0,"why":"L'article 223-6 du Code pénal punit la non-assistance à personne en danger de 5 ans d'emprisonnement et 75 000 € d'amende (7 ans et 100 000 € pour l'abstention volontaire de porter secours).","themeLabel":"Droits et devoirs"},{"id":"D-32","theme":"droits","page":"1789657471714","q":"Être juré d'assises est :","options":["Une obligation civique : ne pas répondre à la convocation est puni d'une amende","Un métier rémunéré à temps plein","Une activité facultative sur simple candidature","Une fonction réservée aux fonctionnaires"],"correct":0,"why":"Le juré est tiré au sort sur les listes électorales ; il doit se présenter, et ne peut être écarté que pour un motif grave reconnu par le juge.","themeLabel":"Droits et devoirs"},{"id":"D-33","theme":"droits","page":"1789657471714","q":"La vente d'alcool en France est interdite aux personnes de moins de :","options":["18 ans","16 ans","15 ans","21 ans"],"correct":0,"why":"Depuis 2009, la vente d'alcool est interdite aux mineurs de 18 ans ; la vente aux moins de 16 ans est en outre passible d'une amende aggravée.","themeLabel":"Droits et devoirs"},{"id":"D-34","theme":"droits","page":"1789657471714","q":"Le non-respect du code de la route est :","options":["Une infraction punie d'une amende, et parfois d'un retrait de points ou de permis","Un simple rappel à l'ordre du policier","Une infraction sanctionnée seulement en cas d'accident","Un litige de nature civile avec l'assurance"],"correct":0,"why":"Selon la gravité, l'infraction routière est une contravention ou un délit : amende, retrait de points, suspension de permis, voire prison.","themeLabel":"Droits et devoirs"},{"id":"D-35","theme":"droits","page":"1789657471714","q":"Lequel de ces crimes ou délits peut entraîner la privation des droits civils et politiques par un juge ?","options":["Une condamnation pour trafic de stupéfiants ou escroquerie","Une contravention pour stationnement interdit","Un retard de paiement de loyer","Un excès de vitesse de 10 km/h"],"correct":0,"why":"La privation des droits civiques est une peine complémentaire prévue pour les crimes et les délits graves : elle peut notamment interdire de voter pendant plusieurs années.","themeLabel":"Droits et devoirs"},{"id":"D-36","theme":"droits","page":"1789657471714","q":"Pour obtenir une carte d'identité, il faut :","options":["Se présenter en mairie avec une photo, un justificatif de domicile et l'ancienne carte ou un acte de naissance","Envoyer une simple demande écrite à la préfecture","Attendre d'avoir 18 ans et un emploi","La demander uniquement au consulat de France"],"correct":0,"why":"La demande se fait en mairie équipée d'une station d'enregistrement ; la présence du titulaire (et d'un parent pour un mineur) est obligatoire.","themeLabel":"Droits et devoirs"},{"id":"D-37","theme":"droits","page":"1789657471714","q":"Pour quel motif peut-on limiter la liberté d'expression ?","options":["Pour protéger les droits et la dignité d'autrui (diffamation, injure, incitation à la haine)","Pour empêcher toute critique du gouvernement","Pour éviter les débats contradictoires dans les médias","Pour réserver l'expression aux seuls journalistes professionnels"],"correct":0,"why":"En France, la critique des pouvoirs publics est libre ; seules les atteintes à autrui (appel à la haine, diffamation, apologie du terrorisme) sont interdites.","themeLabel":"Droits et devoirs"},{"id":"I-01","theme":"institutions","page":"1789657471730","q":"Comment est désigné le Premier ministre ?","options":["Il est nommé par le président de la République","Il est élu au suffrage universel direct","Il est élu par les députés","Il est désigné par le Sénat"],"correct":0,"why":"Le président de la République nomme le Premier ministre (art. 8 de la Constitution) ; il peut ensuite mettre fin à ses fonctions.","themeLabel":"Système institutionnel et politique"},{"id":"I-02","theme":"institutions","page":"1789657471730","q":"Qui peut se présenter aux élections présidentielles ?","options":["Toute personne de nationalité française, majeure, qui recueille 500 parrainages d'élus","Uniquement les anciens ministres","Uniquement les membres d'un parti représenté au Parlement","Toute personne résidant en France depuis 10 ans"],"correct":0,"why":"À retenir : Mêmes conditions que ci-dessus (art. 3 de la loi du 6 novembre 1962) : les parrainages doivent venir d'élus de 30 départements différents au moins. Les conditions : être Français, avoir 18 ans révolus, jouir de ses droits civiques et obtenir 500 signatures d'élus (parrainages).","themeLabel":"Système institutionnel et politique"},{"id":"I-05","theme":"institutions","page":"1789657471730","q":"L'inscription sur les listes électorales est :","options":["Obligatoire et automatique pour les jeunes dès leur recensement à 16 ans","Facultative et laissée à l'initiative de chacun","Réservée aux personnes qui paient l'impôt sur le revenu","Payante pour les élections locales"],"correct":0,"why":"Depuis 2019, l'inscription est automatique pour les jeunes recensés ; les personnes qui déménagent doivent actualiser leur inscription.","themeLabel":"Système institutionnel et politique"},{"id":"I-06","theme":"institutions","page":"1789657471730","q":"Quelle condition est nécessaire pour voter aux élections présidentielles ?","options":["Être de nationalité française, majeur, inscrit sur les listes électorales et jouir de ses droits civiques","Payer au moins un impôt en France","Résider en France depuis au moins 5 ans","Adhérer à un parti politique"],"correct":0,"why":"Seuls les Français inscrits sur les listes électorales votent aux présidentielles ; les ressortissants de l'UE votent uniquement aux municipales et européennes.","themeLabel":"Système institutionnel et politique"},{"id":"I-07","theme":"institutions","page":"1789657471730","q":"Quelle condition faut-il remplir pour être candidat aux élections municipales ?","options":["Être majeur, jouir de ses droits civiques et être inscrit sur la liste électorale de la commune (ou y être domicilié depuis 6 mois)","Résider dans la commune depuis au moins 10 ans","Avoir déjà été conseiller municipal","Être proposé par le préfet du département"],"correct":0,"why":"Pour être conseiller municipal : 18 ans, nationalité française ou ressortissant de l'UE, droits civiques, et inscription (ou attache locale) dans la commune.","themeLabel":"Système institutionnel et politique"},{"id":"I-08","theme":"institutions","page":"1789657471730","q":"Parmi ces autorités, laquelle est élue ?","options":["Le président de la République","Le préfet","Le Premier ministre","Le Défenseur des droits"],"correct":0,"why":"Le président est élu au suffrage universel direct ; le préfet, le Premier ministre et le Défenseur des droits sont nommés (décret ou nomination par le président).","themeLabel":"Système institutionnel et politique"},{"id":"I-10","theme":"institutions","page":"1789657471730","q":"Une personne n'ayant pas d'accès à internet veut s'inscrire sur les listes électorales. Où peut-elle s'inscrire ?","options":["À la mairie de sa commune","À la préfecture de son département","Au tribunal judiciaire","Dans n'importe quel commissariat de police"],"correct":0,"why":"L'inscription peut se faire en mairie, par courrier ou en ligne ; la mairie est le passage obligé pour les personnes non connectées.","themeLabel":"Système institutionnel et politique"},{"id":"I-11","theme":"institutions","page":"1789657471730","q":"À quel âge peut-on devenir électeur ?","options":["18 ans","16 ans","21 ans","Dès l'obtention d'un titre de séjour"],"correct":0,"why":"On est électeur à partir de 18 ans, à condition d'être inscrit sur les listes électorales et de jouir de ses droits civils et politiques.","themeLabel":"Système institutionnel et politique"},{"id":"I-12","theme":"institutions","page":"1789657471730","q":"En France, est-ce obligatoire de voter ?","options":["Non : le vote est un droit, pas une obligation légale","Oui, sous peine d'une amende","Oui, mais uniquement aux élections nationales","Oui, sauf pour les personnes étrangères"],"correct":0,"why":"Le vote est un droit et un devoir civique, mais l'abstention n'est pas sanctionnée ; seules les élections professionnelles obligatoires (comme les prud'hommes) sont concernées par des sanctions.","themeLabel":"Système institutionnel et politique"},{"id":"I-13","theme":"institutions","page":"1789657471730","q":"A-t-on le droit de ne pas respecter une loi ?","options":["Non : la loi s'impose à tous, son respect est obligatoire","Oui, si on l'estime injuste","Oui, si elle date de plus de dix ans","Oui, pour les personnes étrangères"],"correct":0,"why":"Nul n'est censé ignorer la loi : une loi jugée injuste doit être contestée par les voies légales (recours, élection des représentants), pas ignorée.","themeLabel":"Système institutionnel et politique"},{"id":"I-14","theme":"institutions","page":"1789657471730","q":"Comment sont désignés les députés ?","options":["Au suffrage universel direct, dans une circonscription, à deux tours","Au suffrage universel indirect, par les maires","Par le Sénat","Par le président de la République"],"correct":0,"why":"Les 577 députés sont élus pour 5 ans au scrutin majoritaire uninominal à deux tours dans leur circonscription.","themeLabel":"Système institutionnel et politique"},{"id":"I-16","theme":"institutions","page":"1789657471730","q":"La séparation des pouvoirs est un principe fondamental. Quels sont les trois pouvoirs concernés ?","options":["Le pouvoir législatif, le pouvoir exécutif et le pouvoir judiciaire","Le pouvoir du peuple, le pouvoir des médias et le pouvoir des juges","Le pouvoir civil, le pouvoir militaire et le pouvoir religieux","Le pouvoir central, le pouvoir régional et le pouvoir municipal"],"correct":0,"why":"Formulé par Montesquieu, ce principe sépare le pouvoir de faire la loi (Parlement), de l'appliquer (gouvernement) et de juger (tribunaux).","themeLabel":"Système institutionnel et politique"},{"id":"I-17","theme":"institutions","page":"1789657471730","q":"Qu'est-ce que l'État de droit ?","options":["Un principe selon lequel les pouvoirs publics sont eux-mêmes soumis au droit et chacun est jugé selon la loi","Un État qui compte beaucoup de lois","Un État dirigé par les juges","Un État sans Constitution"],"correct":0,"why":"Dans un État de droit, la puissance publique est encadrée par le droit : les citoyens comme l'administration peuvent être jugés et sanctionnés.","themeLabel":"Système institutionnel et politique"},{"id":"I-18","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat du conseil municipal et du maire ?","options":["6 ans","5 ans","3 ans","10 ans"],"correct":0,"why":"Les conseillers municipaux et le maire sont élus pour 6 ans ; les élections municipales ont lieu tous les 6 ans.","themeLabel":"Système institutionnel et politique"},{"id":"I-20","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat du président de la République française ?","options":["5 ans","4 ans","6 ans","7 ans"],"correct":0,"why":"Le quinquennat est en vigueur depuis 2000 (référendum) et s'applique depuis l'élection de 2002 ; le septennat a été abandonné.","themeLabel":"Système institutionnel et politique"},{"id":"I-21","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat des députés ?","options":["5 ans","3 ans","6 ans","9 ans"],"correct":0,"why":"Les députés sont élus pour 5 ans, sauf dissolution de l'Assemblée nationale par le président de la République.","themeLabel":"Système institutionnel et politique"},{"id":"I-22","theme":"institutions","page":"1789657471730","q":"Quelle est la durée du mandat des sénateurs ?","options":["6 ans","4 ans","5 ans","9 ans"],"correct":0,"why":"Les sénateurs sont élus pour 6 ans ; le Sénat est renouvelé par moitié tous les 3 ans.","themeLabel":"Système institutionnel et politique"},{"id":"I-24","theme":"institutions","page":"1789657471730","q":"En France, est-ce possible d'adhérer à un parti politique ?","options":["Oui : la liberté d'association et d'opinion le permet","Non, les partis politiques sont interdits","Oui, mais seulement à partir de 21 ans","Oui, avec l'autorisation du préfet"],"correct":0,"why":"La création et l'adhésion à un parti politique sont libres : les partis concourent à l'expression du suffrage (art. 4 de la Constitution).","themeLabel":"Système institutionnel et politique"},{"id":"I-26","theme":"institutions","page":"1789657471730","q":"Qui gère les collèges publics ?","options":["Le département (conseil départemental)","La commune","La région","L'État"],"correct":0,"why":"Le département gère les collèges, la région les lycées, la commune les écoles maternelles et élémentaires.","themeLabel":"Système institutionnel et politique"},{"id":"I-27","theme":"institutions","page":"1789657471730","q":"Qui gère les écoles primaires et maternelles publiques ?","options":["La commune (la mairie)","Le département","La région","Le rectorat d'académie"],"correct":0,"why":"La commune assure la construction, l'entretien et le fonctionnement des écoles publiques ; l'Éducation nationale recrute et affecte les enseignants.","themeLabel":"Système institutionnel et politique"},{"id":"I-28","theme":"institutions","page":"1789657471730","q":"Comment sont désignés les maires ?","options":["Par les conseillers municipaux, parmi eux, lors du premier conseil","Par les habitants, au suffrage universel direct","Par le préfet du département","Par le président de la République"],"correct":0,"why":"Les électeurs votent pour une liste de conseillers municipaux ; le maire est ensuite élu par le conseil municipal, en son sein.","themeLabel":"Système institutionnel et politique"},{"id":"I-29","theme":"institutions","page":"1789657471721","q":"Quelle est l'une des voies possibles pour modifier la Constitution ?","options":["Le référendum ou le vote du Parlement réuni en Congrès à la majorité des 3/5","Un décret du président de la République","Une loi ordinaire votée par les députés","Une décision du Conseil constitutionnel"],"correct":0,"why":"La révision constitutionnelle (art. 89) se fait par référendum ou par le Congrès (Assemblée + Sénat) à la majorité des trois cinquièmes.","themeLabel":"Système institutionnel et politique"},{"id":"I-30","theme":"institutions","page":"1789657471721","q":"Qui assure l'intérim du président de la République en cas de décès ?","options":["Le président du Sénat","Le Premier ministre","Le président de l'Assemblée nationale","Le garde des Sceaux"],"correct":0,"why":"Art. 7 de la Constitution : en cas de vacance, les fonctions sont assurées par le président du Sénat, et une élection doit se tenir sous 20 à 35 jours.","themeLabel":"Système institutionnel et politique"},{"id":"I-31","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du Conseil constitutionnel ?","options":["Contrôler la conformité des lois à la Constitution et veiller à la régularité des élections","Juger les crimes les plus graves","Voter le budget de l'État","Représenter la France à l'étranger"],"correct":0,"why":"Le Conseil constitutionnel contrôle les lois avant leur promulgation et valide les résultats des élections nationales (9 membres, nommés pour 9 ans).","themeLabel":"Système institutionnel et politique"},{"id":"I-32","theme":"institutions","page":"1789657471721","q":"Quelle condition est obligatoire pour se présenter à l'élection présidentielle ?","options":["Recueillir 500 signatures d'élus (parrainages)","Avoir plus de 25 ans","Avoir été ministre ou député","Être présenté par un parti politique"],"correct":0,"why":"L'âge minimum est de 18 ans ; le seul filtre est le parrainage de 500 élus, dont au moins 30 départements ou collectivités différents.","themeLabel":"Système institutionnel et politique"},{"id":"I-34","theme":"institutions","page":"1789657471721","q":"Comment est organisé le découpage administratif de la France ?","options":["En régions, départements et communes : 18 régions, 101 départements et près de 35 000 communes","En régions et départements uniquement","En 22 régions métropolitaines depuis 1982","En provinces, cantons et districts"],"correct":0,"why":"Depuis 2016, les 13 régions métropolitaines et les 5 régions d'outre-mer remplacent les 22 régions métropolitaines antérieures.","themeLabel":"Système institutionnel et politique"},{"id":"I-36","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du président de la République ?","options":["Il est chef de l'État : il promulgue les lois, nomme le Premier ministre et représente la France à l'étranger","Il vote les lois et le budget","Il rend la justice au nom du peuple","Il dirige les entreprises publiques"],"correct":0,"why":"Le président est élu pour 5 ans ; il peut dissoudre l'Assemblée nationale, saisir le Conseil constitutionnel et est le chef des armées.","themeLabel":"Système institutionnel et politique"},{"id":"I-37","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du Premier ministre ?","options":["Diriger l'action du gouvernement et conduire la politique de la Nation","Voter les lois","Présider le Conseil constitutionnel","Rendre la justice"],"correct":0,"why":"Le Premier ministre est responsable devant l'Assemblée nationale et coordonne les ministres ; il peut engager la responsabilité du gouvernement.","themeLabel":"Système institutionnel et politique"},{"id":"I-38","theme":"institutions","page":"1789657471721","q":"Quel est le rôle du Défenseur des droits ?","options":["Défendre les personnes dont les droits ne sont pas respectés, notamment face aux services publics","Voter les lois relatives aux droits humains","Juger les litiges entre particuliers","Représenter l'État devant les tribunaux"],"correct":0,"why":"Le Défenseur des droits est une autorité indépendante ; il peut être saisi gratuitement par tout citoyen (exemple : discrimination, conflit avec l'administration).","themeLabel":"Système institutionnel et politique"},{"id":"I-39","theme":"institutions","page":"1789657471721","q":"En quelle année la citoyenneté européenne a-t-elle été créée ?","options":["1992, par le traité de Maastricht","1957, par le traité de Rome","1979, date de la première élection du Parlement européen","2004, lors de l'élargissement à 10 pays"],"correct":0,"why":"Le traité de Maastricht crée la citoyenneté de l'Union : elle s'ajoute à la citoyenneté nationale et donne le droit de circuler et de voter localement dans l'UE.","themeLabel":"Système institutionnel et politique"},{"id":"I-40","theme":"institutions","page":"1789657471721","q":"Quel est le dernier État à avoir intégré l'Union européenne en 2013 ?","options":["La Croatie","La Bulgarie","La Roumanie","La Turquie"],"correct":0,"why":"La Croatie est devenue le 28e État membre le 1er juillet 2013 ; après le Brexit (2020), l'UE compte 27 États.","themeLabel":"Système institutionnel et politique"},{"id":"I-41","theme":"institutions","page":"1789657471721","q":"Qui a composé l'hymne de l'Union européenne ?","options":["Beethoven, à partir de l'Ode à la joie de sa 9ᵉ symphonie","Mozart","Jean-Baptiste Lully","Giuseppe Verdi"],"correct":0,"why":"L'hymne européen reprend l'Ode à la joie (1823) de Beethoven, sans paroles, pour éviter toute langue dominante.","themeLabel":"Système institutionnel et politique"},{"id":"I-43","theme":"institutions","page":"1789657471721","q":"Où est le siège de la Banque centrale européenne ?","options":["À Francfort, en Allemagne","À Bruxelles, en Belgique","À Luxembourg","À Strasbourg, en France"],"correct":0,"why":"La BCE, qui gère l'euro et la politique monétaire, siège à Francfort ; les autres institutions européennes sont à Bruxelles, Luxembourg et Strasbourg.","themeLabel":"Système institutionnel et politique"},{"id":"I-44","theme":"institutions","page":"1789657471721","q":"Où est le siège de la Commission européenne ?","options":["À Bruxelles, en Belgique","À Strasbourg, en France","À La Haye, aux Pays-Bas","À Genève, en Suisse"],"correct":0,"why":"La Commission siège à Bruxelles, comme le Conseil de l'UE ; le Parlement européen a son siège officiel à Strasbourg.","themeLabel":"Système institutionnel et politique"},{"id":"I-45","theme":"institutions","page":"1789657471721","q":"Qui siège au Parlement européen ?","options":["Les députés européens, élus au suffrage universel direct","Les ministres des États membres","Les chefs d'État et de gouvernement","Les juges de la Cour de justice"],"correct":0,"why":"Les députés européens sont élus pour 5 ans depuis 1979 ; le Parlement compte 720 membres depuis 2024.","themeLabel":"Système institutionnel et politique"},{"id":"I-46","theme":"institutions","page":"1789657471721","q":"Les citoyens de l'Union européenne peuvent-ils voter aux élections locales dans un autre État de l'Union ?","options":["Oui : ils votent aux élections municipales et européennes dans leur État de résidence","Non, jamais","Oui, à toutes les élections, y compris les présidentielles","Oui, mais seulement après 10 ans de résidence"],"correct":0,"why":"La citoyenneté européenne donne le droit de vote et d'éligibilité aux municipales et européennes dans l'État de résidence, pas aux élections nationales.","themeLabel":"Système institutionnel et politique"},{"id":"I-47","theme":"institutions","page":"1789657471721","q":"Combien d'États font partie de l'Union européenne au 1ᵉʳ janvier 2025 ?","options":["27","25","28","31"],"correct":0,"why":"Depuis le départ du Royaume-Uni en 2020, l'UE compte 27 États membres.","themeLabel":"Système institutionnel et politique"},{"id":"I-48","theme":"institutions","page":"1789657471721","q":"En quelle année le traité de Maastricht, qui marque la fondation de l'Union européenne, a-t-il été signé ?","options":["1992","1957","1986","2002"],"correct":0,"why":"Signé le 7 février 1992, il est entré en vigueur en 1993 ; il crée l'Union européenne et la citoyenneté européenne.","themeLabel":"Système institutionnel et politique"},{"id":"I-49","theme":"institutions","page":"1789657471721","q":"Quel traité concerne la construction de l'Union européenne ?","options":["Le traité de Maastricht","Le traité de Versailles","Le traité de l'Élysée","Le pacte de Varsovie"],"correct":0,"why":"Les traités de la construction européenne sont la CECA (1951), Rome (1957), Maastricht (1992), Amsterdam (1997), Nice (2001) et Lisbonne (2007).","themeLabel":"Système institutionnel et politique"},{"id":"I-50","theme":"institutions","page":"1789657471721","q":"Quel État a quitté l'Union européenne en 2020 ?","options":["Le Royaume-Uni","La Grèce","La Norvège","La Suisse"],"correct":0,"why":"Le Royaume-Uni est sorti de l'UE le 31 janvier 2020, après le référendum de 2016 (« Brexit ») ; la Norvège et la Suisse n'ont jamais été membres.","themeLabel":"Système institutionnel et politique"},{"id":"I-53","theme":"institutions","page":"1789657471721","q":"De quoi est composé le drapeau européen ?","options":["Douze étoiles d'or en cercle sur fond bleu","Vingt-sept étoiles d'or sur fond bleu","Six étoiles blanches sur fond bleu","Douze étoiles d'or sur fond rouge"],"correct":0,"why":"Le cercle de 12 étoiles symbolise la perfection, la solidarité et l'harmonie ; le nombre ne correspond pas au nombre d'États membres.","themeLabel":"Système institutionnel et politique"},{"id":"I-54","theme":"institutions","page":"1789657471721","q":"Qui élit les députés européens ?","options":["Les citoyens de l'Union européenne, au suffrage universel direct depuis 1979","Les parlements nationaux des États membres","Les gouvernements des États membres","Les chefs d'État réunis en Conseil européen"],"correct":0,"why":"Depuis 1979, les députés européens sont élus directement par les citoyens ; chaque État fixe ses modalités (en France, scrutin de liste, tous les 5 ans).","themeLabel":"Système institutionnel et politique"},{"id":"I-55","theme":"institutions","page":"1789657471721","q":"Où est le siège du Parlement européen ?","options":["À Strasbourg, avec des sessions de travail à Bruxelles et un secrétariat à Luxembourg","À Bruxelles uniquement","À Francfort","À La Haye"],"correct":0,"why":"Le traité fixe le siège officiel du Parlement européen à Strasbourg, où se tiennent les sessions plénières ; les commissions travaillent à Bruxelles.","themeLabel":"Système institutionnel et politique"},{"id":"P-01","theme":"valeurs","page":"1789657471738","q":"Quel symbole religieux peut être porté dans une école publique dans le respect de la laïcité ?","options":["Un signe discret, comme une petite médaille ou une croix sobre","Un voile islamique","Une kippa","Un grand crucifix bien visible"],"correct":0,"why":"La loi du 15 mars 2004 interdit les signes religieux ostentatoires à l'école publique ; les signes discrets restent tolérés.","themeLabel":"Principes et valeurs de la République"},{"id":"P-02","theme":"valeurs","page":"1789657471738","q":"Quel terme désigne précisément la haine ou les préjugés contre les Juifs ?","options":["L'antisémitisme","L'islamophobie","La xénophobie","La misogynie"],"correct":0,"why":"L'antisémitisme est un racisme spécifique visant les personnes juives ; il est aggravant pour les infractions et puni par la loi.","themeLabel":"Principes et valeurs de la République"},{"id":"P-03","theme":"valeurs","page":"1789657471738","q":"Quel texte est considéré comme le texte fondateur de la laïcité ?","options":["La loi de séparation des Églises et de l'État de 1905","La loi de 1881 sur la liberté de la presse","La Constitution de 1958","La loi de 2004 sur les signes religieux à l'école"],"correct":0,"why":"La loi du 9 décembre 1905 sépare l'Église et l'État : la République ne reconnaît, ne salarie ni ne subventionne aucun culte (avec une exception en Alsace-Moselle).","themeLabel":"Principes et valeurs de la République"},{"id":"P-04","theme":"valeurs","page":"1789657471738","q":"Quelle institution française doit rester neutre en matière de religion ?","options":["Les services publics et l'État","Les associations culturelles","Les entreprises privées","Les familles"],"correct":0,"why":"L'État et ses agents sont neutres : ils ne peuvent ni favoriser ni défavoriser une religion ; les usagers, eux, sont libres de leurs convictions.","themeLabel":"Principes et valeurs de la République"},{"id":"P-06","theme":"valeurs","page":"1789657471738","q":"À l'école, la charte de la laïcité permet de :","options":["Rappeler les règles de la laïcité et le respect des convictions de chacun","Interdire aux élèves de parler de religion entre eux","Imposer une religion unique dans l'établissement","Organiser des prières dans la cour de récréation"],"correct":0,"why":"La charte de la laïcité à l'école (2013) est affichée dans les établissements : elle explique que l'école est un lieu d'enseignement, et non de pratique religieuse.","themeLabel":"Principes et valeurs de la République"},{"id":"P-07","theme":"valeurs","page":"1789657471738","q":"Qui doit respecter et veiller à la neutralité religieuse dans les services publics ?","options":["Les agents publics, ainsi que leurs responsables hiérarchiques","Les usagers du service public","Les enfants scolarisés","Les entreprises prestataires des collectivités"],"correct":0,"why":"Les agents publics doivent être strictement neutres : ni signe, ni propos, ni pratique religieuse dans l'exercice de leurs fonctions.","themeLabel":"Principes et valeurs de la République"},{"id":"P-08","theme":"valeurs","page":"1789657471738","q":"Une personne déclare ne croire en aucun dieu. On peut dire :","options":["Qu'elle est athée","Qu'elle est agnostique","Qu'elle est croyante mais non pratiquante","Qu'elle est superstitieuse"],"correct":0,"why":"L'athée ne croit en aucun dieu ; l'agnostique considère qu'on ne peut pas trancher la question de l'existence de Dieu.","themeLabel":"Principes et valeurs de la République"},{"id":"P-09","theme":"valeurs","page":"1789657471746","q":"Complétez les paroles de la Marseillaise : « Allons enfants de la patrie… »","options":["« Le jour de gloire est arrivé »","« La victoire est à nous »","« La liberté nous appelle »","« Vive la République et la nation »"],"correct":0,"why":"C'est le premier couplet de La Marseillaise, composée par Rouget de Lisle en 1792 et devenue hymne national en 1879.","themeLabel":"Principes et valeurs de la République"},{"id":"P-10","theme":"valeurs","page":"1789657471746","q":"Dans le cadre d'un entretien d'embauche, que peut-on demander au candidat ?","options":["Ses diplômes, ses compétences et son expérience professionnelle","Sa religion ou ses convictions politiques","Son intention d'avoir des enfants","Son origine ethnique ou sa situation médicale"],"correct":0,"why":"Les questions personnelles (religion, origine, situation familiale, santé) sont interdites : elles constituent une discrimination (art. L.1132-1 du Code du travail).","themeLabel":"Principes et valeurs de la République"},{"id":"P-11","theme":"valeurs","page":"1789657471746","q":"Déclarer ses revenus aux services fiscaux est :","options":["Une obligation légale pour les personnes concernées","Une démarche facultative","Une obligation réservée aux personnes mariées","Une obligation réservée aux propriétaires immobiliers"],"correct":0,"why":"La déclaration de revenus est obligatoire, même lorsque l'impôt dû est nul : elle sert aussi à calculer la prime d'activité, les aides au logement, etc.","themeLabel":"Principes et valeurs de la République"},{"id":"P-12","theme":"valeurs","page":"1789657471746","q":"En France, les impôts permettent de financer les dépenses publiques. Quelle proposition est correcte ?","options":["Ils financent les services publics : écoles, hôpitaux, routes, justice, défense et aides sociales","Ils financent uniquement l'armée et la police","Ils sont reversés aux entreprises privées selon leur chiffre d'affaires","Ils servent uniquement à rémunérer les élus"],"correct":0,"why":"L'impôt est le prix des services publics : il finance l'éducation, la santé, la sécurité, les infrastructures et la solidarité nationale.","themeLabel":"Principes et valeurs de la République"},{"id":"P-13","theme":"valeurs","page":"1789657471746","q":"La liberté d'association est :","options":["Un principe fondamental : on peut créer une association et y adhérer librement (loi de 1901)","Un droit réservé aux entreprises et aux syndicats","Une activité interdite sans autorisation préalable du préfet","Un droit réservé aux personnes majeures de nationalité française"],"correct":0,"why":"La loi du 1er juillet 1901 fonde la liberté d'association : une simple déclaration en préfecture suffit pour créer une association.","themeLabel":"Principes et valeurs de la République"},{"id":"P-14","theme":"valeurs","page":"1789657471746","q":"La liberté d'expression sur les réseaux sociaux en France est :","options":["Garantie comme partout, mais ses abus (menaces, injures, harcèlement, incitation à la haine) sont punis par la loi","Totale et sans aucune limite","Interdite aux personnes mineures","Limitée aux propos politiques"],"correct":0,"why":"Internet n'est pas une zone de non-droit : la diffamation, le cyberharcèlement et l'appel à la haine y sont punis, parfois plus lourdement qu'hors ligne.","themeLabel":"Principes et valeurs de la République"},{"id":"P-15","theme":"valeurs","page":"1789657471746","q":"Lequel de ces prénoms évoque un symbole de la République ?","options":["Marianne","Louis","Napoléon","Henri"],"correct":0,"why":"Marianne, coiffée du bonnet phrygien, incarne la République depuis la Révolution ; son buste est présent dans les mairies.","themeLabel":"Principes et valeurs de la République"},{"id":"P-16","theme":"valeurs","page":"1789657471746","q":"Lequel de ces symboles représente la République française ?","options":["Le drapeau tricolore bleu, blanc, rouge","La couronne royale","La fleur de lys","L'aigle impérial"],"correct":0,"why":"Les symboles officiels (art. 2 de la Constitution) sont le drapeau tricolore, La Marseillaise, la devise « Liberté, Égalité, Fraternité » et le 14 juillet.","themeLabel":"Principes et valeurs de la République"},{"id":"P-18","theme":"valeurs","page":"1789657471746","q":"Lesquels sont des symboles officiels de la République française ?","options":["Le drapeau tricolore, La Marseillaise et la devise « Liberté, Égalité, Fraternité »","La fleur de lys et la couronne","Le drapeau bleu frappé de douze étoiles d'or","Le sceau royal et le sceptre impérial"],"correct":0,"why":"S'y ajoutent Marianne, le 14 juillet (fête nationale), le coq gaulois, le faisceau de licteur et la devise de la République.","themeLabel":"Principes et valeurs de la République"},{"id":"P-20","theme":"valeurs","page":"1789657471746","q":"Quand la Sécurité sociale a-t-elle été établie en France ?","options":["1945","1905","1958","1981"],"correct":0,"why":"Les ordonnances d'octobre 1945 ont créé la Sécurité sociale : elle repose sur la solidarité nationale et couvre maladie, famille, retraite et accidents du travail.","themeLabel":"Principes et valeurs de la République"},{"id":"P-21","theme":"valeurs","page":"1789657471746","q":"Que commémore la fête nationale ?","options":["La prise de la Bastille (1789) et la Fête de la Fédération (1790)","La victoire des Alliés en 1945","La fin de la Première Guerre mondiale","La proclamation de la Vᵉ République"],"correct":0,"why":"Instaurée par la loi du 6 juillet 1880, la fête nationale rappelle la prise de la Bastille et la Fête de la Fédération, symboles de l'unité nationale.","themeLabel":"Principes et valeurs de la République"},{"id":"P-22","theme":"valeurs","page":"1789657471746","q":"Que signifie le mot « fraternité » dans la devise française ?","options":["La solidarité et l'entraide entre les citoyens, le « vivre ensemble »","L'amitié entre la France et les autres pays","La charité religieuse obligatoire","L'obéissance aux représentants de l'État"],"correct":0,"why":"La fraternité prolonge l'égalité : elle appelle à la solidarité concrète entre les citoyens (impôts, protection sociale, entraide).","themeLabel":"Principes et valeurs de la République"},{"id":"P-23","theme":"valeurs","page":"1789657471746","q":"Quel symbole de la République peut-on voir sur les maillots de l'équipe de France de football ?","options":["Le coq gaulois","Marianne","La fleur de lys","Le faisceau de licteur"],"correct":0,"why":"Le coq gaulois est l'emblème sportif de la France ; il existe aussi sous la forme du sceau de la République.","themeLabel":"Principes et valeurs de la République"},{"id":"P-26","theme":"valeurs","page":"1789657471746","q":"Qu'est-ce qu'une liberté ?","options":["La possibilité d'agir sans contrainte injustifiée, dans les limites fixées par la loi","Le droit de faire tout ce que l'on veut, même en nuisant aux autres","Un privilège accordé à certaines catégories de citoyens","Une récompense attribuée aux personnes méritantes"],"correct":0,"why":"Les libertés sont encadrées par la loi afin de garantir les droits de chacun : ma liberté s'arrête là où commence celle des autres.","themeLabel":"Principes et valeurs de la République"},{"id":"P-27","theme":"valeurs","page":"1789657471746","q":"Selon la Constitution, la France est une République…","options":["Indivisible, laïque, démocratique et sociale","Catholique, monarchique et unitaire","Fédérale, libérale et parlementaire","Indivisible, religieuse et militaire"],"correct":0,"why":"Article 1er de la Constitution : elle assure l'égalité devant la loi de tous les citoyens et respecte toutes les croyances.","themeLabel":"Principes et valeurs de la République"},{"id":"P-29","theme":"valeurs","page":"1789657471746","q":"Une des valeurs de la devise républicaine est l'Égalité. Qu'est-ce que cela signifie ?","options":["L'égalité de tous devant la loi, sans distinction d'origine, de religion, de sexe ou de fortune","L'égalité des revenus pour tous les habitants","L'obligation de vivre tous dans le même type de logement","L'égalité des résultats scolaires entre élèves"],"correct":0,"why":"L'égalité est l'égalité en droit : mêmes droits et mêmes devoirs pour tous, ce qui n'interdit pas les politiques de rattrapage (discrimination positive à la française, handicap...).","themeLabel":"Principes et valeurs de la République"},{"id":"P-31","theme":"valeurs","page":"1789657471746","q":"Selon le principe de laïcité, que signifie la neutralité de l'État ?","options":["L'État ne privilégie aucune religion et n'en impose aucune","L'État interdit la pratique de toute religion","L'État finance toutes les religions à parts égales","L'État reconnaît le catholicisme comme religion nationale"],"correct":0,"why":"La neutralité de l'État garantit l'égalité des citoyens quelles que soient leurs convictions ; une exception historique subsiste en Alsace-Moselle.","themeLabel":"Principes et valeurs de la République"},{"id":"P-32","theme":"valeurs","page":"1789657471746","q":"Que peut faire un usager du service public dans une mairie ?","options":["Être accueilli et servi de la même façon que tous les autres usagers, quelle que soit sa religion","Demander à être reçu uniquement par un agent partageant sa religion","Exiger que les agents portent les signes de sa religion","Refuser d'être servi par un agent d'une autre religion"],"correct":0,"why":"L'égalité devant le service public et la neutralité des agents garantissent le même traitement à tous les usagers.","themeLabel":"Principes et valeurs de la République"},{"id":"P-35","theme":"valeurs","page":"1789657471746","q":"Que garantit le principe de laïcité ?","options":["La liberté de conscience et l'égalité de tous les citoyens, croyants ou non","L'interdiction de pratiquer une religion en public","La prééminence d'une religion sur les autres","L'obligation de déclarer sa religion à l'administration"],"correct":0,"why":"La laïcité protège la liberté de croire ou de ne pas croire et assure l'égalité de traitement de tous les citoyens.","themeLabel":"Principes et valeurs de la République"},{"id":"P-36","theme":"valeurs","page":"1789657471746","q":"Quel jour célèbre-t-on officiellement la laïcité en France ?","options":["Le 9 décembre","Le 14 juillet","Le 9 mai","Le 1ᵉʳ mai"],"correct":0,"why":"Le 9 décembre est la Journée nationale de la laïcité, en mémoire de la loi de séparation du 9 décembre 1905.","themeLabel":"Principes et valeurs de la République"}]};
